INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('af253cd9-9b36-5bf8-a757-f8fccd31d481', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 19, 19, 'Then the princes said to Baruch, Go, hide, you and Jeremiah; and let no man know where you are.'),
  ('018ddc08-90c7-5e1b-a5c3-6bc08d4c07d3', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 20, 20, 'They went in to the king into the court; but they had laid up the scroll in the room of Elishama the scribe; and they told all the words in the ears of the king.'),
  ('6bdfb14e-6a70-506f-ac24-5c01b4480e90', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 21, 21, 'So the king sent Jehudi to get the scroll; and he took it out of the room of Elishama the scribe. Jehudi read it in the ears of the king, and in the ears of all the princes who stood beside the king.'),
  ('db0a1e6c-3b6b-5caf-a123-010cce351074', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 22, 22, 'Now the king was sitting in the winter house in the ninth month: and [there was a fire in] the brazier burning before him.'),
  ('35faf505-cd1d-5669-aa47-b2b567820439', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 23, 23, 'It happened, when Jehudi had read three or four leaves, that [the king] cut it with the penknife, and cast it into the fire that was in the brazier, until all the scroll was consumed in the fire that was in the brazier.'),
  ('ed8990bd-87cb-5b5a-a4d0-59c42d92d8cc', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 24, 24, 'They were not afraid, nor tore their garments, neither the king, nor any of his servants who heard all these words.'),
  ('0414d0b7-e9e1-53ee-a0e1-148ce55e5ceb', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 25, 25, 'Moreover Elnathan and Delaiah and Gemariah had made intercession to the king that he would not burn the scroll; but he would not hear them.'),
  ('b6139fad-346f-58da-a5b9-6c9bbefd5ca9', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 26, 26, 'The king commanded Jerahmeel the king''s son, and Seraiah the son of Azriel, and Shelemiah the son of Abdeel, to take Baruch the scribe and Jeremiah the prophet; but Yahweh hid them.'),
  ('479387ff-5db4-561f-a394-5c6bd5c570f0', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 27, 27, 'Then the word of Yahweh came to Jeremiah, after that the king had burned the scroll, and the words which Baruch wrote at the mouth of Jeremiah, saying,'),
  ('4f21dc7f-f782-5998-a373-be87233df1e5', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 28, 28, 'Take again another scroll, and write in it all the former words that were in the first scroll, which Jehoiakim the king of Judah has burned.'),
  ('25658120-2d91-567f-ad3f-fe38a44343f9', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 29, 29, 'Concerning Jehoiakim king of Judah you shall say, Thus says Yahweh: You have burned this scroll, saying, Why have you written therein, saying, The king of Babylon shall certainly come and destroy this land, and shall cause to cease from there man and animal?'),
  ('cb03896f-21cc-5205-a08e-1a3b9bf23ff2', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 30, 30, 'Therefore thus says Yahweh concerning Jehoiakim king of Judah: He shall have none to sit on the throne of David; and his dead body shall be cast out in the day to the heat, and in the night to the frost.'),
  ('b7d88e74-e2b4-5e2c-aa10-c4e105c450f1', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 31, 31, 'I will punish him and his seed and his servants for their iniquity; and I will bring on them, and on the inhabitants of Jerusalem, and on the men of Judah, all the evil that I have pronounced against them, but they didn''t listen.'),
  ('63c75cf4-378a-565a-a77f-a334e6e1e05c', '1ca9bf65-b7c0-5f90-af68-ff07a1b755b8', NULL, 32, 32, 'Then took Jeremiah another scroll, and gave it to Baruch the scribe, the son of Neriah, who wrote therein from the mouth of Jeremiah all the words of the book which Jehoiakim king of Judah had burned in the fire; and there were added besides to them many like words.'),
  ('d18aa1f6-09ed-54f5-a39c-8feec84b92d5', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 1, 1, 'Zedekiah the son of Josiah reigned as king, instead of Coniah the son of Jehoiakim, whom Nebuchadnezzar king of Babylon made king in the land of Judah.'),
  ('1756d015-c32d-5b04-a726-0111a054fdc1', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 2, 2, 'But neither he, nor his servants, nor the people of the land, did listen to the words of Yahweh, which he spoke by the prophet Jeremiah.'),
  ('e6d5f020-73e7-5728-a817-c129fd7cdea0', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 3, 3, 'Zedekiah the king sent Jehucal the son of Shelemiah, and Zephaniah the son of Maaseiah, the priest, to the prophet Jeremiah, saying, Pray now to Yahweh our God for us.'),
  ('ba89602d-303a-597e-aa5d-ddfd3277c971', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 4, 4, 'Now Jeremiah came in and went out among the people; for they had not put him into prison.'),
  ('88ed3cfc-0127-59e3-a174-63b931a0cd44', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 5, 5, 'Pharaoh''s army was come forth out of Egypt; and when the Chaldeans who were besieging Jerusalem heard news of them, they broke up from Jerusalem.'),
  ('e457481d-c8c4-5ed1-a180-0956e756a8a4', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 6, 6, 'Then came the word of Yahweh to the prophet Jeremiah, saying,'),
  ('32dbdac5-0f82-5187-abfb-c5f3c8edecac', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 7, 7, 'Thus says Yahweh, the God of Israel, You shall tell the king of Judah, who sent you to me to inquire of me: Behold, Pharaoh''s army, which is come forth to help you, shall return to Egypt into their own land.'),
  ('04c19fb4-356e-56c7-a963-0913a0e5f7cb', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 8, 8, 'The Chaldeans shall come again, and fight against this city; and they shall take it, and burn it with fire.'),
  ('9c4464b0-f433-5b4c-ac68-aa323e5c573a', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 9, 9, 'Thus says Yahweh, Don''t deceive yourselves, saying, The Chaldeans shall surely depart from us; for they shall not depart.'),
  ('315ce568-3ecf-5eca-a63b-1ad6c4ec4025', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 10, 10, 'For though you had struck the whole army of the Chaldeans who fight against you, and there remained but wounded men among them, yes would they rise up every man in his tent, and burn this city with fire.'),
  ('c4733368-91a6-555b-ab7b-468b06ae26a3', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 11, 11, 'It happened that, when the army of the Chaldeans was broken up from Jerusalem for fear of Pharaoh''s army,'),
  ('1ad69d0c-b246-5a5f-a711-4ad2f19ebb50', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 12, 12, 'then Jeremiah went forth out of Jerusalem to go into the land of Benjamin, to receive his portion there, in the midst of the people.'),
  ('b9550677-3f1a-52f3-ae26-de65091066bb', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 13, 13, 'When he was in the gate of Benjamin, a captain of the guard was there, whose name was Irijah, the son of Shelemiah, the son of Hananiah; and he laid hold on Jeremiah the prophet, saying, You are falling away to the Chaldeans.'),
  ('2fe79710-1abd-5e31-a3a5-2748e797adbc', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 14, 14, 'Then Jeremiah said, It is false; I am not falling away to the Chaldeans. But he didn''t listen to him; so Irijah laid hold on Jeremiah, and brought him to the princes.'),
  ('a5df4229-72f1-505b-ac59-9f184a160cf1', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 15, 15, 'The princes were angry with Jeremiah, and struck him, and put him in prison in the house of Jonathan the scribe; for they had made that the prison.'),
  ('c8cf44b3-b454-5fec-a670-99d17b94b79e', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 16, 16, 'When Jeremiah was come into the dungeon house, and into the cells, and Jeremiah had remained there many days;'),
  ('c129a113-0d41-5ee3-aab3-360a4ea9c5f6', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 17, 17, 'Then Zedekiah the king sent, and fetched him: and the king asked him secretly in his house, and said, Is there any word from Yahweh? Jeremiah said, There is. He said also, You shall be delivered into the hand of the king of Babylon.'),
  ('9ca85065-ed31-535a-a620-9186e91a1ffd', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 18, 18, 'Moreover Jeremiah said to king Zedekiah, Wherein have I sinned against you, or against your servants, or against this people, that you have put me in prison?'),
  ('f4911ab1-56ec-5764-a623-35f5290e9ee4', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 19, 19, 'Where now are your prophets who prophesied to you, saying, The king of Babylon shall not come against you, nor against this land?'),
  ('036fe2ae-9289-579c-afee-aa34c91d3b4f', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 20, 20, 'Now please hear, my lord the king: please let my supplication be presented before you, that you not cause me to return to the house of Jonathan the scribe, lest I die there.'),
  ('17a474d9-fde8-5f49-ab32-c5ccd92d7555', '625c86e5-d60c-5f78-a712-65ff874cfbdc', NULL, 21, 21, 'Then Zedekiah the king commanded, and they committed Jeremiah into the court of the guard; and they gave him daily a loaf of bread out of the bakers'' street, until all the bread in the city was spent. Thus Jeremiah remained in the court of the guard.'),
  ('1e7e05c8-b7e5-576f-a5d4-e2a22b8abe9a', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 1, 1, 'Shephatiah the son of Mattan, and Gedaliah the son of Pashhur, and Jucal the son of Shelemiah, and Pashhur the son of Malchijah, heard the words that Jeremiah spoke to all the people, saying,'),
  ('ecd8f3c7-ae49-55a6-a573-ecd4584d6335', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 2, 2, 'Thus says Yahweh, He who remains in this city shall die by the sword, by the famine, and by the pestilence; but he who goes forth to the Chaldeans shall live, and his life shall be to him for a prey, and he shall live.'),
  ('c6b7284e-494c-5223-a549-58197641c925', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 3, 3, 'Thus says Yahweh, This city shall surely be given into the hand of the army of the king of Babylon, and he shall take it.'),
  ('b8cc11d5-bf05-57f2-a096-c57f2463daa4', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 4, 4, 'Then the princes said to the king, "Please let this man be put to death; because he weakens the hands of the men of war who remain in this city, and the hands of all the people, in speaking such words to them: for this man doesn''t seek the welfare of this people, but the hurt."'),
  ('5d43932b-644a-5275-ab65-601ecb5ab683', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 5, 5, 'Zedekiah the king said, Behold, he is in your hand; for the king is not he who can do anything against you.'),
  ('be17edcc-0b52-5e83-a1db-dd36211882ce', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 6, 6, 'Then took they Jeremiah, and cast him into the dungeon of Malchijah the king''s son, that was in the court of the guard: and they let down Jeremiah with cords. In the dungeon there was no water, but mire; and Jeremiah sank in the mire.'),
  ('7d972421-b264-52fc-a8e8-d8ffed7dd506', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 7, 7, 'Now when Ebedmelech the Ethiopian, a eunuch, who was in the king''s house, heard that they had put Jeremiah in the dungeon (the king then sitting in the gate of Benjamin),'),
  ('197a593a-4232-53d0-a9a4-9dcdcec03c96', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 8, 8, 'Ebedmelech went forth out of the king''s house, and spoke to the king, saying,'),
  ('f17c3e18-084f-5050-ab1d-096340b8ef95', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 9, 9, 'My lord the king, these men have done evil in all that they have done to Jeremiah the prophet, whom they have cast into the dungeon; and he is likely to die in the place where he is, because of the famine; for there is no more bread in the city.'),
  ('448e9074-37c5-5cbf-a2eb-1ac4c47ec2d7', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 10, 10, 'Then the king commanded Ebedmelech the Ethiopian, saying, Take from here thirty men with you, and take up Jeremiah the prophet out of the dungeon, before he dies.'),
  ('82effe2b-9c87-5470-ad5d-0b4afca6aca6', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 11, 11, 'So Ebedmelech took the men with him, and went into the house of the king under the treasury, and took there rags and worn-out garments, and let them down by cords into the dungeon to Jeremiah.'),
  ('4dcbed88-0f5b-5c3e-a9ca-1043df4dd260', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 12, 12, 'Ebedmelech the Ethiopian said to Jeremiah, Put now these rags and worn-out garments under your armpits under the cords. Jeremiah did so.'),
  ('85002404-e899-50ab-ad4e-ae7f0eb27214', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 13, 13, 'So they drew up Jeremiah with the cords, and took him up out of the dungeon: and Jeremiah remained in the court of the guard.'),
  ('6cc2cf61-6d3b-5014-a01c-f669180bd24a', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 14, 14, 'Then Zedekiah the king sent, and took Jeremiah the prophet to him into the third entry that is in the house of Yahweh: and the king said to Jeremiah, I will ask you something. Hide nothing from me.'),
  ('39fa79a6-684c-5003-a894-4a34fc073a5d', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 15, 15, 'Then Jeremiah said to Zedekiah, If I declare it to you, will you not surely put me to death? and if I give you counsel, you will not listen to me.'),
  ('9b99c448-fde6-57b8-a635-04e1076483ad', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 16, 16, 'So Zedekiah the king swore secretly to Jeremiah, saying, As Yahweh lives, who made us this soul, I will not put you to death, neither will I give you into the hand of these men who seek your life.'),
  ('6265dfa2-c865-55ba-a950-1af3bf0205b4', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 17, 17, 'Then Jeremiah said to Zedekiah, Thus says Yahweh, the God of Armies, the God of Israel: If you will go forth to the king of Babylon''s princes, then your soul shall live, and this city shall not be burned with fire; and you shall live, and your house.'),
  ('414bdafe-2ee5-5aac-adfd-2a317b39b1b1', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 18, 18, 'But if you will not go forth to the king of Babylon''s princes, then shall this city be given into the hand of the Chaldeans, and they shall burn it with fire, and you shall not escape out of their hand.'),
  ('19dab46b-47c9-52e8-aa96-d6b0b8983313', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 19, 19, 'Zedekiah the king said to Jeremiah, I am afraid of the Jews who are fallen away to the Chaldeans, lest they deliver me into their hand, and they mock me.'),
  ('13f1a81b-3763-5aeb-a54c-da9050d0c49d', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 20, 20, 'But Jeremiah said, They shall not deliver you. Obey, I beg you, the voice of Yahweh, in that which I speak to you: so it shall be well with you, and your soul shall live.'),
  ('4413445a-ae6f-5eac-a5e6-02d2c08a66c7', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 21, 21, 'But if you refuse to go forth, this is the word that Yahweh has shown me:'),
  ('ad7b92fd-60e4-5c79-aae6-368effbb6852', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 22, 22, 'behold, all the women who are left in the king of Judah''s house shall be brought forth to the king of Babylon''s princes, and those women shall say, Your familiar friends have set you on, and have prevailed over you: [now that] your feet are sunk in the mire, they are turned away back.'),
  ('04dbc3da-5293-5bd6-ad09-7d6025817b19', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 23, 23, 'They shall bring out all your wives and your children to the Chaldeans; and you shall not escape out of their hand, but shall be taken by the hand of the king of Babylon: and you shall cause this city to be burned with fire.'),
  ('e44af0b4-3a9f-54b4-a487-6bdbd7faf1cf', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 24, 24, 'Then Zedekiah said to Jeremiah, Let no man know of these words, and you shall not die.'),
  ('306b7309-ae96-5dde-a89e-5f27090747b7', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 25, 25, 'But if the princes hear that I have talked with you, and they come to you, and tell you, Declare to us now what you have said to the king; don''t hide it from us, and we will not put you to death; also what the king said to you:'),
  ('889661d5-74f5-5f59-ae8e-6c599ad90194', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 26, 26, 'then you shall tell them, I presented my supplication before the king, that he would not cause me to return to Jonathan''s house, to die there.'),
  ('a972012f-0575-5dfb-a3cb-da3280073225', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 27, 27, 'Then came all the princes to Jeremiah, and asked him; and he told them according to all these words that the king had commanded. So they left off speaking with him; for the matter was not perceived.'),
  ('407b283e-8c4d-537d-a06f-d70e59edd5c7', 'dac0faa8-41cc-55d7-a6b1-267fe714a273', NULL, 28, 28, 'So Jeremiah stayed in the court of the guard until the day that Jerusalem was taken.'),
  ('4251f973-7d20-5876-ac14-499290ddb14f', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 1, 1, 'It happened when Jerusalem was taken, (in the ninth year of Zedekiah king of Judah, in the tenth month, came Nebuchadnezzar king of Babylon and all his army against Jerusalem, and besieged it;'),
  ('5b99227e-47af-5cdf-a794-303fbcf5635d', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 2, 2, 'in the eleventh year of Zedekiah, in the fourth month, the ninth day of the month, a breach was made in the city),'),
  ('6fa5febf-c931-5560-acf5-305ba07b578d', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 3, 3, 'that all the princes of the king of Babylon came in, and sat in the middle gate, [to wit], Nergal Sharezer, Samgarnebo, Sarsechim, Rabsaris, Nergal Sharezer, Rabmag, with all the rest of the princes of the king of Babylon.'),
  ('55e894b9-775f-5e6d-a997-f40e5d1b854f', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 4, 4, 'It happened that, when Zedekiah the king of Judah and all the men of war saw them, then they fled, and went forth out of the city by night, by the way of the king''s garden, through the gate between the two walls; and he went out toward the Arabah.'),
  ('631724f3-f6b0-54f0-afff-b7a7b15ed64b', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 5, 5, 'But the army of the Chaldeans pursued after them, and overtook Zedekiah in the plains of Jericho: and when they had taken him, they brought him up to Nebuchadnezzar king of Babylon to Riblah in the land of Hamath; and he gave judgment on him.'),
  ('ed470809-17f2-57db-a3c1-8698ee0185ea', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 6, 6, 'Then the king of Babylon killed the sons of Zedekiah in Riblah before his eyes: also the king of Babylon killed all the nobles of Judah.'),
  ('d51d96f1-07ad-5a9b-a95a-9774f7f31cfc', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 7, 7, 'Moreover he put out Zedekiah''s eyes, and bound him in fetters, to carry him to Babylon.'),
  ('cf43efc7-9fe0-5eeb-a21d-d65ae9d8b2f2', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 8, 8, 'The Chaldeans burned the king''s house, and the houses of the people, with fire, and broke down the walls of Jerusalem.'),
  ('3fe23232-b66d-5fb6-a44e-ea37931a5baf', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 9, 9, 'Then Nebuzaradan the captain of the guard carried away captive into Babylon the residue of the people who remained in the city, the deserters also who fell away to him, and the residue of the people who remained.'),
  ('22474267-741b-51d9-a7dc-2b9bd69eef04', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 10, 10, 'But Nebuzaradan the captain of the guard left of the poor of the people, who had nothing, in the land of Judah, and gave them vineyards and fields at the same time.'),
  ('7fd1ef15-127a-5b4a-a92a-3ba8c2a324f7', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 11, 11, 'Now Nebuchadnezzar king of Babylon commanded Nebuzaradan the captain of the guard concerning Jeremiah, saying,'),
  ('abc2d318-8fa8-5c17-abe4-f829cd74e5d9', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 12, 12, 'Take him, and look well to him, and do him no harm; but do to him even as he shall tell you.'),
  ('c04c810e-a670-5422-a245-54800e23345d', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 13, 13, 'So Nebuzaradan the captain of the guard sent, and Nebushazban, Rabsaris, and Nergal Sharezer, Rabmag, and all the chief officers of the king of Babylon;'),
  ('47dec63c-d451-55b9-ad99-ac285947b93b', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 14, 14, 'they sent, and took Jeremiah out of the court of the guard, and committed him to Gedaliah the son of Ahikam, the son of Shaphan, that he should carry him home: so he lived among the people.'),
  ('38a7f909-1ba7-5493-adff-4122e294b423', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 15, 15, 'Now the word of Yahweh came to Jeremiah, while he was shut up in the court of the guard, saying,'),
  ('db074c0a-7e9b-5323-af35-3f7cffdc75d7', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 16, 16, 'Go, and speak to Ebedmelech the Ethiopian, saying, Thus says Yahweh of Armies, the God of Israel: Behold, I will bring my words on this city for evil, and not for good; and they shall be accomplished before you in that day.'),
  ('e5dab09d-ee5b-53a9-a473-5e4ee7588725', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 17, 17, 'But I will deliver you in that day, says Yahweh; and you shall not be given into the hand of the men of whom you are afraid.'),
  ('e1f05a16-6ec4-52ae-a285-eb95e371f33d', '7d68c5e0-36e1-5fae-ae79-4956c6547537', NULL, 18, 18, 'For I will surely save you, and you shall not fall by the sword, but your life shall be for a prey to you; because you have put your trust in me, says Yahweh.'),
  ('645d0cb5-b29d-565c-a58e-a5b651e0a1df', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 1, 1, 'The word which came to Jeremiah from Yahweh, after that Nebuzaradan the captain of the guard had let him go from Ramah, when he had taken him being bound in chains among all the captives of Jerusalem and Judah, who were carried away captive to Babylon.'),
  ('016aab51-9578-53b8-adbd-714979ea8dc2', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 2, 2, 'The captain of the guard took Jeremiah, and said to him, Yahweh your God pronounced this evil on this place;'),
  ('f25dd4de-8178-5199-a238-5f3cb2fb68a8', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 3, 3, 'and Yahweh has brought it, and done according as he spoke: because you have sinned against Yahweh, and have not obeyed his voice, therefore this thing has come on you.'),
  ('6c4adf02-eefd-5e4b-a434-2ad5bf77fb3d', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 4, 4, 'Now, behold, I release you this day from the chains which are on your hand. If it seems good to you to come with me into Babylon, come, and I will take care of you; but if it seems bad to you to come with me into Babylon, don''t: behold, all the land is before you; where it seems good and right to you to go, there go.'),
  ('b1b9d6aa-a30b-5f00-a17b-cf41dbaef3a0', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 5, 5, 'Now while he was not yet gone back, Go back then, [said he], to Gedaliah the son of Ahikam, the son of Shaphan, whom the king of Babylon has made governor over the cities of Judah, and dwell with him among the people; or go wherever it seems right to you to go. So the captain of the guard gave him food and a present, and let him go.'),
  ('ca1864b9-a710-51e7-aed5-aa3fa7807b72', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 6, 6, 'Then went Jeremiah to Gedaliah the son of Ahikam to Mizpah, and lived with him among the people who were left in the land.'),
  ('1d2ed054-bd7a-5a67-acb5-82d9a2dcba8c', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 7, 7, 'Now when all the captains of the forces who were in the fields, even they and their men, heard that the king of Babylon had made Gedaliah the son of Ahikam governor in the land, and had committed to him men, and women, and children, and of the poorest of the land, of those who were not carried away captive to Babylon;'),
  ('e6ae417f-9456-5a7e-a008-cba7840a047c', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 8, 8, 'then they came to Gedaliah to Mizpah, [to wit], Ishmael the son of Nethaniah, and Johanan and Jonathan the sons of Kareah, and Seraiah the son of Tanhumeth, and the sons of Ephai the Netophathite, and Jezaniah the son of the Maacathite, they and their men.'),
  ('494d7e97-4593-5e1b-aa1e-e76bf522196c', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 9, 9, 'Gedaliah the son of Ahikam the son of Shaphan swore to them and to their men, saying, Don''t be afraid to serve the Chaldeans: dwell in the land, and serve the king of Babylon, and it shall be well with you.'),
  ('c4605c63-485d-5dc9-a471-0da40342086c', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 10, 10, 'As for me, behold, I will dwell at Mizpah, to stand before the Chaldeans who shall come to us: but you, gather wine and summer fruits and oil, and put them in your vessels, and dwell in your cities that you have taken.'),
  ('67f7d89c-84ce-5103-ad96-bceefbff0de7', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 11, 11, 'Likewise when all the Jews who were in Moab, and among the children of Ammon, and in Edom, and who were in all the countries, heard that the king of Babylon had left a remnant of Judah, and that he had set over them Gedaliah the son of Ahikam, the son of Shaphan;'),
  ('8296d500-6243-54d7-ab86-e0da7702693d', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 12, 12, 'then all the Jews returned out of all places where they were driven, and came to the land of Judah, to Gedaliah, to Mizpah, and gathered wine and summer fruits very much.'),
  ('aba02911-96e6-5e22-a711-a3388b0a9258', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 13, 13, 'Moreover Johanan the son of Kareah, and all the captains of the forces who were in the fields, came to Gedaliah to Mizpah,'),
  ('6b19f383-3180-5193-a985-ff74e12086cd', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 14, 14, 'and said to him, Do you know that Baalis the king of the children of Ammon has sent Ishmael the son of Nethaniah to take your life? But Gedaliah the son of Ahikam didn''t believe them.'),
  ('79a747eb-ca7f-5b86-aa19-e67e0738a8e0', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 15, 15, 'Then Johanan the son of Kareah spoke to Gedaliah in Mizpah secretly, saying, Please let me go, and I will kill Ishmael the son of Nethaniah, and no man shall know it: why should he take your life, that all the Jews who are gathered to you should be scattered, and the remnant of Judah perish?'),
  ('4753339e-b37c-579f-a8ce-9fc1eaa30761', '69f388ab-e19d-5b7e-a8c5-802aaf59cca3', NULL, 16, 16, 'But Gedaliah the son of Ahikam said to Johanan the son of Kareah, You shall not do this thing; for you speak falsely of Ishmael.'),
  ('52b4eaee-2f33-52c3-aab4-3dfa3cbf873b', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 1, 1, 'Now it happened in the seventh month, that Ishmael the son of Nethaniah, the son of Elishama, of the seed royal and [one of] the chief officers of the king, and ten men with him, came to Gedaliah the son of Ahikam to Mizpah; and there they ate bread together in Mizpah.'),
  ('52e77bcf-4bfb-5d82-a84d-1e400ed30e76', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 2, 2, 'Then arose Ishmael the son of Nethaniah, and the ten men who were with him, and struck Gedaliah the son of Ahikam the son of Shaphan with the sword, and killed him, whom the king of Babylon had made governor over the land.'),
  ('72286a08-2e9e-5d3a-ab90-cc6eaed1e678', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 3, 3, 'Ishmael also killed all the Jews who were with him, [to wit], with Gedaliah, at Mizpah, and the Chaldeans who were found there, the men of war.'),
  ('bf95c1dd-e3fc-5902-a4c5-73162a6fea18', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 4, 4, 'It happened the second day after he had killed Gedaliah, and no man knew it,'),
  ('5a6d2d8f-e026-52fd-aa06-7bebe9a2c366', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 5, 5, 'that there came men from Shechem, from Shiloh, and from Samaria, even eighty men, having their beards shaved and their clothes torn, and having cut themselves, with meal offerings and frankincense in their hand, to bring them to the house of Yahweh.'),
  ('58403af7-2baf-5a2e-ac0e-e1125ff8de8e', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 6, 6, 'Ishmael the son of Nethaniah went forth from Mizpah to meet them, weeping all along as he went: and it happened, as he met them, he said to them, Come to Gedaliah the son of Ahikam.'),
  ('1516d287-4b7f-5eda-aba8-31d96d5b12ef', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 7, 7, 'It was so, when they came into the midst of the city, that Ishmael the son of Nethaniah killed them, [and cast them] into the midst of the pit, he, and the men who were with him.'),
  ('7650d93c-229c-58f3-a0d5-208196f7b2e6', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 8, 8, 'But ten men were found among those who said to Ishmael, Don''t kill us; for we have stores hidden in the field, of wheat, and of barley, and of oil, and of honey. So he stopped, and didn''t kill them among their brothers.'),
  ('1b4a2dfb-82df-52f6-aba8-c783c6e1d433', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 9, 9, 'Now the pit in which Ishmael cast all the dead bodies of the men whom he had killed, by the side of Gedaliah (the same was who which Asa the king had made for fear of Baasha king of Israel), Ishmael the son of Nethaniah filled it with those who were killed.'),
  ('e929dfc7-1871-5675-a4ba-02cb604b926d', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 10, 10, 'Then Ishmael carried away captive all the residue of the people who were in Mizpah, even the king''s daughters, and all the people who remained in Mizpah, whom Nebuzaradan the captain of the guard had committed to Gedaliah the son of Ahikam; Ishmael the son of Nethaniah carried them away captive, and departed to go over to the children of Ammon.'),
  ('a3c07592-67f7-53d8-a0a0-cabca8b04913', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 11, 11, 'But when Johanan the son of Kareah, and all the captains of the forces who were with him, heard of all the evil that Ishmael the son of Nethaniah had done,'),
  ('92b22493-59ec-5c85-aaec-e21836a80015', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 12, 12, 'then they took all the men, and went to fight with Ishmael the son of Nethaniah, and found him by the great waters that are in Gibeon.'),
  ('66856b4e-7042-5f8d-a276-be2e111dd102', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 13, 13, 'Now it happened that, when all the people who were with Ishmael saw Johanan the son of Kareah, and all the captains of the forces who were with him, then they were glad.'),
  ('f018b308-167b-551c-ac5f-97a90a68dc86', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 14, 14, 'So all the people who Ishmael had carried away captive from Mizpah turned about and came back, and went to Johanan the son of Kareah.'),
  ('bd8f542c-b3ec-587c-a290-2eac95e17ee8', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 15, 15, 'But Ishmael the son of Nethaniah escaped from Johanan with eight men, and went to the children of Ammon.'),
  ('8822dd90-4e9b-5f8a-ae5b-d0edaac77e34', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 16, 16, 'Then took Johanan the son of Kareah, and all the captains of the forces who were with him, all the remnant of the people whom he had recovered from Ishmael the son of Nethaniah, from Mizpah, after that he had killed Gedaliah the son of Ahikam, [to wit], the men of war, and the women, and the children, and the eunuchs, whom he had brought back from Gibeon:'),
  ('4d4b50a5-9206-50ac-a65f-b20c2af08d88', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 17, 17, 'and they departed, and lived in Geruth Chimham, which is by Bethlehem, to go to enter into Egypt,'),
  ('e6ad6768-e62e-52ee-af37-a46bafc2b494', 'd7488276-e7ff-547f-a4c1-b0156c167475', NULL, 18, 18, 'because of the Chaldeans; for they were afraid of them, because Ishmael the son of Nethaniah had killed Gedaliah the son of Ahikam, whom the king of Babylon made governor over the land.'),
  ('4fd29c70-25ce-5e26-a69b-547f90d77aca', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 1, 1, 'Then all the captains of the forces, and Johanan the son of Kareah, and Jezaniah the son of Hoshaiah, and all the people from the least even to the greatest, came near,'),
  ('d2abb5b8-bdd0-5ce2-ab90-896023b96a57', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 2, 2, 'and said to Jeremiah the prophet, Please let our supplication be presented before you, and pray for us to Yahweh your God, even for all this remnant; for we are left but a few of many, as your eyes do see us:'),
  ('0bab3d63-5212-58f2-ab60-74fd54a301b5', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 3, 3, 'that Yahweh your God may show us the way in which we should walk, and the thing that we should do.'),
  ('f36f28a2-0ad7-5bee-a630-5cf01422beaa', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 4, 4, 'Then Jeremiah the prophet said to them, I have heard you; behold, I will pray to Yahweh your God according to your words; and it shall happen that whatever thing Yahweh shall answer you, I will declare it to you; I will keep nothing back from you.'),
  ('87440f6d-23b7-5f3b-a1b7-8d9b73873a62', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 5, 5, 'Then they said to Jeremiah, Yahweh be a true and faithful witness among us, if we don''t do according to all the word with which Yahweh your God shall send you to us.'),
  ('282c681d-a31b-521d-a2ff-86ae6b724056', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 6, 6, 'Whether it be good, or whether it be evil, we will obey the voice of Yahweh our God, to whom we send you; that it may be well with us, when we obey the voice of Yahweh our God.'),
  ('1030585a-2d01-5690-a916-7b43de4085ee', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 7, 7, 'It happened after ten days, that the word of Yahweh came to Jeremiah.'),
  ('52ab3eb6-f99d-5a9b-a019-29e2e222839f', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 8, 8, 'Then called he Johanan the son of Kareah, and all the captains of the forces who were with him, and all the people from the least even to the greatest,'),
  ('d0dccc2a-4414-576c-a1f4-6fa1ffa4df89', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 9, 9, 'and said to them, Thus says Yahweh, the God of Israel, to whom you sent me to present your supplication before him:'),
  ('901d89e4-df21-51d6-adfc-1e0838aa0242', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 10, 10, 'If you will still live in this land, then will I build you, and not pull you down, and I will plant you, and not pluck you up; for I grieve over the distress that I have brought on you.'),
  ('05bc8d44-de07-5e8b-aabe-769f1458d999', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 11, 11, 'Don''t be afraid of the king of Babylon, of whom you are afraid; don''t be afraid of him, says Yahweh: for I am with you to save you, and to deliver you from his hand.'),
  ('86e101b7-b136-51a0-afcb-49943581935d', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 12, 12, 'I will grant you mercy, that he may have mercy on you, and cause you to return to your own land.'),
  ('8621b80c-b644-5a91-ac5c-e91d1467e318', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 13, 13, 'But if you say, We will not dwell in this land; so that you don''t obey the voice of Yahweh your God,'),
  ('1176d5d8-6daa-5b97-adfc-4d097040a2ee', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 14, 14, 'saying, No; but we will go into the land of Egypt, where we shall see no war, nor hear the sound of the trumpet, nor have hunger of bread; and there will we dwell:'),
  ('d1e0f27f-8597-5730-aee9-9bce6414b96f', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 15, 15, 'now therefore hear the word of Yahweh, O remnant of Judah: Thus says Yahweh of Armies, the God of Israel, If you indeed set your faces to enter into Egypt, and go to live there;'),
  ('ed95e2ed-a615-513d-a9fe-3e45aeb22258', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 16, 16, 'then it shall happen, that the sword, which you fear, shall overtake you there in the land of Egypt; and the famine, about which you are afraid, shall follow close behind you there in Egypt; and there you shall die.'),
  ('edc72c13-9cfc-5902-ad06-a50b5d68e629', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 17, 17, 'So shall it be with all the men who set their faces to go into Egypt to live there: they shall die by the sword, by the famine, and by the pestilence; and none of them shall remain or escape from the evil that I will bring on them.'),
  ('1080e8f3-cf94-567c-ab74-e1e91ea3aab5', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 18, 18, 'For thus says Yahweh of Armies, the God of Israel: As my anger and my wrath has been poured forth on the inhabitants of Jerusalem, so shall my wrath be poured forth on you, when you shall enter into Egypt; and you shall be an object of horror, and an astonishment, and a curse, and a reproach; and you shall see this place no more.'),
  ('6e6ad43f-2305-5aec-a545-5e9c89541611', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 19, 19, 'Yahweh has spoken concerning you, remnant of Judah, Don''t you go into Egypt: know certainly that I have testified to you this day.'),
  ('7c4c87b3-cd64-5341-a611-247ff181080f', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 20, 20, 'For you have dealt deceitfully against your own souls; for you sent me to Yahweh your God, saying, Pray for us to Yahweh our God; and according to all that Yahweh our God shall say, so declare to us, and we will do it:'),
  ('a3ac59fa-fcbf-5720-aa47-1529a623fab1', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 21, 21, 'and I have this day declared it to you; but you have not obeyed the voice of Yahweh your God in anything for which he has sent me to you.'),
  ('d50e6c7b-b798-50c9-a28e-f1f984ebaad7', 'd3e7a53a-a1c9-5325-a237-87bcfedbb495', NULL, 22, 22, 'Now therefore know certainly that you shall die by the sword, by the famine, and by the pestilence, in the place where you desire to go to live there.'),
  ('1fa4df52-113b-5998-ade0-d0077df80a1e', 'b1e75d9b-5b72-5631-a0b7-136d65bc38f0', NULL, 1, 1, 'It happened that, when Jeremiah had made an end of speaking to all the people all the words of Yahweh their God, with which Yahweh their God had sent him to them, even all these words,'),
  ('af179f03-b4be-50b2-ae59-37510893b39a', 'b1e75d9b-5b72-5631-a0b7-136d65bc38f0', NULL, 2, 2, 'then spoke Azariah the son of Hoshaiah, and Johanan the son of Kareah, and all the proud men, saying to Jeremiah, You speak falsely: Yahweh our God has not sent you to say, You shall not go into Egypt to live there;'),
  ('d642df4d-1bc9-5702-a3da-09484629ab43', 'b1e75d9b-5b72-5631-a0b7-136d65bc38f0', NULL, 3, 3, 'but Baruch the son of Neriah sets you on against us, to deliver us into the hand of the Chaldeans, that they may put us to death, and carry us away captive to Babylon.'),
  ('c7429057-c0b8-5378-a3d1-194dd8a64f4e', 'b1e75d9b-5b72-5631-a0b7-136d65bc38f0', NULL, 4, 4, 'So Johanan the son of Kareah, and all the captains of the forces, and all the people, didn''t obey the voice of Yahweh, to dwell in the land of Judah.'),
  ('b956b999-0eea-58ff-aa29-c39bfc933aa9', 'b1e75d9b-5b72-5631-a0b7-136d65bc38f0', NULL, 5, 5, 'But Johanan the son of Kareah, and all the captains of the forces, took all the remnant of Judah, who were returned from all the nations where they had been driven, to live in the land of Judah;'),
  ('f7f00483-3b29-5c90-a7fd-54799f40cd31', 'b1e75d9b-5b72-5631-a0b7-136d65bc38f0', NULL, 6, 6, 'the men, and the women, and the children, and the king''s daughters, and every person who Nebuzaradan the captain of the guard had left with Gedaliah the son of Ahikam, the son of Shaphan; and Jeremiah the prophet, and Baruch the son of Neriah;'),
  ('7cf5982d-7de6-5665-a0fe-b2493f0e9ea9', 'b1e75d9b-5b72-5631-a0b7-136d65bc38f0', NULL, 7, 7, 'and they came into the land of Egypt; for they didn''t obey the voice of Yahweh: and they came to Tahpanhes.'),
  ('6cf90e29-f340-5277-a1a1-e9ca445c164e', 'b1e75d9b-5b72-5631-a0b7-136d65bc38f0', NULL, 8, 8, 'Then came the word of Yahweh to Jeremiah in Tahpanhes, saying,'),
  ('fbdb2cd2-de1c-5af4-acd5-c281dd0cb9db', 'b1e75d9b-5b72-5631-a0b7-136d65bc38f0', NULL, 9, 9, 'Take great stones in your hand, and hide them in mortar in the brick work, which is at the entry of Pharaoh''s house in Tahpanhes, in the sight of the men of Judah;'),
  ('7dcc15a2-1f0a-5dd0-a54b-e74c40106c45', 'b1e75d9b-5b72-5631-a0b7-136d65bc38f0', NULL, 10, 10, 'and tell them, Thus says Yahweh of Armies, the God of Israel: Behold, I will send and take Nebuchadnezzar the king of Babylon, my servant, and will set his throne on these stones that I have hidden; and he shall spread his royal pavilion over them.'),
  ('8de842fd-eba9-5996-aac3-ded6fd01f7f2', 'b1e75d9b-5b72-5631-a0b7-136d65bc38f0', NULL, 11, 11, 'He shall come, and shall strike the land of Egypt; such as are for death [shall be given] to death, and such as are for captivity to captivity, and such as are for the sword to the sword.'),
  ('4f8475bd-d58b-5820-a82b-deac0ee96811', 'b1e75d9b-5b72-5631-a0b7-136d65bc38f0', NULL, 12, 12, 'I will kindle a fire in the houses of the gods of Egypt; and he shall burn them, and carry them away captive: and he shall array himself with the land of Egypt, as a shepherd puts on his garment; and he shall go forth from there in peace.'),
  ('7cbdfb06-8949-5b13-ac4b-37bce2d7fac5', 'b1e75d9b-5b72-5631-a0b7-136d65bc38f0', NULL, 13, 13, 'He shall also break the pillars of Beth Shemesh, that is in the land of Egypt; and the houses of the gods of Egypt shall he burn with fire.'),
  ('4d63fb64-7845-5b4b-adc8-684e2ee70833', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 1, 1, 'The word that came to Jeremiah concerning all the Jews who lived in the land of Egypt, who lived at Migdol, and at Tahpanhes, and at Memphis, and in the country of Pathros, saying,'),
  ('95cc8212-1afd-5771-a6ad-779dad71ab03', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 2, 2, 'Thus says Yahweh of Armies, the God of Israel: You have seen all the evil that I have brought on Jerusalem, and on all the cities of Judah; and behold, this day they are a desolation, and no man dwells therein,'),
  ('0bbd06c1-5777-537b-ab06-ee6389641ee2', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 3, 3, 'because of their wickedness which they have committed to provoke me to anger, in that they went to burn incense, [and] to serve other gods, that they didn''t know, neither they, nor you, nor your fathers.'),
  ('1d997ce6-8883-5ad6-a234-24a265940b98', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 4, 4, 'However I sent to you all my servants the prophets, rising up early and sending them, saying, Oh, don''t do this abominable thing that I hate.'),
  ('ef065c46-3dcb-5cd3-a574-719f27eeedb9', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 5, 5, 'But they didn''t listen, nor inclined their ear to turn from their wickedness, to burn no incense to other gods.'),
  ('0aca2883-ae3a-5f9c-a8a5-9227f13f61c6', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 6, 6, 'Therefore my wrath and my anger was poured forth, and was kindled in the cities of Judah and in the streets of Jerusalem; and they are wasted and desolate, as it is this day.'),
  ('a6170706-427e-5162-ad02-e7aa7d4cbc36', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 7, 7, 'Therefore now thus says Yahweh, the God of Armies, the God of Israel: Why do you commit great evil against your own souls, to cut off from yourselves man and woman, infant and nursing child out of the midst of Judah, to leave yourselves none remaining;'),
  ('8c649b8f-90cb-58b7-ae8d-44f1c201c845', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 8, 8, 'in that you provoke me to anger with the works of your hands, burning incense to other gods in the land of Egypt, where you have gone to live; that you may be cut off, and that you may be a curse and a reproach among all the nations of the earth?'),
  ('5c8bd9b4-c446-511d-a879-6aff850548a1', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 9, 9, 'Have you forgotten the wickedness of your fathers, and the wickedness of the kings of Judah, and the wickedness of their wives, and your own wickedness, and the wickedness of your wives which they committed in the land of Judah, and in the streets of Jerusalem?'),
  ('52b5896b-ea12-5064-a985-bfecdfc82ab8', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 10, 10, 'They are not humbled even to this day, neither have they feared, nor walked in my law, nor in my statutes, that I set before you and before your fathers.'),
  ('d7e1508d-8bfb-5610-afde-c86f3bc91f4c', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 11, 11, 'Therefore thus says Yahweh of Armies, the God of Israel: Behold, I will set my face against you for evil, even to cut off all Judah.'),
  ('27187eb0-a488-50cb-af99-0f0956e8532a', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 12, 12, 'I will take the remnant of Judah, that have set their faces to go into the land of Egypt to live there, and they shall all be consumed; in the land of Egypt shall they fall; they shall be consumed by the sword and by the famine; they shall die, from the least even to the greatest, by the sword and by the famine; and they shall be an object of horror, [and] an astonishment, and a curse, and a reproach.'),
  ('18b1eddf-180c-5434-ac93-b9b86f498178', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 13, 13, 'For I will punish those who dwell in the land of Egypt, as I have punished Jerusalem, by the sword, by the famine, and by the pestilence;'),
  ('5be8426b-ab02-5242-aab9-99bfcd9406e9', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 14, 14, 'so that none of the remnant of Judah, who have gone into the land of Egypt to live there, shall escape or be left, to return into the land of Judah, to which they have a desire to return to dwell there: for none shall return save such as shall escape.'),
  ('67b556d1-cb23-50ba-a701-a58cb46e3423', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 15, 15, 'Then all the men who knew that their wives burned incense to other gods, and all the women who stood by, a great assembly, even all the people who lived in the land of Egypt, in Pathros, answered Jeremiah, saying,'),
  ('4187b999-6ee5-5d1c-a44b-2c51444a68ec', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 16, 16, 'As for the word that you have spoken to us in the name of Yahweh, we will not listen to you.'),
  ('50fd82b4-98bb-589e-a6a4-0c3245e40d91', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 17, 17, 'But we will certainly perform every word that is gone forth out of our mouth, to burn incense to the queen of the sky, and to pour out drink offerings to her, as we have done, we and our fathers, our kings and our princes, in the cities of Judah, and in the streets of Jerusalem; for then had we plenty of food, and were well, and saw no evil.'),
  ('9d810f0c-d10a-5f5d-a3af-f5acc9d3aa98', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 18, 18, 'But since we left off burning incense to the queen of the sky, and pouring out drink offerings to her, we have wanted all things, and have been consumed by the sword and by the famine.'),
  ('89673d4b-73c1-5fc2-a850-34884e6b35bf', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 19, 19, 'When we burned incense to the queen of the sky, and poured out drink offerings to her, did we make her cakes to worship her, and pour out drink offerings to her, without our husbands?'),
  ('bb380d70-45c6-55d3-a3bb-2725177921e6', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 20, 20, 'Then Jeremiah said to all the people, to the men, and to the women, even to all the people who had given him an answer, saying,'),
  ('6c95038c-df90-58c3-a6bf-d12c1f1760aa', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 21, 21, 'The incense that you burned in the cities of Judah, and in the streets of Jerusalem, you and your fathers, your kings and your princes, and the people of the land, didn''t Yahweh remember them, and didn''t it come into his mind?'),
  ('7bcbb44b-92d1-5f5e-a0ed-1d39cc5f916c', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 22, 22, 'so that Yahweh could no longer bear, because of the evil of your doings, and because of the abominations which you have committed; therefore your land has become a desolation, and an astonishment, and a curse, without inhabitant, as it is this day.'),
  ('1a5fcc1f-cbad-5469-ae34-155f99c13abe', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 23, 23, 'Because you have burned incense, and because you have sinned against Yahweh, and have not obeyed the voice of Yahweh, nor walked in his law, nor in his statutes, nor in his testimonies; therefore this evil has happened to you, as it is this day.'),
  ('79d8b3eb-4074-5e14-a224-35b1c0c68998', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 24, 24, 'Moreover Jeremiah said to all the people, and to all the women, Hear the word of Yahweh, all Judah who are in the land of Egypt:'),
  ('d1aa142b-d2e5-5aad-a841-800cb93280de', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 25, 25, 'Thus says Yahweh of Armies, the God of Israel, saying, You and your wives have both spoken with your mouths, and with your hands have fulfilled it, saying, We will surely perform our vows that we have vowed, to burn incense to the queen of the sky, and to pour out drink offerings to her: establish then your vows, and perform your vows.'),
  ('c417d310-21b7-50c2-aac7-18dfd514fa14', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 26, 26, 'Therefore hear the word of Yahweh, all Judah who dwell in the land of Egypt: Behold, I have sworn by my great name, says Yahweh, that my name shall no more be named in the mouth of any man of Judah in all the land of Egypt, saying, As the Lord Yahweh lives.'),
  ('c0e0ce8a-a3a8-5457-ac49-19def14a9b4c', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 27, 27, 'Behold, I watch over them for evil, and not for good; and all the men of Judah who are in the land of Egypt shall be consumed by the sword and by the famine, until there be an end of them.'),
  ('ea46e576-c38a-5a35-a09c-3bb88c41cab7', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 28, 28, 'Those who escape the sword shall return out of the land of Egypt into the land of Judah, few in number; and all the remnant of Judah, who have gone into the land of Egypt to live there, shall know whose word shall stand, mine, or theirs.'),
  ('d28e8635-55ea-5cbc-aa83-58d88db5c7a5', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 29, 29, 'This shall be the sign to you, says Yahweh, that I will punish you in this place, that you may know that my words shall surely stand against you for evil:'),
  ('1e412cd9-8a62-56c6-a0c5-7b9154a5b3fc', '760fab65-bc20-50a2-a641-f9d5901927a3', NULL, 30, 30, 'Thus says Yahweh, Behold, I will give Pharaoh Hophra king of Egypt into the hand of his enemies, and into the hand of those who seek his life; as I gave Zedekiah king of Judah into the hand of Nebuchadnezzar king of Babylon, who was his enemy, and sought his life.'),
  ('7f51403c-57d8-516b-adfc-13d8477ac7c6', '7270cf83-9383-584f-a67e-705f9e3d3f35', NULL, 1, 1, 'The message that Jeremiah the prophet spoke to Baruch the son of Neriah, when he wrote these words in a book at the mouth of Jeremiah, in the fourth year of Jehoiakim the son of Josiah, king of Judah, saying,'),
  ('6304b83a-3d29-5ead-ad3b-e9f03f551ec7', '7270cf83-9383-584f-a67e-705f9e3d3f35', NULL, 2, 2, 'Thus says Yahweh, the God of Israel, to you, Baruch:'),
  ('da33e8e8-7bcb-5a84-ab27-a558b9737703', '7270cf83-9383-584f-a67e-705f9e3d3f35', NULL, 3, 3, 'You said, Woe is me now! for Yahweh has added sorrow to my pain; I am weary with my groaning, and I find no rest.'),
  ('9dacc8e8-f36d-5cbd-a07c-9024f007fb2a', '7270cf83-9383-584f-a67e-705f9e3d3f35', NULL, 4, 4, 'You shall tell him, Thus says Yahweh: Behold, that which I have built will I break down, and that which I have planted I will pluck up; and this in the whole land.'),
  ('41a31b17-6893-5447-ac6a-f73cedfb6864', '7270cf83-9383-584f-a67e-705f9e3d3f35', NULL, 5, 5, 'Do you seek great things for yourself? Don''t seek them; for, behold, I will bring evil on all flesh, says Yahweh; but your life will I give to you for a prey in all places where you go.'),
  ('70912d75-0d40-5178-a4d0-efd56753a716', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 1, 1, 'The word of Yahweh which came to Jeremiah the prophet concerning the nations.'),
  ('af9e681d-a917-50c2-a183-668d226e690c', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 2, 2, 'Of Egypt: concerning the army of Pharaoh Necoh king of Egypt, which was by the river Euphrates in Carchemish, which Nebuchadnezzar king of Babylon struck in the fourth year of Jehoiakim the son of Josiah, king of Judah.'),
  ('d0da8fad-93c0-53ee-ad68-de7439f2bc7d', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 3, 3, 'Prepare the buckler and shield, and draw near to battle!'),
  ('3b6226f7-de6c-5865-ad4f-027076fbe4ad', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 4, 4, 'Harness the horses, and get up, you horsemen, and stand forth with your helmets; furbish the spears, put on the coats of mail.'),
  ('91614585-ea5f-5985-aa5d-5b450613cccd', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 5, 5, 'Why have I seen it? they are dismayed and are turned backward; and their mighty ones are beaten down, and have fled apace, and don''t look back: terror is on every side, says Yahweh.'),
  ('ca56be88-558d-5e3c-aee2-b0f36d1b50a5', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 6, 6, 'Don''t let the swift flee away, nor the mighty man escape; in the north by the river Euphrates have they stumbled and fallen.'),
  ('53103197-1faf-59d5-ad51-d9b05aaacff8', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 7, 7, 'Who is this who rises up like the Nile, whose waters toss themselves like the rivers?'),
  ('5aad237c-3178-5600-a382-e037131b99c3', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 8, 8, 'Egypt rises up like the Nile, and his waters toss themselves like the rivers: and he says, I will rise up, I will cover the earth; I will destroy cities and its inhabitants.'),
  ('26a01a40-0fc6-5eb0-af70-ee66883c5409', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 9, 9, 'Go up, you horses; and rage, you chariots; and let the mighty men go forth: Cush and Put, who handle the shield; and the Ludim, who handle and bend the bow.'),
  ('242bb9ed-0a2b-59b0-ac82-29d7e0afa80d', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 10, 10, 'For that day is [a day] of the Lord, Yahweh of Armies, a day of vengeance, that he may avenge him of his adversaries: and the sword shall devour and be satiate, and shall drink its fill of their blood; for the Lord, Yahweh of Armies, has a sacrifice in the north country by the river Euphrates.'),
  ('93953678-881e-5228-ae94-eecdd82d3014', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 11, 11, 'Go up into Gilead, and take balm, virgin daughter of Egypt: in vain do you use many medicines; there is no healing for you.'),
  ('44982085-98aa-5e57-a7bb-7676694df215', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 12, 12, 'The nations have heard of your shame, and the earth is full of your cry; for the mighty man has stumbled against the mighty, they are fallen both of them together.'),
  ('7ed2dc39-a3f0-5e44-a200-5bb89923679f', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 13, 13, 'The word that Yahweh spoke to Jeremiah the prophet, how that Nebuchadnezzar king of Babylon should come and strike the land of Egypt.'),
  ('ca581082-3e97-5365-a5a0-5e4f7d356781', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 14, 14, 'Declare in Egypt, and publish in Migdol, and publish in Memphis and in Tahpanhes: say, Stand forth, and prepare; for the sword has devoured around you.'),
  ('992f67d0-f4f9-509e-abba-e8e1a31be9ee', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 15, 15, 'Why are your strong ones swept away? they didn''t stand, because Yahweh did drive them.'),
  ('18a78db7-3bde-54c8-aaef-238a93dd71ee', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 16, 16, 'He made many to stumble, yes, they fell one on another: and they said, Arise, and let us go again to our own people, and to the land of our birth, from the oppressing sword.'),
  ('3798960f-3a3e-5f81-a007-6faa4751a094', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 17, 17, 'They cried there, Pharaoh king of Egypt is but a noise; he has let the appointed time pass by.'),
  ('cfa02e4e-5f6e-5dac-ab5c-b842f5281e05', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 18, 18, 'As I live, says the King, whose name is Yahweh of Armies, surely like Tabor among the mountains, and like Carmel by the sea, so shall he come.'),
  ('187cbaed-80e1-5141-a306-5af5833df5b3', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 19, 19, 'You daughter who dwells in Egypt, furnish yourself to go into captivity; for Memphis shall become a desolation, and shall be burnt up, without inhabitant.'),
  ('f123318a-343b-5072-a22f-43dfd1d4c3ed', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 20, 20, 'Egypt is a very beautiful heifer; [but] destruction out of the north is come, it is come.'),
  ('d45ff8aa-9af7-5e7d-a24c-754944a79a2d', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 21, 21, 'Also her hired men in the midst of her are like calves of the stall; for they also are turned back, they are fled away together, they didn''t stand: for the day of their calamity is come on them, the time of their visitation.'),
  ('e8f53515-fab8-5ff5-a7cc-ec8a81b8261c', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 22, 22, 'The sound of it shall go like the serpent; for they shall march with an army, and come against her with axes, as wood cutters.'),
  ('59c17008-a86b-5bfe-a012-7744ed707a3f', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 23, 23, 'They shall cut down her forest, says Yahweh, though it can''t be searched; because they are more than the locusts, and are innumerable.'),
  ('43b887b0-7bec-57d0-a7c4-eb20cfbbf655', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 24, 24, 'The daughter of Egypt shall be disappointed; she shall be delivered into the hand of the people of the north.'),
  ('0d28e9ba-208d-5b61-a30d-c463cd973c00', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 25, 25, 'Yahweh of Armies, the God of Israel, says: Behold, I will punish Amon of No, and Pharaoh, and Egypt, with her gods, and her kings; even Pharaoh, and those who trust in him:'),
  ('1117fb54-dc95-5ab0-a160-495b303fe547', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 26, 26, 'and I will deliver them into the hand of those who seek their lives, and into the hand of Nebuchadnezzar king of Babylon, and into the hand of his servants; and afterwards it shall be inhabited, as in the days of old, says Yahweh.'),
  ('2326a59b-109b-5906-a3ba-2935539d7936', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 27, 27, 'But don''t you be afraid, Jacob my servant, neither be dismayed, Israel: for, behold, I will save you from afar, and your seed from the land of their captivity; and Jacob shall return, and shall be quiet and at ease, and none shall make him afraid.'),
  ('eea81b5d-3777-5498-ae82-6e1cc2a05cdf', '5810b560-6de3-5637-a3b8-874d517d00d3', NULL, 28, 28, 'Don''t you be afraid, O Jacob my servant, says Yahweh; for I am with you: for I will make a full end of all the nations where I have driven you; but I will not make a full end of you, but I will correct you in measure, and will in no way leave you unpunished.'),
  ('4b83ba2a-93ff-5cc7-ac20-3cdf30a9cb20', 'feb2e7f5-f192-55f1-ac73-c76189d277f9', NULL, 1, 1, 'The word of Yahweh that came to Jeremiah the prophet concerning the Philistines, before that Pharaoh struck Gaza.'),
  ('2693e419-3c5b-54df-af89-26b77ee1e615', 'feb2e7f5-f192-55f1-ac73-c76189d277f9', NULL, 2, 2, 'Thus says Yahweh: Behold, waters rise up out of the north, and shall become an overflowing stream, and shall overflow the land and all that is therein, the city and those who dwell therein; and the men shall cry, and all the inhabitants of the land shall wail.'),
  ('a8a88e39-0590-535d-aabb-995d3d4f5415', 'feb2e7f5-f192-55f1-ac73-c76189d277f9', NULL, 3, 3, 'At the noise of the stamping of the hoofs of his strong ones, at the rushing of his chariots, at the rumbling of his wheels, the fathers don''t look back to their children for feebleness of hands;'),
  ('27d15a11-eaf1-5026-a555-b96225049ae1', 'feb2e7f5-f192-55f1-ac73-c76189d277f9', NULL, 4, 4, 'because of the day that comes to destroy all the Philistines, to cut off from Tyre and Sidon every helper who remains: for Yahweh will destroy the Philistines, the remnant of the isle of Caphtor.'),
  ('7ecb0b98-5983-5935-acb6-0d555eb225e5', 'feb2e7f5-f192-55f1-ac73-c76189d277f9', NULL, 5, 5, 'Baldness is come on Gaza; Ashkelon is brought to nothing, the remnant of their valley: how long will you cut yourself?'),
  ('658451fb-0167-5543-aecd-b8ac8858b0ba', 'feb2e7f5-f192-55f1-ac73-c76189d277f9', NULL, 6, 6, 'You sword of Yahweh, how long will it be before you be quiet? Put up yourself into your scabbard; rest, and be still.'),
  ('d275b9dd-ea47-5465-a347-0d217570d7d2', 'feb2e7f5-f192-55f1-ac73-c76189d277f9', NULL, 7, 7, 'How can you be quiet, since Yahweh has given you a command? Against Ashkelon, and against the seashore, there has he appointed it.'),
  ('c1dfc144-afb2-559c-a409-a7f106e47faa', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 1, 1, 'Of Moab. Thus says Yahweh of Armies, the God of Israel: Woe to Nebo! for it is laid waste; Kiriathaim is disappointed, it is taken; Misgab is put to shame and broken down.'),
  ('aacc340b-bd42-53c9-a8a0-4df0844b5aa4', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 2, 2, 'The praise of Moab is no more; in Heshbon they have devised evil against her: Come, and let us cut her off from being a nation. You also, Madmen, shall be brought to silence: the sword shall pursue you.'),
  ('d0c6593e-b2bd-55fa-a818-237f592491d1', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 3, 3, 'The sound of a cry from Horonaim, desolation and great destruction!'),
  ('0290e4cb-1d3b-53ee-abb1-1cf0f552de05', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 4, 4, 'Moab is destroyed; her little ones have caused a cry to be heard.'),
  ('81def9be-f339-5e10-a42c-f60f33239d4b', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 5, 5, 'For by the ascent of Luhith with continual weeping shall they go up; for at the descent of Horonaim they have heard the distress of the cry of destruction.'),
  ('3e7a105a-2e0a-531c-a68f-38da656e902d', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 6, 6, 'Flee, save your lives, and be like the heath in the wilderness.'),
  ('bdaf9187-1460-50cd-a3c8-2ec112381761', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 7, 7, 'For, because you have trusted in your works and in your treasures, you also shall be taken: and Chemosh shall go forth into captivity, his priests and his princes together.'),
  ('629effe2-a41a-50ea-aca5-01b637e43b4e', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 8, 8, 'The destroyer shall come on every city, and no city shall escape; the valley also shall perish, and the plain shall be destroyed; as Yahweh has spoken.'),
  ('4d6c4d4b-d2e1-5984-afac-378ad8321a1a', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 9, 9, 'Give wings to Moab, that she may fly and get her away: and her cities shall become a desolation, without any to dwell therein.'),
  ('47f90de9-81d4-5509-a66f-3f4ad17b0060', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 10, 10, 'Cursed is he who does the work of Yahweh negligently; and cursed is he who keeps back his sword from blood.'),
  ('9d991a99-6176-50e4-a464-9dccfab47dfa', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 11, 11, 'Moab has been at ease from his youth, and he has settled on his lees, and has not been emptied from vessel to vessel, neither has he gone into captivity: therefore his taste remains in him, and his scent is not changed.'),
  ('435634dc-ac15-51b6-afa8-057ed8b62868', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 12, 12, 'Therefore, behold, the days come, says Yahweh, that I will send to him those who pour off, and they shall pour him off; and they shall empty his vessels, and break their bottles in pieces.'),
  ('8639b8e5-7821-54e8-ab44-6540d1446bdc', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 13, 13, 'Moab shall be ashamed of Chemosh, as the house of Israel was ashamed of Bethel their confidence.'),
  ('f49a9732-84dc-5c40-a835-642319d98e6a', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 14, 14, 'How do you say, We are mighty men, and valiant men for the war?'),
  ('32afb0f2-1e0d-595c-a813-875a935692c2', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 15, 15, 'Moab is laid waste, and they are gone up into his cities, and his chosen young men are gone down to the slaughter, says the King, whose name is Yahweh of Armies.'),
  ('dded6483-1c8a-5877-af4c-9569f817e088', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 16, 16, 'The calamity of Moab is near to come, and his affliction hurries fast.'),
  ('d3b032de-42ce-5123-a75c-a0e26c00f9ba', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 17, 17, 'All you who are around him, bemoan him, and all you who know his name; say, How is the strong staff broken, the beautiful rod!'),
  ('6d17f22b-1ebe-5fd0-aec1-950149dc0c3b', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 18, 18, 'You daughter who dwells in Dibon, come down from your glory, and sit in thirst; for the destroyer of Moab has come up against you, he has destroyed your strongholds.'),
  ('6c5b6939-f552-5433-a06c-619f8445848d', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 19, 19, 'Inhabitant of Aroer, stand by the way, and watch: ask him who flees, and her who escapes; say, What has been done?'),
  ('b2ec1fc6-1239-562e-acae-00e295398863', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 20, 20, 'Moab is disappointed; for it is broken down: wail and cry; tell it by the Arnon, that Moab is laid waste.'),
  ('a64f7ea5-8deb-501c-a133-063d75f403b6', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 21, 21, 'Judgment is come on the plain country, on Holon, and on Jahzah, and on Mephaath,'),
  ('a3b89ebc-9b39-52db-a12c-be6b2ef4cdd9', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 22, 22, 'and on Dibon, and on Nebo, and on Beth Diblathaim,'),
  ('8633689a-77ab-52f6-a272-52ebdf3d3c3d', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 23, 23, 'and on Kiriathaim, and on Beth Gamul, and on Beth Meon,'),
  ('096b1c6a-55a3-5acf-ac08-7d611d52227e', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 24, 24, 'and on Kerioth, and on Bozrah, and on all the cities of the land of Moab, far or near.'),
  ('907e3705-d6ad-5a4c-aae9-0e8de2ce34fc', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 25, 25, 'The horn of Moab is cut off, and his arm is broken, says Yahweh.'),
  ('8fbbef2c-540b-5fe9-aa4f-0d6887b02f32', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 26, 26, 'Make him drunken; for he magnified himself against Yahweh: and Moab shall wallow in his vomit, and he also shall be in derision.'),
  ('ed5ed041-1e0c-5c41-a4fb-67961be5d783', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 27, 27, 'For wasn''t Israel a derision to you? was he found among thieves? for as often as you speak of him, you shake your head.'),
  ('942490d1-e720-5d38-af69-67145eef1aaa', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 28, 28, 'You inhabitants of Moab, leave the cities, and dwell in the rock; and be like the dove that makes her nest over the mouth of the abyss.'),
  ('6e6c49d8-a48d-5c5c-a2ef-0b12f66a9ddf', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 29, 29, 'We have heard of the pride of Moab, [that] he is very proud; his loftiness, and his pride, and his arrogance, and the haughtiness of his heart.'),
  ('ec392990-58db-555c-a911-5a2b9d938937', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 30, 30, 'I know his wrath, says Yahweh, that it is nothing; his boastings have worked nothing.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('39d52d6c-e91e-5119-a9ed-7e06fab400d7', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 31, 31, 'Therefore will I wail for Moab; yes, I will cry out for all Moab: for the men of Kir Heres shall they mourn.'),
  ('40189116-a12e-59dc-ac9f-900a8ebf6ccc', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 32, 32, 'With more than the weeping of Jazer will I weep for you, vine of Sibmah: your branches passed over the sea, they reached even to the sea of Jazer: on your summer fruits and on your vintage the destroyer is fallen.'),
  ('5dba637a-086c-5778-a4ae-a6fdd62aaa5d', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 33, 33, 'Gladness and joy is taken away from the fruitful field and from the land of Moab; and I have caused wine to cease from the wine presses: none shall tread with shouting; the shouting shall be no shouting.'),
  ('94882d2b-7b6b-5d1a-a07d-b2e671d81842', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 34, 34, 'From the cry of Heshbon even to Elealeh, even to Jahaz have they uttered their voice, from Zoar even to Horonaim, to Eglath Shelishiyah: for the waters of Nimrim also shall become desolate.'),
  ('aa4b6110-4f2a-5261-a7ee-6fa196c2de4c', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 35, 35, 'Moreover I will cause to cease in Moab, says Yahweh, him who offers in the high place, and him who burns incense to his gods.'),
  ('06229d62-77ee-5cae-a7b0-47a35cc740b8', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 36, 36, 'Therefore my heart sounds for Moab like pipes, and my heart sounds like pipes for the men of Kir Heres: therefore the abundance that he has gotten is perished.'),
  ('2ac003bb-be2f-5afc-a613-7d52a5d6a828', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 37, 37, 'For every head is bald, and every beard clipped: on all the hands are cuttings, and on the waist sackcloth.'),
  ('e1f27e17-cfc9-5591-a664-1bfe317bf6bb', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 38, 38, 'On all the housetops of Moab and in its streets there is lamentation every where; for I have broken Moab like a vessel in which none delights, says Yahweh.'),
  ('a36bad9a-12e6-5eb3-a63a-8937c9fa0141', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 39, 39, 'How is it broken down! [how] do they wail! how has Moab turned the back with shame! so shall Moab become a derision and a terror to all who are around him.'),
  ('e8afa060-b8ae-51f0-ae3f-d3563933169c', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 40, 40, 'For thus says Yahweh: Behold, he shall fly as an eagle, and shall spread out his wings against Moab.'),
  ('e5027ab5-cab7-5983-a3d0-8923b2982e03', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 41, 41, 'Kerioth is taken, and the strongholds are seized, and the heart of the mighty men of Moab at that day shall be as the heart of a woman in her pangs.'),
  ('0d5de60d-c61f-5e88-a497-20fb9471aef4', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 42, 42, 'Moab shall be destroyed from being a people, because he has magnified himself against Yahweh.'),
  ('45bfc7ab-788c-5c56-aa22-de4dd79a2bb5', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 43, 43, 'Fear, and the pit, and the snare, are on you, inhabitant of Moab, says Yahweh.'),
  ('c48b2e47-b702-5920-a1a6-2fef4d44c059', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 44, 44, 'He who flees from the fear shall fall into the pit; and he who gets up out of the pit shall be taken in the snare: for I will bring on him, even on Moab, the year of their visitation, says Yahweh.'),
  ('1365ee8f-7b37-56df-ac4d-afb4d4fce4ce', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 45, 45, 'Those who fled stand without strength under the shadow of Heshbon; for a fire is gone forth out of Heshbon, and a flame from the midst of Sihon, and has devoured the corner of Moab, and the crown of the head of the tumultuous ones.'),
  ('f6f35f01-fcc2-59f3-a18f-ca01405a348a', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 46, 46, 'Woe to you, O Moab! the people of Chemosh is undone; for your sons are taken away captive, and your daughters into captivity.'),
  ('4dd3548c-6c3d-5453-ae35-e0fe4265c139', '0742565d-7c59-555b-ad8b-a66827a5f202', NULL, 47, 47, 'Yet will I bring back the captivity of Moab in the latter days, says Yahweh. Thus far is the judgment of Moab.'),
  ('88d54aef-eca7-5e8e-aae1-d72f0c4ade08', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 1, 1, 'Of the children of Ammon. Thus says Yahweh: Has Israel no sons? has he no heir? why then does Malcam possess Gad, and his people well in its cities?'),
  ('7ee93947-e50c-5479-a932-f6815cb7064b', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 2, 2, 'Therefore, behold, the days come, says Yahweh, that I will cause an alarm of war to be heard against Rabbah of the children of Ammon; and it shall become a desolate heap, and her daughters shall be burned with fire: then shall Israel possess those who did possess him, says Yahweh.'),
  ('b0a480fd-f2c6-5dbf-a4be-c35515aa4a5e', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 3, 3, 'Wail, Heshbon, for Ai is laid waste; cry, you daughters of Rabbah, clothe yourself in sackcloth: lament, and run back and forth among the fences; for Malcam shall go into captivity, his priests and his princes together.'),
  ('3e42c6f0-10ad-5281-a3dc-f9898fda1f5b', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 4, 4, 'Why do you glory in the valleys, your flowing valley, backsliding daughter? who trusted in her treasures, [saying], Who shall come to me?'),
  ('d805c87a-b3fe-50ed-a833-f46ea5521a58', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 5, 5, 'Behold, I will bring a fear on you, says the Lord, Yahweh of Armies, from all who are around you; and you shall be driven out every man right forth, and there shall be none to gather together the fugitives.'),
  ('7ac00e7c-7cae-51ce-ad5d-fc6f502109e7', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 6, 6, 'But afterward I will bring back the captivity of the children of Ammon, says Yahweh.'),
  ('954f49a9-5ebe-5f55-aa2d-fcf1a26b6c96', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 7, 7, 'Of Edom. Thus says Yahweh of Armies: Is wisdom no more in Teman? is counsel perished from the prudent? is their wisdom vanished?'),
  ('d6bdd510-7749-553e-a0d6-b7de4ca2a833', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 8, 8, 'Flee, turn back, dwell in the depths, inhabitants of Dedan; for I will bring the calamity of Esau on him, the time that I shall visit him.'),
  ('05da86ea-180d-5f22-a77c-e8e46cb92735', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 9, 9, 'If grape gatherers came to you, would they not leave some gleaning grapes? if thieves by night, wouldn''t they destroy until they had enough?'),
  ('a1eb10d4-f29f-5ec1-ad6a-4d6948f25c9d', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 10, 10, 'But I have made Esau bare, I have uncovered his secret places, and he shall not be able to hide himself: his seed is destroyed, and his brothers, and his neighbors; and he is no more.'),
  ('9e620080-9bef-5edc-a302-be8751911656', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 11, 11, 'Leave your fatherless children, I will preserve them alive; and let your widows trust in me.'),
  ('6f7514e3-6202-5dc0-acd5-c0e9a857ea49', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 12, 12, 'For thus says Yahweh: Behold, they to whom it didn''t pertain to drink of the cup shall certainly drink; and are you he who shall altogether go unpunished? You shall not go unpunished, but you shall surely drink.'),
  ('8d894c53-f70f-5b65-aa3b-1977e12d6e83', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 13, 13, 'For I have sworn by myself, says Yahweh, that Bozrah shall become an astonishment, a reproach, a waste, and a curse; and all its cities shall be perpetual wastes.'),
  ('09e9c434-1604-50d0-a7b3-95cec8cb95e2', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 14, 14, 'I have heard news from Yahweh, and an ambassador is sent among the nations, [saying], Gather yourselves together, and come against her, and rise up to the battle.'),
  ('ae174d74-6210-59a4-a856-9ef8c29ce90c', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 15, 15, 'For, behold, I have made you small among the nations, and despised among men.'),
  ('cc42539b-bdad-56ac-a031-8407c4540ac1', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 16, 16, 'As for your terror, the pride of your heart has deceived you, O you who dwell in the clefts of the rock, who hold the height of the hill: though you should make your nest as high as the eagle, I will bring you down from there, says Yahweh.'),
  ('16667ae3-b795-560c-abce-365082162e32', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 17, 17, 'Edom shall become an astonishment: everyone who passes by it shall be astonished, and shall hiss at all its plagues.'),
  ('7d3bf230-0930-5f7a-ad72-c08dbe09e130', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 18, 18, 'As in the overthrow of Sodom and Gomorrah and the neighbor cities of it, says Yahweh, no man shall dwell there, neither shall any son of man live therein.'),
  ('bfe5f8e0-9318-5181-a9e9-a4ad64f0a2a8', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 19, 19, 'Behold, he shall come up like a lion from the pride of the Jordan against the strong habitation: for I will suddenly make them run away from it; and whoever is chosen, him will I appoint over it: for who is like me? and who will appoint me a time? and who is the shepherd who will stand before me?'),
  ('ab43fc82-81f9-5304-a913-f24c496634de', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 20, 20, 'Therefore hear the counsel of Yahweh, that he has taken against Edom; and his purposes, that he has purposed against the inhabitants of Teman: Surely they shall drag them away, [even] the little ones of the flock; surely he shall make their habitation desolate over them.'),
  ('8a5ce04a-3344-5747-a413-cb82199b5c50', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 21, 21, 'The earth trembles at the noise of their fall; there is a cry, the noise which is heard in the Red Sea.'),
  ('18bc4380-b0ea-5d8b-a61a-8451e8e591cd', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 22, 22, 'Behold, he shall come up and fly as the eagle, and spread out his wings against Bozrah: and the heart of the mighty men of Edom at that day shall be as the heart of a woman in her pangs.'),
  ('1097f348-c4f3-5681-a660-d3f8240d1b08', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 23, 23, 'Of Damascus. Hamath is confounded, and Arpad; for they have heard evil news, they are melted away: there is sorrow on the sea; it can''t be quiet.'),
  ('a0851920-8b65-5cc1-afa7-597764294871', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 24, 24, 'Damascus has grown feeble, she turns herself to flee, and trembling has seized on her: anguish and sorrows have taken hold of her, as of a woman in travail.'),
  ('5408e129-1eed-5d75-aed2-f5e19694c645', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 25, 25, 'How is the city of praise not forsaken, the city of my joy?'),
  ('83040dfe-1db9-547a-a52c-0729238b6170', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 26, 26, 'Therefore her young men shall fall in her streets, and all the men of war shall be brought to silence in that day, says Yahweh of Armies.'),
  ('5cf1fdef-3459-5445-a847-184a06f01571', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 27, 27, 'I will kindle a fire in the wall of Damascus, and it shall devour the palaces of Ben Hadad.'),
  ('69be3c84-321f-53ad-ae77-d4252ea71f0d', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 28, 28, 'Of Kedar, and of the kingdoms of Hazor, which Nebuchadnezzar king of Babylon struck. Thus says Yahweh: Arise, go up to Kedar, and destroy the children of the east.'),
  ('a3ac45eb-7c75-5e4d-a6b1-ccfc43ffe3a6', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 29, 29, 'Their tents and their flocks shall they take; they shall carry away for themselves their curtains, and all their vessels, and their camels; and they shall cry to them, Terror on every side!'),
  ('acf0ffd2-4f1e-5f87-a02f-31c9839d3629', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 30, 30, 'Flee, wander far off, dwell in the depths, you inhabitants of Hazor, says Yahweh; for Nebuchadnezzar king of Babylon has taken counsel against you, and has conceived a purpose against you.'),
  ('ab4bdb28-0c75-57e6-a214-47fedaa1e9e1', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 31, 31, 'Arise, go up to a nation that is at ease, that dwells without care, says Yahweh; that have neither gates nor bars, that dwell alone.'),
  ('8dc872a8-7a60-5cec-aeac-bbb95dee9da1', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 32, 32, 'Their camels shall be a booty, and the multitude of their livestock a spoil: and I will scatter to all winds those who have the corners [of their hair] cut off; and I will bring their calamity from every side of them, says Yahweh.'),
  ('6f32d74a-c442-5720-a62b-e0bd71012fe9', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 33, 33, 'Hazor shall be a dwelling place of jackals, a desolation forever: no man shall dwell there, neither shall any son of man live therein.'),
  ('20f47852-7668-578f-ae31-0dadb4ea89b3', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 34, 34, 'The word of Yahweh that came to Jeremiah the prophet concerning Elam, in the beginning of the reign of Zedekiah king of Judah, saying,'),
  ('bf1ff9a4-65a9-5e41-ab17-a520ccff7ef2', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 35, 35, 'Thus says Yahweh of Armies: Behold, I will break the bow of Elam, the chief of their might.'),
  ('705e7409-3012-5616-a928-06c2410c558c', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 36, 36, 'On Elam will I bring the four winds from the four quarters of the sky, and will scatter them toward all those winds; and there shall be no nation where the outcasts of Elam shall not come.'),
  ('42d8aaa2-c165-54f1-a9f7-d096404e8cf7', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 37, 37, 'I will cause Elam to be dismayed before their enemies, and before those who seek their life; and I will bring evil on them, even my fierce anger, says Yahweh; and I will send the sword after them, until I have consumed them;'),
  ('1c29d4a4-9c97-51dc-a066-1fdc0b28ae7d', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 38, 38, 'and I will set my throne in Elam, and will destroy from there king and princes, says Yahweh.'),
  ('29f39eba-fe0f-5468-a8a9-b30d402db93e', '0d9f7379-9bfb-5575-a550-4a914f982a44', NULL, 39, 39, 'But it shall happen in the latter days, that I will bring back the captivity of Elam, says Yahweh.'),
  ('4eda6295-8e85-58b9-ad43-19034b52e4b3', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 1, 1, 'The word that Yahweh spoke concerning Babylon, concerning the land of the Chaldeans, by Jeremiah the prophet.'),
  ('9c70ccca-97b8-50f1-acfe-ffd04fc9a21d', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 2, 2, 'Declare among the nations and publish, and set up a standard; publish, and don''t conceal: say, Babylon is taken, Bel is disappointed, Merodach is dismayed; her images are disappointed, her idols are dismayed.'),
  ('736c23a1-24db-5b64-a0df-b6b78039763a', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 3, 3, 'For out of the north there comes up a nation against her, which shall make her land desolate, and none shall dwell therein: they are fled, they are gone, both man and animal.'),
  ('924c553c-a701-5e2d-a5b7-ac6c2560df0a', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 4, 4, 'In those days, and in that time, says Yahweh, the children of Israel shall come, they and the children of Judah together; they shall go on their way weeping, and shall seek Yahweh their God.'),
  ('f1af2d2b-b383-5b2d-a0a0-b91ac1af75ea', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 5, 5, 'They shall inquire concerning Zion with their faces turned toward it, [saying], Come, and join yourselves to Yahweh in an everlasting covenant that shall not be forgotten.'),
  ('ba8981ab-865d-5079-a38a-1d787fdb89c2', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 6, 6, 'My people have been lost sheep: their shepherds have caused them to go astray; they have turned them away on the mountains; they have gone from mountain to hill; they have forgotten their resting place.'),
  ('ca57415f-a0e9-50ed-a3a4-40057e530c8b', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 7, 7, 'All who found them have devoured them; and their adversaries said, We are not guilty, because they have sinned against Yahweh, the habitation of righteousness, even Yahweh, the hope of their fathers.'),
  ('b1c6d40d-aacf-544a-a9f7-be3f4b72e2e2', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 8, 8, 'Flee out of the midst of Babylon, and go forth out of the land of the Chaldeans, and be as the male goats before the flocks.'),
  ('30420996-25cc-52cc-ac52-278743ea1046', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 9, 9, 'For, behold, I will stir up and cause to come up against Babylon a company of great nations from the north country; and they shall set themselves in array against her; from there she shall be taken: their arrows shall be as of an expert mighty man; none shall return in vain.'),
  ('0d1b9066-f6ac-5d53-aaeb-9a10242c5eaa', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 10, 10, 'Chaldea shall be a prey: all who prey on her shall be satisfied, says Yahweh.'),
  ('4d561533-0796-5130-afb1-55a91d3e7c80', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 11, 11, 'Because you are glad, because you rejoice, O you who plunder my heritage, because you are wanton as a heifer that treads out [the grain], and neigh as strong horses;'),
  ('3bbe9390-99eb-545c-a085-d7a8edf5f1ae', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 12, 12, 'your mother shall be utterly disappointed; she who bore you shall be confounded: behold, she shall be the least of the nations, a wilderness, a dry land, and a desert.'),
  ('3ba55320-63c3-5644-a3ce-c127724efcdd', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 13, 13, 'Because of the wrath of Yahweh she shall not be inhabited, but she shall be wholly desolate: everyone who goes by Babylon shall be astonished, and hiss at all her plagues.'),
  ('be70a959-ee6c-5cc3-a756-f7c788f6baa9', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 14, 14, 'Set yourselves in array against Babylon all around, all you who bend the bow; shoot at her, spare no arrows: for she has sinned against Yahweh.'),
  ('4f4f439d-9044-5662-ae07-237c566e5ef2', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 15, 15, 'Shout against her all around: she has submitted herself; her bulwarks are fallen, her walls are thrown down; for it is the vengeance of Yahweh: take vengeance on her; as she has done, do to her.'),
  ('922cf467-f596-5302-a2c5-fda002d9d6d2', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 16, 16, 'Cut off the sower from Babylon, and him who handles the sickle in the time of harvest: for fear of the oppressing sword they shall turn everyone to his people, and they shall flee everyone to his own land.'),
  ('39b15ab2-c34f-57b7-ada1-8a3093cb6acc', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 17, 17, 'Israel is a hunted sheep; the lions have driven him away: first, the king of Assyria devoured him; and now at last Nebuchadnezzar king of Babylon has broken his bones.'),
  ('b8e80c48-cdde-5cc8-a677-79a2a96cfcbf', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 18, 18, 'Therefore thus says Yahweh of Armies, the God of Israel: Behold, I will punish the king of Babylon and his land, as I have punished the king of Assyria.'),
  ('e52c9e66-e2a7-5041-a4a3-e4faf687a2f7', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 19, 19, 'I will bring Israel again to his pasture, and he shall feed on Carmel and Bashan, and his soul shall be satisfied on the hills of Ephraim and in Gilead.'),
  ('a08f8c1b-a853-5bef-a632-76ee30a5846f', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 20, 20, 'In those days, and in that time, says Yahweh, the iniquity of Israel shall be sought for, and there shall be none; and the sins of Judah, and they shall not be found: for I will pardon them whom I leave as a remnant.'),
  ('4103d87a-fccf-5f83-a6e1-49f99d440d41', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 21, 21, 'Go up against the land of Merathaim, even against it, and against the inhabitants of Pekod: kill and utterly destroy after them, says Yahweh, and do according to all that I have commanded you.'),
  ('85ccf1e9-9f86-5e8d-af74-ad1184bee186', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 22, 22, 'A sound of battle is in the land, and of great destruction.'),
  ('848a964e-5513-5127-a737-562af91060c5', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 23, 23, 'How is the hammer of the whole earth cut apart and broken! how is Babylon become a desolation among the nations!'),
  ('c87707bf-0a70-52dc-a94b-96d57eed1383', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 24, 24, 'I have laid a snare for you, and you are also taken, Babylon, and you weren''t aware: you are found, and also caught, because you have striven against Yahweh.'),
  ('7dc00b39-b26c-506b-a036-311c3c59a179', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 25, 25, 'Yahweh has opened his armory, and has brought forth the weapons of his indignation; for the Lord, Yahweh of Armies, has a work [to do] in the land of the Chaldeans.'),
  ('5dfabc5b-5814-54b0-ad76-f98eed789c51', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 26, 26, 'Come against her from the utmost border; open her storehouses; cast her up as heaps, and destroy her utterly; let nothing of her be left.'),
  ('d6d303bc-19ed-5f17-a29a-2c962ce9c984', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 27, 27, 'Kill all her bulls; let them go down to the slaughter: woe to them! for their day is come, the time of their visitation.'),
  ('154d963a-88d3-5bd0-a2e0-f93b39d1225e', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 28, 28, 'The voice of those who flee and escape out of the land of Babylon, to declare in Zion the vengeance of Yahweh our God, the vengeance of his temple.'),
  ('35abc27d-c016-50cc-af1c-ed5545a1c3ee', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 29, 29, 'Call together the archers against Babylon, all those who bend the bow; encamp against her all around; let none of it escape: recompense her according to her work; according to all that she has done, do to her; for she has been proud against Yahweh, against the Holy One of Israel.'),
  ('f4275d61-3401-5660-af70-5592de755e94', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 30, 30, 'Therefore her young men will fall in her streets, and all her men of war will be brought to silence in that day, says Yahweh.'),
  ('6d97375b-820a-5e47-af52-9aa1c33b1c66', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 31, 31, 'Behold, I am against you, you proud one, says the Lord, Yahweh of Armies; for your day has come, the time that I will visit you.'),
  ('3c55a84f-2373-56a1-a5e3-49f84c63e71c', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 32, 32, 'The proud one shall stumble and fall, and none shall raise him up; and I will kindle a fire in his cities, and it shall devour all who are around him.'),
  ('2f204ecc-6d4d-5ed3-a86b-03be2b68f31b', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 33, 33, 'Thus says Yahweh of Armies: The children of Israel and the children of Judah are oppressed together; and all who took them captive hold them fast; they refuse to let them go.'),
  ('f773af0a-8723-5d24-a51f-67861cf56f82', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 34, 34, 'Their Redeemer is strong; Yahweh of Armies is his name: he will thoroughly plead their cause, that he may give rest to the earth, and disquiet the inhabitants of Babylon.'),
  ('0a044cfe-f8da-5a81-a41f-92cc43dc17de', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 35, 35, 'A sword is on the Chaldeans, says Yahweh, and on the inhabitants of Babylon, and on her princes, and on her wise men.'),
  ('acbf48cd-520d-573b-a2b7-7f6fb1c05413', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 36, 36, 'A sword is on the boasters, and they shall become fools; a sword is on her mighty men, and they shall be dismayed.'),
  ('7520dcdd-635b-553a-adf6-4a413633b712', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 37, 37, 'A sword is on their horses, and on their chariots, and on all the mixed people who are in the midst of her; and they shall become as women: a sword is on her treasures, and they shall be robbed.'),
  ('05f8833c-9754-5c68-af33-1af0a19806b8', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 38, 38, 'A drought is on her waters, and they shall be dried up; for it is a land of engraved images, and they are mad over idols.'),
  ('97fea380-339e-5ba2-a029-a0ec0fc83818', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 39, 39, 'Therefore the wild animals of the desert with the wolves shall dwell there, and the ostriches shall dwell therein: and it shall be no more inhabited forever; neither shall it be lived in from generation to generation.'),
  ('9fe74621-f1cc-5cb5-ac1b-0ee08dd6c981', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 40, 40, 'As when God overthrew Sodom and Gomorrah and the neighbor cities of it, says Yahweh, so shall no man dwell there, neither shall any son of man live therein.'),
  ('2b99f75a-db30-5471-abd3-219e924b926d', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 41, 41, 'Behold, a people comes from the north; and a great nation and many kings shall be stirred up from the uttermost parts of the earth.'),
  ('9e5a1e11-41c6-54d7-a668-f51b4d500fc6', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 42, 42, 'They lay hold on bow and spear; they are cruel, and have no mercy; their voice roars like the sea; and they ride on horses, everyone set in array, as a man to the battle, against you, daughter of Babylon.'),
  ('83a9cd27-fe19-5a78-ae54-4b68b1086616', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 43, 43, 'The king of Babylon has heard the news of them, and his hands wax feeble: anguish has taken hold of him, [and] pangs as of a woman in travail.'),
  ('d627796f-7ee7-59a7-a6f6-c25235345934', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 44, 44, 'Behold, [the enemy] shall come up like a lion from the pride of the Jordan against the strong habitation: for I will suddenly make them run away from it; and whoever is chosen, him will I appoint over it: for who is like me? and who will appoint me a time? and who is the shepherd who can stand before me?'),
  ('074340e8-ece1-51c3-a349-a80ece5545c6', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 45, 45, 'Therefore hear the counsel of Yahweh, that he has taken against Babylon; and his purposes, that he has purposed against the land of the Chaldeans: Surely they shall drag them away, [even] the little ones of the flock; surely he shall make their habitation desolate over them.'),
  ('924cb615-9539-54cc-aa11-b60d557da350', '9b3c2eec-44e3-5422-a86f-010a35766c50', NULL, 46, 46, 'At the noise of the taking of Babylon the earth trembles, and the cry is heard among the nations.'),
  ('db632be3-bb62-5dc9-a721-9cb85b908fea', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 1, 1, 'Thus says Yahweh: Behold, I will raise up against Babylon, and against those who dwell in Lebkamai, a destroying wind.'),
  ('663fb970-42b2-512b-ad2e-16b9612af2bb', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 2, 2, 'I will send to Babylon strangers, who shall winnow her; and they shall empty her land: for in the day of trouble they shall be against her around.'),
  ('ae5df8b8-5bf3-5b8c-a596-01afcaac5063', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 3, 3, 'Against [him who] bends let the archer bend his bow, and against [him who] lifts himself up in his coat of mail: and don''t spare her young men; utterly destroy all her army.'),
  ('947da97d-48ba-5779-ab1c-5345baf9b7f9', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 4, 4, 'They shall fall down slain in the land of the Chaldeans, and thrust through in her streets.'),
  ('5a77cd97-248f-56f8-a5f6-32fd69997b67', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 5, 5, 'For Israel is not forsaken, nor Judah, of his God, of Yahweh of Armies; though their land is full of guilt against the Holy One of Israel.'),
  ('259398ff-326a-59f0-a45e-90ee8984bd56', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 6, 6, 'Flee out of the midst of Babylon, and save every man his life; don''t be cut off in her iniquity: for it is the time of Yahweh''s vengeance; he will render to her a recompense.'),
  ('2fb4b58b-9937-5428-a5ab-822223b33b57', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 7, 7, 'Babylon has been a golden cup in Yahweh''s hand, who made all the earth drunken: the nations have drunk of her wine; therefore the nations are mad.'),
  ('4540f858-b59a-508a-aadc-9adbba4b3d3b', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 8, 8, 'Babylon is suddenly fallen and destroyed: wail for her; take balm for her pain, if so be she may be healed.'),
  ('83ca7bc5-bdec-52bf-abc5-5d988a8a8a7b', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 9, 9, 'We would have healed Babylon, but she is not healed: forsake her, and let us go everyone into his own country; for her judgment reaches to heaven, and is lifted up even to the skies.'),
  ('d7d80a72-2b9e-553a-a3a1-df9cc4adba94', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 10, 10, 'Yahweh has brought forth our righteousness: come, and let us declare in Zion the work of Yahweh our God.'),
  ('f5616b9a-79ab-5125-a685-ae627de96cd4', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 11, 11, 'Make sharp the arrows; hold firm the shields: Yahweh has stirred up the spirit of the kings of the Medes; because his purpose is against Babylon, to destroy it: for it is the vengeance of Yahweh, the vengeance of his temple.'),
  ('07601d2c-e555-51c8-ac2b-be9d9df61879', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 12, 12, 'Set up a standard against the walls of Babylon, make the watch strong, set the watchmen, prepare the ambushes; for Yahweh has both purposed and done that which he spoke concerning the inhabitants of Babylon.'),
  ('9fce25ca-2e5a-514e-a7d4-6df1f45523f9', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 13, 13, 'You who dwell on many waters, abundant in treasures, your end has come, the measure of your covetousness.'),
  ('2af9dd00-f461-5327-a12a-2a8cda6d5a1d', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 14, 14, 'Yahweh of Armies has sworn by himself, [saying], Surely I will fill you with men, as with the canker worm; and they shall lift up a shout against you.'),
  ('31b830f2-b1c8-5c52-a9ed-77ae3506ffc3', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 15, 15, 'He has made the earth by his power, he has established the world by his wisdom, and by his understanding has he stretched out the heavens:'),
  ('d7ce642f-2ee0-525e-ae4d-a8cfcc806a41', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 16, 16, 'when he utters his voice, there is a tumult of waters in the heavens, and he causes the vapors to ascend from the ends of the earth; he makes lightning for the rain, and brings forth the wind out of his treasuries.'),
  ('f29389fa-5af6-54ff-a3d3-1adda723d33e', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 17, 17, 'Every man is become brutish [and is] without knowledge; every goldsmith is disappointed by his image; for his molten image is falsehood, and there is no breath in them.'),
  ('877813b4-492f-5af5-a981-8224ef8ea9bf', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 18, 18, 'They are vanity, a work of delusion: in the time of their visitation they shall perish.'),
  ('e65df3b1-213a-5ca9-a491-e9d655613ad4', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 19, 19, 'The portion of Jacob is not like these; for he is the former of all things; and [Israel] is the tribe of his inheritance: Yahweh of Armies is his name.'),
  ('2e62333a-e659-5ffe-a709-c427ef8c26b0', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 20, 20, 'You are my battle axe and weapons of war: and with you will I break in pieces the nations; and with you will I destroy kingdoms;'),
  ('91d25f4c-62a0-535a-af12-10178de1aff1', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 21, 21, 'and with you will I break in pieces the horse and his rider;'),
  ('d659fae3-5451-5153-ae5b-176e1b4672f0', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 22, 22, 'and with you will I break in pieces the chariot and him who rides therein; and with you will I break in pieces man and woman; and with you will I break in pieces the old man and the youth; and with you will I break in pieces the young man and the virgin;'),
  ('aed8e01d-0015-575a-a33b-0bde80421ece', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 23, 23, 'and with you will I break in pieces the shepherd and his flock; and with you will I break in pieces the farmer and his yoke [of oxen]; and with you will I break in pieces governors and deputies.'),
  ('fe97bde6-1000-5803-a7ce-af717bb5b0eb', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 24, 24, 'I will render to Babylon and to all the inhabitants of Chaldea all their evil that they have done in Zion in your sight, says Yahweh.'),
  ('781e22c7-179d-52e0-a5da-773eb1b7e7d0', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 25, 25, 'Behold, I am against you, destroying mountain, says Yahweh, which destroys all the earth; and I will stretch out my hand on you, and roll you down from the rocks, and will make you a burnt mountain.'),
  ('4616c0fc-e71a-5b8c-af02-2e464ee6bfad', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 26, 26, 'They shall not take of you a stone for a corner, nor a stone for foundations; but you shall be desolate for ever, says Yahweh.'),
  ('52d1a4c4-1241-5b24-ac54-5c6da535ed41', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 27, 27, 'Set up a standard in the land, blow the trumpet among the nations, prepare the nations against her, call together against her the kingdoms of Ararat, Minni, and Ashkenaz: appoint a marshal against her; cause the horses to come up as the rough canker worm.'),
  ('adfe39dd-d6ef-5e03-a57f-b6a9d7f4c935', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 28, 28, 'Prepare against her the nations, the kings of the Medes, its governors, and all its deputies, and all the land of their dominion.'),
  ('dee6870d-89df-5761-adf6-c246d7366403', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 29, 29, 'The land trembles and is in pain; for the purposes of Yahweh against Babylon do stand, to make the land of Babylon a desolation, without inhabitant.'),
  ('f9f57402-9b8c-55e9-adfa-c70c3baa4585', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 30, 30, 'The mighty men of Babylon have forborne to fight, they remain in their strongholds; their might has failed; they are become as women: her dwelling places are set on fire; her bars are broken.'),
  ('3e403f92-5d3c-593d-a288-d4978e836cd1', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 31, 31, 'One runner will run to meet another, and one messenger to meet another, to show the king of Babylon that his city is taken on every quarter:'),
  ('fe0453cb-c0ec-57b3-a2ad-e5537c93398d', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 32, 32, 'and the passages are seized, and the reeds they have burned with fire, and the men of war are frightened.'),
  ('fd37b703-2269-5703-a02b-e16a6f1f10c8', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 33, 33, 'For thus says Yahweh of Armies, the God of Israel: The daughter of Babylon is like a threshing floor at the time when it is trodden; yet a little while, and the time of harvest shall come for her.'),
  ('6d11ea00-c304-5877-a5c4-0c12908e561a', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 34, 34, 'Nebuchadnezzar the king of Babylon has devoured me, he has crushed me, he has made me an empty vessel, he has, like a monster, swallowed me up, he has filled his maw with my delicacies; he has cast me out.'),
  ('b36d088b-30aa-599f-a11f-e8f6717885c0', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 35, 35, 'The violence done to me and to my flesh be on Babylon, shall the inhabitant of Zion say; and, My blood be on the inhabitants of Chaldea, shall Jerusalem say.'),
  ('48a9abd0-894c-5614-ae07-fb6b60edac0f', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 36, 36, 'Therefore thus says Yahweh: Behold, I will plead your cause, and take vengeance for you; and I will dry up her sea, and make her fountain dry.'),
  ('4d7926ea-94dc-5e80-aa8d-feeab0ddab97', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 37, 37, 'Babylon shall become heaps, a dwelling place for jackals, an astonishment, and a hissing, without inhabitant.'),
  ('4925dba0-1732-5d04-ae12-1759dc7cee3a', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 38, 38, 'They shall roar together like young lions; they shall growl as lions'' cubs.'),
  ('76854283-2590-59ed-ad97-113c65ec18ff', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 39, 39, 'When they are heated, I will make their feast, and I will make them drunken, that they may rejoice, and sleep a perpetual sleep, and not wake, says Yahweh.'),
  ('b7fae4ed-7fb5-54db-a55a-57dbc86eac77', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 40, 40, 'I will bring them down like lambs to the slaughter, like rams with male goats.'),
  ('95d188ac-a572-52ef-ade8-3338b5180ec5', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 41, 41, 'How is Sheshach taken! and the praise of the whole earth seized! how is Babylon become a desolation among the nations!'),
  ('43279b7c-bf43-533b-af21-9195c83d5241', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 42, 42, 'The sea is come up on Babylon; she is covered with the multitude of its waves.'),
  ('cf7f346f-2839-526e-afdf-441ed8c25c0a', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 43, 43, 'Her cities are become a desolation, a dry land, and a desert, a land in which no man dwells, neither does any son of man pass thereby.'),
  ('cc8975da-1f44-5cbe-ae5e-b75a9b71a254', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 44, 44, 'I will execute judgment on Bel in Babylon, and I will bring forth out of his mouth that which he has swallowed up; and the nations shall not flow any more to him: yes, the wall of Babylon shall fall.'),
  ('aab8451b-fef6-5a24-ac2f-3fe695b1f7b6', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 45, 45, 'My people, go away from the midst of her, and save yourselves every man from the fierce anger of Yahweh.'),
  ('b0d3218c-da53-58f1-aad6-689c8c54c2e5', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 46, 46, 'Don''t let your heart faint, neither fear for the news that shall be heard in the land; for news shall come one year, and after that in another year [shall come] news, and violence in the land, ruler against ruler.'),
  ('5b7fc63d-9433-596c-aec3-ca97ea1f7813', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 47, 47, 'Therefore, behold, the days come, that I will execute judgment on the engraved images of Babylon; and her whole land shall be confounded; and all her slain shall fall in the midst of her.'),
  ('b0acf987-01f0-5167-afc5-5693584a6c4d', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 48, 48, 'Then the heavens and the earth, and all that is therein, shall sing for joy over Babylon; for the destroyers shall come to her from the north, says Yahweh.'),
  ('ecc859a5-e1f2-5f5e-a1fa-2310f793bcd4', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 49, 49, 'As Babylon has caused the slain of Israel to fall, so at Babylon shall fall the slain of all the land.'),
  ('a5f14abe-f1f3-5825-a529-689d7dbbeba5', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 50, 50, 'You who have escaped the sword, go, don''t stand still; remember Yahweh from afar, and let Jerusalem come into your mind.'),
  ('91bfff95-5442-5f1f-af36-f3877b324f26', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 51, 51, 'We are confounded, because we have heard reproach; confusion has covered our faces: for strangers are come into the sanctuaries of Yahweh''s house.'),
  ('2fba28ff-f267-55b6-a769-c2be3af55087', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 52, 52, 'Therefore, behold, the days come, says Yahweh, that I will execute judgment on her engraved images; and through all her land the wounded shall groan.'),
  ('9d94f466-51b1-5f82-a276-022d1bc8cfae', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 53, 53, 'Though Babylon should mount up to the sky, and though she should fortify the height of her strength, yet from me shall destroyers come to her, says Yahweh.'),
  ('286c0ed1-c5c4-5895-addd-d62045d023e9', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 54, 54, 'The sound of a cry from Babylon, and of great destruction from the land of the Chaldeans!'),
  ('f0233a20-c5be-5c6b-a20a-3f4ba22c5fc0', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 55, 55, 'For Yahweh lays Babylon waste, and destroys out of her the great voice; and their waves roar like many waters; the noise of their voice is uttered:'),
  ('ac687598-f18e-5268-a92d-b4ff5e596c62', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 56, 56, 'for the destroyer is come on her, even on Babylon, and her mighty men are taken, their bows are broken in pieces; for Yahweh is a God of recompenses, he will surely requite.'),
  ('18f6887e-a0c0-5bfe-a50e-5a44c470473c', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 57, 57, 'I will make drunk her princes and her wise men, her governors and her deputies, and her mighty men; and they shall sleep a perpetual sleep, and not wake up, says the King, whose name is Yahweh of Armies.'),
  ('237b9a00-18db-5ecb-a62f-a3e03a01f3be', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 58, 58, 'Thus says Yahweh of Armies: The broad walls of Babylon shall be utterly overthrown, and her high gates shall be burned with fire; and the peoples shall labor for vanity, and the nations for the fire; and they shall be weary.'),
  ('14df3db1-8f63-505e-aef4-96a06829bf09', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 59, 59, 'The word which Jeremiah the prophet commanded Seraiah the son of Neriah, the son of Mahseiah, when he went with Zedekiah the king of Judah to Babylon in the fourth year of his reign. Now Seraiah was chief quartermaster.'),
  ('a34563f9-f0b1-5a70-a22d-68dddedf955d', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 60, 60, 'Jeremiah wrote in a book all the evil that should come on Babylon, even all these words that are written concerning Babylon.'),
  ('71c19373-c6df-5495-a2d6-6492695febb9', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 61, 61, 'Jeremiah said to Seraiah, When you come to Babylon, then see that you read all these words,'),
  ('81911933-4986-5894-ab3a-4d7790cfc324', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 62, 62, 'and say, Yahweh, you have spoken concerning this place, to cut it off, that none shall dwell therein, neither man nor animal, but that it shall be desolate forever.'),
  ('85e3e1ea-a6e6-507e-a82d-bd51cdbb74bd', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 63, 63, 'It shall be, when you have made an end of reading this book, that you shall bind a stone to it, and cast it into the midst of the Euphrates:'),
  ('a8346c09-2f32-5a48-a7c0-15a1a46fa356', '5b4ebe48-eebb-5f8e-a287-4f2103c16c68', NULL, 64, 64, 'and you shall say, Thus shall Babylon sink, and shall not rise again because of the evil that I will bring on her; and they shall be weary. Thus far are the words of Jeremiah.'),
  ('cf2cd8ac-d18c-554d-aa50-efe6e9c66575', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 1, 1, 'Zedekiah was twenty-one years old when he began to reign; and he reigned eleven years in Jerusalem: and his mother''s name was Hamutal the daughter of Jeremiah of Libnah.'),
  ('9c0f1351-e290-50a7-a406-ad4bb68a2781', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 2, 2, 'He did that which was evil in the sight of Yahweh, according to all that Jehoiakim had done.'),
  ('e837e0c2-4f18-5424-ae9e-00fcf885f08e', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 3, 3, 'For through the anger of Yahweh did it happen in Jerusalem and Judah, until he had cast them out from his presence. Zedekiah rebelled against the king of Babylon.'),
  ('301576b6-bdbb-57d6-aa74-95b3910b89a9', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 4, 4, 'It happened in the ninth year of his reign, in the tenth month, in the tenth day of the month, that Nebuchadnezzar king of Babylon came, he and all his army, against Jerusalem, and encamped against it; and they built forts against it round about.'),
  ('69cdd9fb-c0b5-53fe-a166-f5fb970d6540', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 5, 5, 'So the city was besieged to the eleventh year of king Zedekiah.'),
  ('3fc5cb36-e296-5f6f-ab9c-8afbd869b451', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 6, 6, 'In the fourth month, in the ninth day of the month, the famine was severe in the city, so that there was no bread for the people of the land.'),
  ('ac861c12-2655-5aa6-ade6-059c2c80bc46', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 7, 7, 'Then a breach was made in the city, and all the men of war fled, and went forth out of the city by night by the way of the gate between the two walls, which was by the king''s garden; (now the Chaldeans were against the city all around;) and they went toward the Arabah.'),
  ('3a973a63-a72c-55b3-a109-b695dadc0709', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 8, 8, 'But the army of the Chaldeans pursued after the king, and overtook Zedekiah in the plains of Jericho; and all his army was scattered from him.'),
  ('320a4b39-f51f-587a-a707-03d60f9ff247', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 9, 9, 'Then they took the king, and carried him up to the king of Babylon to Riblah in the land of Hamath; and he gave judgment on him.'),
  ('7569b01f-c5be-5274-abf4-14080332a49e', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 10, 10, 'The king of Babylon killed the sons of Zedekiah before his eyes: he killed also all the princes of Judah in Riblah.'),
  ('e1ba68d7-0d91-5f2a-a087-dfc9b907a941', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 11, 11, 'He put out the eyes of Zedekiah; and the king of Babylon bound him in fetters, and carried him to Babylon, and put him in prison until the day of his death.'),
  ('21d98817-1bbd-5728-a11c-2236ecee6b24', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 12, 12, 'Now in the fifth month, in the tenth day of the month, which was the nineteenth year of king Nebuchadnezzar, king of Babylon, came Nebuzaradan the captain of the guard, who stood before the king of Babylon, into Jerusalem:'),
  ('2d8a16de-fef6-5a3a-ae55-4019fd86bb77', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 13, 13, 'and he burned the house of Yahweh, and the king''s house; and all the houses of Jerusalem, even every great house, burned he with fire.'),
  ('63d9c73b-bebe-5e4c-ac84-d6493fd4c44c', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 14, 14, 'All the army of the Chaldeans, who were with the captain of the guard, broke down all the walls of Jerusalem all around.'),
  ('190bfc43-8d11-5fb4-adae-d87e9621bcbe', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 15, 15, 'Then Nebuzaradan the captain of the guard carried away captive of the poorest of the people, and the residue of the people who were left in the city, and those who fell away, who fell to the king of Babylon, and the residue of the multitude.'),
  ('a3528caf-4c6f-51ae-a4a9-dbca799abf0e', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 16, 16, 'But Nebuzaradan the captain of the guard left of the poorest of the land to be vineyard keepers and farmers.'),
  ('4f98ca00-612b-59aa-a8bc-e3ba79e180ea', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 17, 17, 'The pillars of brass that were in the house of Yahweh, and the bases and the bronze sea that were in the house of Yahweh, did the Chaldeans break in pieces, and carried all the brass of them to Babylon.'),
  ('df93b075-7554-51cf-aeae-adfe9a689fbe', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 18, 18, 'The pots also, and the shovels, and the snuffers, and the basins, and the spoons, and all the vessels of brass with which they ministered, took they away.'),
  ('dd7e2a78-83e4-52d0-a3e4-25e13f2b037f', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 19, 19, 'The cups, and the fire pans, and the basins, and the pots, and the lampstands, and the spoons, and the bowls--that which was of gold, in gold, and that which was of silver, in silver,--the captain of the guard took away.'),
  ('15a54165-a5a5-5ebc-a0df-ddada38092db', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 20, 20, 'The two pillars, the one sea, and the twelve bronze bulls that were under the bases, which king Solomon had made for the house of Yahweh. The brass of all these vessels was without weight.'),
  ('b3bca35a-6226-5ffc-a5ad-8ba215dcdb63', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 21, 21, 'As for the pillars, the height of the one pillar was eighteen cubits; and a line of twelve cubits did compass it; and its thickness was four fingers: it was hollow.'),
  ('f88f119e-46a0-52da-a77d-43eb3f925f54', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 22, 22, 'A capital of brass was on it; and the height of the one capital was five cubits, with network and pomegranates on the capital all around, all of brass: and the second pillar also had like these, and pomegranates.'),
  ('4cdce57f-9ae3-57b5-a468-82398f2a73ab', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 23, 23, 'There were ninety-six pomegranates on the sides; all the pomegranates were one hundred on the network all around.'),
  ('0d391092-d838-5516-a642-9cee973590a2', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 24, 24, 'The captain of the guard took Seraiah the chief priest, and Zephaniah the second priest, and the three keepers of the threshold:'),
  ('8ef2c1b6-e010-5dc4-af5f-78a5531edfa6', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 25, 25, 'and out of the city he took an officer who was set over the men of war; and seven men of those who saw the king''s face, who were found in the city; and the scribe of the captain of the army, who mustered the people of the land; and sixty men of the people of the land, who were found in the midst of the city.'),
  ('b992a072-536d-581a-adcd-73239b5abf4b', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 26, 26, 'Nebuzaradan the captain of the guard took them, and brought them to the king of Babylon to Riblah.'),
  ('e80925e5-7c6b-527c-a8a3-ef69dcd89a95', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 27, 27, 'The king of Babylon struck them, and put them to death at Riblah in the land of Hamath. So Judah was carried away captive out of his land.'),
  ('a576c5e0-7f5d-5695-a279-533c91593f88', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 28, 28, 'This is the people whom Nebuchadnezzar carried away captive: in the seventh year three thousand twenty-three Jews;'),
  ('b543e457-9838-5572-a1f8-9219cae42f89', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 29, 29, 'in the eighteenth year of Nebuchadnezzar he carried away captive from Jerusalem eight hundred thirty-two persons;'),
  ('05b5ce54-84a6-5891-a610-3ad7ae016298', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 30, 30, 'in the three and twentieth year of Nebuchadnezzar Nebuzaradan the captain of the guard carried away captive of the Jews seven hundred forty-five persons: all the persons were four thousand and six hundred.'),
  ('d7da3b1f-0e26-5533-abfe-3623117c7b3c', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 31, 31, 'It happened in the seven and thirtieth year of the captivity of Jehoiachin king of Judah, in the twelfth month, in the five and twentieth day of the month, that Evilmerodach king of Babylon, in the [first] year of his reign, lifted up the head of Jehoiachin king of Judah, and brought him forth out of prison;'),
  ('354e6509-ff2e-501e-a3cb-461ac95c1bcf', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 32, 32, 'and he spoke kindly to him, and set his throne above the throne of the kings who were with him in Babylon,'),
  ('55f8f04d-149d-5319-a3fa-8fe9c225c116', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 33, 33, 'and changed his prison garments. [Jehoiachin] ate bread before him continually all the days of his life:'),
  ('dfcd2e20-e20b-58f8-a046-c8dce31fc449', 'c4857f0a-372c-59b3-aff6-6d89d5428b4c', NULL, 34, 34, 'and for his allowance, there was a continual allowance given him by the king of Babylon, every day a portion until the day of his death, all the days of his life.'),
  ('4987aebc-0487-55df-a5cc-9f051d2942d2', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 1, 1, 'How the city sits solitary, that was full of people! She has become as a widow, who was great among the nations! She who was a princess among the provinces is become tributary!'),
  ('baf88555-003e-5d85-ae09-cbe6eee1c20f', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 2, 2, 'She weeps bitterly in the night, and her tears are on her cheeks; among all her lovers she has none to comfort her: All her friends have dealt treacherously with her; they are become her enemies.'),
  ('a82f3e22-4072-534c-a573-bb31ed5b7d78', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 3, 3, 'Judah is gone into captivity because of affliction, and because of great servitude; she dwells among the nations, she finds no rest: all her persecutors overtook her within the straits.'),
  ('41ac4080-ef58-58ae-a5ac-4c88d2e1296c', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 4, 4, 'The ways of Zion do mourn, because none come to the solemn assembly; all her gates are desolate, her priests do sigh: her virgins are afflicted, and she herself is in bitterness.'),
  ('c528a7b5-a9c6-5963-a200-c70c7a4b97d7', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 5, 5, 'Her adversaries are become the head, her enemies prosper; for Yahweh has afflicted her for the multitude of her transgressions: her young children are gone into captivity before the adversary.'),
  ('416fbf7d-6f3f-5c5d-a563-9b6fea600fde', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 6, 6, 'From the daughter of Zion all her majesty is departed: her princes are become like harts that find no pasture, they are gone without strength before the pursuer.'),
  ('c0deca73-2a9a-5eba-a627-7fa36fb4b1db', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 7, 7, 'Jerusalem remembers in the days of her affliction and of her miseries all her pleasant things that were from the days of old: when her people fell into the hand of the adversary, and none did help her, The adversaries saw her, they did mock at her desolations.'),
  ('3a7a482e-78b8-5b72-ab29-03e0e10009ce', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 8, 8, 'Jerusalem has grievously sinned; therefore she is become as an unclean thing; all who honored her despise her, because they have seen her nakedness: yes, she sighs, and turns backward.'),
  ('c76e0bb1-2d5f-5f3d-ab27-278ec0d73fdc', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 9, 9, 'Her filthiness was in her skirts; she didn''t remember her latter end; therefore is she come down wonderfully; she has no comforter: see, Yahweh, my affliction; for the enemy has magnified himself.'),
  ('311d33dd-5df2-551c-a783-5ea645e12721', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 10, 10, 'The adversary has spread out his hand on all her pleasant things: for she has seen that the nations are entered into her sanctuary, concerning whom you commanded that they should not enter into your assembly.'),
  ('e9d0842e-7ed2-53bb-aa4f-4514d1a76d80', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 11, 11, 'All her people sigh, they seek bread; they have given their pleasant things for food to refresh the soul: look, Yahweh, and see; for I am become abject.'),
  ('aa445174-a354-5bb7-aeff-903c8c1e8ff8', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 12, 12, 'Is it nothing to you, all you who pass by? Look, and see if there be any sorrow like my sorrow, which is brought on me, With which Yahweh has afflicted [me] in the day of his fierce anger.'),
  ('36ce487a-d7c2-5c2b-a0be-32cdc01437d2', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 13, 13, 'From on high has he sent fire into my bones, and it prevails against them; He has spread a net for my feet, he has turned me back: He has made me desolate and faint all the day.'),
  ('5795c26e-53fe-5ddb-aaf8-9acd32559062', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 14, 14, 'The yoke of my transgressions is bound by his hand; They are knit together, they are come up on my neck; he has made my strength to fail: The Lord has delivered me into their hands, against whom I am not able to stand.'),
  ('b4ea8cf8-2a21-5ccc-aeed-33d218b272b8', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 15, 15, 'The Lord has set at nothing all my mighty men in the midst of me; He has called a solemn assembly against me to crush my young men: The Lord has trodden as in a winepress the virgin daughter of Judah.'),
  ('b781554a-c622-5e31-afd6-86023f0e5469', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 16, 16, 'For these things I weep; my eye, my eye runs down with water; Because the comforter who should refresh my soul is far from me: My children are desolate, because the enemy has prevailed.'),
  ('594588a1-2d9b-5c4e-a1fe-06d678e0439c', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 17, 17, 'Zion spreads forth her hands; there is none to comfort her; Yahweh has commanded concerning Jacob, that those who are around him should be his adversaries: Jerusalem is among them as an unclean thing.'),
  ('6c1e670b-9551-5fd2-a9ff-e5988ff0651d', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 18, 18, 'Yahweh is righteous; for I have rebelled against his commandment: Please hear all you peoples, and see my sorrow: My virgins and my young men are gone into captivity.'),
  ('6157f043-4b09-5fc2-a72f-731368b777e5', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 19, 19, 'I called for my lovers, [but] they deceived me: My priests and my elders gave up the spirit in the city, While they sought them food to refresh their souls.'),
  ('170bedeb-79b0-5a1e-a635-7ea8aa8afb27', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 20, 20, 'See, Yahweh; for I am in distress; my heart is troubled; My heart is turned within me; for I have grievously rebelled: Abroad the sword bereaves, at home there is as death.'),
  ('d8ac056a-3602-5f01-a2e8-175b1952293e', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 21, 21, 'They have heard that I sigh; there is none to comfort me; All my enemies have heard of my trouble; they are glad that you have done it: You will bring the day that you have proclaimed, and they shall be like me.'),
  ('ef9e11bb-08c2-5034-aa51-933f3fde6ee8', 'a5a4dd9d-c8ad-57a5-a3eb-024ac1f70b17', NULL, 22, 22, 'Let all their wickedness come before you; Do to them, as you have done to me for all my transgressions: For my sighs are many, and my heart is faint.'),
  ('e95c7ef6-3e0a-5114-a0a7-404e9a5514b3', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 1, 1, 'How has the Lord covered the daughter of Zion with a cloud in his anger! He has cast down from heaven to the earth the beauty of Israel, And hasn''t remembered his footstool in the day of his anger.'),
  ('fe332b90-8385-5b60-ac19-462386bb68a4', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 2, 2, 'The Lord has swallowed up all the habitations of Jacob, and has not pitied: He has thrown down in his wrath the strongholds of the daughter of Judah; He has brought them down to the ground; he has profaned the kingdom and its princes.'),
  ('df0b832d-6acb-59a7-adb2-f92bef324ec1', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 3, 3, 'He has cut off in fierce anger all the horn of Israel; He has drawn back his right hand from before the enemy: He has burned up Jacob like a flaming fire, which devours all around.'),
  ('e39ad5c8-863c-51a6-a63e-33b5d3fdba8f', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 4, 4, 'He has bent his bow like an enemy, he has stood with his right hand as an adversary, Has killed all that were pleasant to the eye: In the tent of the daughter of Zion he has poured out his wrath like fire.'),
  ('4eed3acf-acc8-5379-ae25-057d4f92e41c', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 5, 5, 'The Lord is become as an enemy, he has swallowed up Israel; He has swallowed up all her palaces, he has destroyed his strongholds; He has multiplied in the daughter of Judah mourning and lamentation.'),
  ('632189a5-112f-5d43-a8a0-67af4a5acf64', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 6, 6, 'He has violently taken away his tabernacle, as if it were of a garden; he has destroyed his place of assembly: Yahweh has caused solemn assembly and Sabbath to be forgotten in Zion, Has despised in the indignation of his anger the king and the priest.'),
  ('67f247dd-f3d3-5f98-a04e-b798de900f2d', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 7, 7, 'The Lord has cast off his altar, he has abhorred his sanctuary; He has given up into the hand of the enemy the walls of her palaces: They have made a noise in the house of Yahweh, as in the day of a solemn assembly.'),
  ('7f45221a-b064-524c-a5ec-a5493991b454', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 8, 8, 'Yahweh has purposed to destroy the wall of the daughter of Zion; He has stretched out the line, he has not withdrawn his hand from destroying; He has made the rampart and wall to lament; they languish together.'),
  ('a664d2a8-de7c-5b13-afb2-1b5fb82c7394', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 9, 9, 'Her gates are sunk into the ground; he has destroyed and broken her bars: Her king and her princes are among the nations where the law is not; Yes, her prophets find no vision from Yahweh.'),
  ('c881b3d6-9a04-5025-afeb-e3ced893fc41', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 10, 10, 'The elders of the daughter of Zion sit on the ground, they keep silence; They have cast up dust on their heads; they have clothed themselves with sackcloth: The virgins of Jerusalem hang down their heads to the ground.'),
  ('79bed1ab-811f-5e11-af72-2c0f63dec608', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 11, 11, 'My eyes do fail with tears, my heart is troubled; My liver is poured on the earth, because of the destruction of the daughter of my people, Because the young children and the infants swoon in the streets of the city.'),
  ('efa06da7-7ec9-5f8e-add1-a3f6e51499da', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 12, 12, 'They tell their mothers, Where is grain and wine? When they swoon as the wounded in the streets of the city, When their soul is poured out into their mothers'' bosom.'),
  ('248789d3-9b74-585e-adb4-d363dcb34db1', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 13, 13, 'What shall I testify to you? what shall I liken to you, daughter of Jerusalem? What shall I compare to you, that I may comfort you, virgin daughter of Zion? For your breach is great like the sea: who can heal you?'),
  ('062e581a-84dd-5d94-acda-7207d323f026', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 14, 14, 'Your prophets have seen for you false and foolish visions; They have not uncovered your iniquity, to bring back your captivity, but have seen for you false oracles and causes of banishment.'),
  ('d9abb27e-6999-5dda-a4bf-6cedd8cc14d3', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 15, 15, 'All that pass by clap their hands at you. They hiss and wag their head at the daughter of Jerusalem, [saying], Is this the city that men called The perfection of beauty, The joy of the whole earth?'),
  ('46e29914-81af-5ad3-a96c-234b377862ba', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 16, 16, 'All your enemies have opened their mouth wide against you; They hiss and gnash the teeth; they say, We have swallowed her up; Certainly this is the day that we looked for; we have found, we have seen it.'),
  ('48c7315d-b23b-5552-a0de-5139dccb03c9', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 17, 17, 'Yahweh has done that which he purposed; he has fulfilled his word that he commanded in the days of old; He has thrown down, and has not pitied: He has caused the enemy to rejoice over you; he has exalted the horn of your adversaries.'),
  ('2a76eb0f-d035-5584-ada8-da1a241d948e', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 18, 18, 'Their heart cried to the Lord: wall of the daughter of Zion, let tears run down like a river day and night; Give yourself no respite; don''t let the apple of your eye cease.'),
  ('6392fc64-2961-556b-ac72-0128a4081a89', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 19, 19, 'Arise, cry out in the night, at the beginning of the watches; Pour out your heart like water before the face of the Lord: Lift up your hands toward him for the life of your young children, that faint for hunger at the head of every street.'),
  ('1049fe05-ade4-5b64-aef4-35f7482077a8', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 20, 20, 'Look, Yahweh, and see to whom you have done thus! Shall the women eat their fruit, the children that are dandled in the hands? Shall the priest and the prophet be killed in the sanctuary of the Lord?'),
  ('d9e0cab6-2abf-52ab-a0ec-1684bd311f4f', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 21, 21, 'The youth and the old man lie on the ground in the streets; My virgins and my young men are fallen by the sword: You have killed them in the day of your anger; you have slaughtered, [and] not pitied.'),
  ('72d4406a-af64-5d50-a76f-4f66a9e6a778', '47a55ca0-42a4-5c58-a419-3ca8d91e3811', NULL, 22, 22, 'You have called, as in the day of a solemn assembly, my terrors on every side; There was none that escaped or remained in the day of Yahweh''s anger: Those that I have dandled and brought up has my enemy consumed.'),
  ('59f71ec4-df00-5bee-afc0-6f991835fa49', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 1, 1, 'I am the man that has seen affliction by the rod of his wrath.'),
  ('565e428c-a5e6-5b7d-a8d8-aee676cdf83d', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 2, 2, 'He has led me and caused me to walk in darkness, and not in light.'),
  ('200021a6-2394-5dd1-abc5-3e6d7a576c38', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 3, 3, 'Surely against me he turns his hand again and again all the day.'),
  ('01b4d9d9-e37c-5fdc-a533-75c3b81aaebe', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 4, 4, 'My flesh and my skin has he made old; he has broken my bones.'),
  ('3271a2a3-8494-55d6-a62c-2e638118df53', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 5, 5, 'He has built against me, and surrounded me with gall and travail.'),
  ('954d2035-9cd8-5009-a60b-7410791ae1ae', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 6, 6, 'He has made me to dwell in dark places, as those that have been long dead.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('2373fdff-5451-5e8f-a475-7a6a775bd48a', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 7, 7, 'He has walled me about, that I can''t go forth; he has made my chain heavy.'),
  ('1942c395-55ab-509d-a3eb-632058fc80b1', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 8, 8, 'Yes, when I cry, and call for help, he shuts out my prayer.'),
  ('c25444b5-2496-5348-ad7f-f277b540f2e7', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 9, 9, 'He has walled up my ways with cut stone; he has made my paths crooked.'),
  ('7c4c4d51-05f1-537e-a2e5-a58dc7f42d82', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 10, 10, 'He is to me as a bear lying in wait, as a lion in secret places.'),
  ('c3511184-4350-5f1f-aace-cd18448056d1', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 11, 11, 'He has turned aside my ways, and pulled me in pieces; he has made me desolate.'),
  ('8e4698a5-cbe2-52d1-a148-b5b5caf9303d', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 12, 12, 'He has bent his bow, and set me as a mark for the arrow.'),
  ('cc4ca758-ca45-53a0-a81f-7b870c22035a', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 13, 13, 'He has caused the shafts of his quiver to enter into my kidneys.'),
  ('ac113dc6-a58b-56bd-a83e-0ce0ec1b832e', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 14, 14, 'I am become a derision to all my people, and their song all the day.'),
  ('cdccc6cc-8ef9-5e19-a327-51fe23f2a337', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 15, 15, 'He has filled me with bitterness, he has sated me with wormwood.'),
  ('2f25f0b3-b6c6-59b5-ac16-ca11b2032989', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 16, 16, 'He has also broken my teeth with gravel stones; he has covered me with ashes.'),
  ('bbc656f5-d902-54c4-a1d7-b70e95e91de4', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 17, 17, 'You have removed my soul far off from peace; I forgot prosperity.'),
  ('eff52666-1b5d-5d41-a4e8-e3933306995c', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 18, 18, 'I said, My strength is perished, and my expectation from Yahweh.'),
  ('9f55e2d0-8e6a-5e94-a345-927c07def1fe', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 19, 19, 'Remember my affliction and my misery, the wormwood and the gall.'),
  ('77f9293f-29d0-51f4-ae80-f05b6d702c38', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 20, 20, 'My soul still remembers them, and is bowed down within me.'),
  ('e76fb96b-b407-5813-aae1-8545811df39f', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 21, 21, 'This I recall to my mind; therefore have I hope.'),
  ('a41dbfa8-ea77-584d-a492-08c51e62f381', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 22, 22, '[It is of] Yahweh''s loving kindnesses that we are not consumed, because his compassion doesn''t fail.'),
  ('764889e4-cb42-54d5-a3ae-b54eb488d4ac', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 23, 23, 'They are new every morning; great is your faithfulness.'),
  ('59365200-07ab-5126-a428-fcb084662694', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 24, 24, 'Yahweh is my portion, says my soul; therefore will I hope in him.'),
  ('d6cc7f55-44e4-5e8a-a069-2e1b603a3b93', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 25, 25, 'Yahweh is good to those who wait for him, to the soul that seeks him.'),
  ('1949ba52-3e30-56bd-a08f-35add39a8c27', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 26, 26, 'It is good that a man should hope and quietly wait for the salvation of Yahweh.'),
  ('cd403222-557d-5cab-a9a4-b36e5637422c', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 27, 27, 'It is good for a man that he bear the yoke in his youth.'),
  ('54d5ba2e-aec3-54f5-a633-f3ce7452b901', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 28, 28, 'Let him sit alone and keep silence, because he has laid it on him.'),
  ('6aee07f6-aa8a-5fe0-a33b-ca778aa6f568', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 29, 29, 'Let him put his mouth in the dust, if so be there may be hope.'),
  ('7d584b8c-e7a4-5a67-a29f-06180f102d4f', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 30, 30, 'Let him give his cheek to him who strikes him; let him be filled full with reproach.'),
  ('7ef18936-4f54-54f7-af9d-434512505b5f', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 31, 31, 'For the Lord will not cast off forever.'),
  ('aba17549-d35f-5e8a-ad03-8538b2a1d038', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 32, 32, 'For though he cause grief, yet he will have compassion according to the multitude of his loving kindnesses.'),
  ('9c83e88c-9a4c-50d1-a518-f8dd562a9649', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 33, 33, 'For he does not afflict willingly, nor grieve the children of men.'),
  ('25bf0afc-f535-55a0-a525-fd0fb20b91b8', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 34, 34, 'To crush under foot all the prisoners of the earth,'),
  ('e52679b4-f2a4-5625-a8d0-a8bf558d785b', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 35, 35, 'To turn aside the right of a man before the face of the Most High,'),
  ('0812f3b3-453d-5851-a222-c796c2cb272d', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 36, 36, 'To subvert a man in his cause, the Lord doesn''t approve.'),
  ('8e9f4b42-e45e-5a8d-a206-285289e665bc', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 37, 37, 'Who is he who says, and it comes to pass, when the Lord doesn''t command it?'),
  ('24790896-a654-53f8-ac07-4cc8163f7e2b', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 38, 38, 'Doesn''t evil and good come out of the mouth of the Most High?'),
  ('8f97b161-ae7c-57ff-a074-48239ca12114', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 39, 39, 'Why does a living man complain, a man for the punishment of his sins?'),
  ('145e441b-4799-5519-aba7-faa6abaf066c', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 40, 40, 'Let us search and try our ways, and turn again to Yahweh.'),
  ('0c6f9a37-f601-5a8c-a47d-dfd8252fd37e', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 41, 41, 'Let us lift up our heart with our hands to God in the heavens.'),
  ('99f8d6c1-456e-5880-a44d-2a604cc502bb', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 42, 42, 'We have transgressed and have rebelled; you have not pardoned.'),
  ('c7795498-df8f-52bd-a324-c707d716e1ee', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 43, 43, 'You have covered with anger and pursued us; you have killed, you have not pitied.'),
  ('dbacda90-6205-5be6-aaad-f35b40c8796c', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 44, 44, 'You have covered yourself with a cloud, so that no prayer can pass through.'),
  ('d1064353-d852-5232-a2ac-ba3ef6547dbe', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 45, 45, 'You have made us an off-scouring and refuse in the midst of the peoples.'),
  ('e9779ae2-dd2e-5c67-a530-21c09dc98e94', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 46, 46, 'All our enemies have opened their mouth wide against us.'),
  ('7d07eeb9-80f3-59c7-a2a6-280f5c92cfc0', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 47, 47, 'Fear and the pit are come on us, devastation and destruction.'),
  ('8937e584-4c5a-5a4f-ab51-423b117e3d7c', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 48, 48, 'My eye runs down with streams of water, for the destruction of the daughter of my people.'),
  ('6c87a8d9-0d15-5a95-a52a-c20caf9ada6b', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 49, 49, 'My eye pours down, and doesn''t cease, without any intermission,'),
  ('fd2d3913-7983-5051-ab0a-1ed474b5fd9d', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 50, 50, 'Until Yahweh look down, and see from heaven.'),
  ('4f8a4147-fe1b-5a93-a1e0-3326357ed7d4', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 51, 51, 'My eye affects my soul, because of all the daughters of my city.'),
  ('918b2e13-c636-585d-a64e-eb288e199e0b', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 52, 52, 'They have chased me relentlessly like a bird, those who are my enemies without cause.'),
  ('c696527b-3378-5fde-ab51-abc564d5d526', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 53, 53, 'They have cut off my life in the dungeon, and have cast a stone on me.'),
  ('c70eee6e-4f66-5167-ada8-93503dceb905', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 54, 54, 'Waters flowed over my head; I said, I am cut off.'),
  ('87db5a6d-981c-559c-a292-cf715a41b4b9', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 55, 55, 'I called on your name, Yahweh, out of the lowest dungeon.'),
  ('94c67e90-388d-5cff-a560-83e73912df15', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 56, 56, 'You heard my voice; don''t hide your ear at my breathing, at my cry.'),
  ('9f2be173-f33d-53b4-a9a0-ad5948100d01', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 57, 57, 'You drew near in the day that I called on you; you said, Don''t be afraid.'),
  ('9781fa1e-91ec-5acc-a23e-32e95b241482', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 58, 58, 'Lord, you have pleaded the causes of my soul; you have redeemed my life.'),
  ('f5e1bee3-7195-5268-ad9a-9efa486e75e2', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 59, 59, 'Yahweh, you have seen my wrong. Judge my cause.'),
  ('f9682b77-9a09-5b55-ad65-3b5975d9819a', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 60, 60, 'You have seen all their vengeance and all their devices against me.'),
  ('08aed5ff-af4c-598c-ac4e-6d37eb79db49', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 61, 61, 'You have heard their reproach, Yahweh, and all their devices against me,'),
  ('862819d0-856c-5784-afe6-fc9b4e3b640e', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 62, 62, 'The lips of those that rose up against me, and their device against me all the day.'),
  ('0273727c-420d-527b-ac3f-ad0dd320b350', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 63, 63, 'You see their sitting down, and their rising up; I am their song.'),
  ('9dea3ad4-1c78-51ca-a65d-e256d22ac7e2', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 64, 64, 'You will render to them a recompense, Yahweh, according to the work of their hands.'),
  ('36985f8a-5add-5545-ac9f-5f661b994bc8', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 65, 65, 'You will give them hardness of heart, your curse to them.'),
  ('42df62c5-201c-5c67-acab-9510107eea45', '8951d58f-94dd-5132-a99b-da069d22f0a2', NULL, 66, 66, 'You will pursue them in anger, and destroy them from under the heavens of Yahweh.'),
  ('6b68d7b8-3a7a-5f46-af4a-e27f2e7f41f0', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 1, 1, 'How is the gold become dim! [how] is the most pure gold changed! The stones of the sanctuary are poured out at the head of every street.'),
  ('9fa6cab8-976e-5bb1-a274-d2dab553324d', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 2, 2, 'The precious sons of Zion, comparable to fine gold, How are they esteemed as earthen pitchers, the work of the hands of the potter!'),
  ('21a0f918-080b-54be-a8be-544d3d9ea20c', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 3, 3, 'Even the jackals draw out the breast, they nurse their young ones: The daughter of my people has become cruel, like the ostriches in the wilderness.'),
  ('f7ec9ee8-722a-5e42-a27a-4e78e0a4c7da', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 4, 4, 'The tongue of the nursing child clings to the roof of his mouth for thirst: The young children ask bread, and no man breaks it to them.'),
  ('a2e4ad11-72d1-5adb-a749-7fa15bad1b56', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 5, 5, 'Those who did feed delicately are desolate in the streets: Those who were brought up in scarlet embrace dunghills.'),
  ('a17a230c-9abf-5a4d-ac76-a9ff2e5fd2cb', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 6, 6, 'For the iniquity of the daughter of my people is greater than the sin of Sodom, That was overthrown as in a moment, and no hands were laid on her.'),
  ('ab7186c4-0711-5a7f-a100-dc443ddef088', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 7, 7, 'Her nobles were purer than snow, they were whiter than milk; They were more ruddy in body than rubies, their polishing was as of sapphire.'),
  ('306219a4-dbf4-573b-aaff-47aaed030c07', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 8, 8, 'Their appearance is blacker than a coal; they are not known in the streets: Their skin clings to their bones; it is withered, it is become like a stick.'),
  ('9227514a-7cfc-5fdb-a98f-df538bd7762e', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 9, 9, 'Those who are killed with the sword are better than those who are killed with hunger; For these pine away, stricken through, for want of the fruits of the field.'),
  ('a6c99729-1aa3-546a-a995-aea7536ef40d', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 10, 10, 'The hands of the pitiful women have boiled their own children; They were their food in the destruction of the daughter of my people.'),
  ('4c5c70a6-71ab-5a67-a288-d82ff99fd1c2', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 11, 11, 'Yahweh has accomplished his wrath, he has poured out his fierce anger; He has kindled a fire in Zion, which has devoured its foundations.'),
  ('5b408a01-60b1-51f7-a110-e4bf6b1cd947', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 12, 12, 'The kings of the earth didn''t believe, neither all the inhabitants of the world, That the adversary and the enemy would enter into the gates of Jerusalem.'),
  ('17b2f71d-968f-53d7-a346-2ad9ee690eda', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 13, 13, '[It is] because of the sins of her prophets, [and] the iniquities of her priests, That have shed the blood of the just in the midst of her.'),
  ('10ce18c0-d338-5a82-a7bd-8f94b056f4d7', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 14, 14, 'They wander as blind men in the streets, they are polluted with blood, So that men can''t touch their garments.'),
  ('c559f7fd-b969-5249-a2a9-5797044660d4', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 15, 15, 'Depart! they cried to them, Unclean! depart, depart, don''t touch! When they fled away and wandered, men said among the nations, They shall no more live [here].'),
  ('ab75f622-427e-556d-a251-e4eab1fbae5f', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 16, 16, 'The anger of Yahweh has scattered them; he will no more regard them: They didn''t respect the persons of the priests, they didn''t favor the elders.'),
  ('b9d04e5c-39f5-5e5b-a8a7-6734915741b1', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 17, 17, 'Our eyes do yet fail [in looking] for our vain help: In our watching we have watched for a nation that could not save.'),
  ('25eaf844-6020-5fc1-ae15-1da6ba466d24', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 18, 18, 'They hunt our steps, so that we can''t go in our streets: Our end is near, our days are fulfilled; for our end is come.'),
  ('e2b490e7-9e3e-50b8-a774-2c143472039c', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 19, 19, 'Our pursuers were swifter than the eagles of the sky: They chased us on the mountains, they laid wait for us in the wilderness.'),
  ('97359213-2d82-53da-ac91-fb9fa7ccb3b1', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 20, 20, 'The breath of our nostrils, the anointed of Yahweh, was taken in their pits; Of whom we said, Under his shadow we shall live among the nations.'),
  ('315abfae-42b3-51ec-afb5-e0cec9bd9833', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 21, 21, 'Rejoice and be glad, daughter of Edom, that dwell in the land of Uz: The cup shall pass through to you also; you shall be drunken, and shall make yourself naked.'),
  ('408b3789-be63-54ea-a43c-47aca69bacdc', 'f87ecb14-b8c4-5ec5-a1fd-9b982b460ae7', NULL, 22, 22, 'The punishment of your iniquity is accomplished, daughter of Zion; he will no more carry you away into captivity: He will visit your iniquity, daughter of Edom; he will uncover your sins.'),
  ('8602170b-27f1-5a5a-a1c1-d8e5f84c20b4', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 1, 1, 'Remember, Yahweh, what has come on us: Look, and see our reproach.'),
  ('51a41a35-e437-52a9-a469-2fb8071739a1', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 2, 2, 'Our inheritance is turned to strangers, Our houses to aliens.'),
  ('ba28b527-e457-5683-a536-2564470de682', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 3, 3, 'We are orphans and fatherless; Our mothers are as widows.'),
  ('b14c52fd-b51f-5fb2-a3d0-f7d938c92019', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 4, 4, 'We have drunken our water for money; Our wood is sold to us.'),
  ('0b8a71d2-1181-520f-a750-83cc2588dafe', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 5, 5, 'Our pursuers are on our necks: We are weary, and have no rest.'),
  ('f36e21b9-1c5a-5642-a01b-5b053b4bd33f', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 6, 6, 'We have given the hand to the Egyptians, To the Assyrians, to be satisfied with bread.'),
  ('c821ed7b-54e0-5b06-a92a-df95002c6dd9', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 7, 7, 'Our fathers sinned, and are no more; We have borne their iniquities.'),
  ('3ffad96f-6b86-51e7-ad41-0e85f68b3122', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 8, 8, 'Servants rule over us: There is none to deliver us out of their hand.'),
  ('fac9f4fa-a86e-5d46-a7d1-ffc8a55368f2', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 9, 9, 'We get our bread at the peril of our lives, Because of the sword of the wilderness.'),
  ('70bbaeed-1749-5116-a4ba-f5bbfd323a8c', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 10, 10, 'Our skin is black like an oven, Because of the burning heat of famine.'),
  ('0d6367b7-38f8-58a1-a673-c6882ea7015c', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 11, 11, 'They ravished the women in Zion, The virgins in the cities of Judah.'),
  ('e8d8d55b-ebc3-5b13-a5ab-19511d319207', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 12, 12, 'Princes were hanged up by their hand: The faces of elders were not honored.'),
  ('2dd9c34e-45ce-5274-a2e7-09cbfa5e003c', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 13, 13, 'The young men bare the mill; The children stumbled under the wood.'),
  ('618392e2-92da-5aaa-a798-fd374b6a45ef', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 14, 14, 'The elders have ceased from the gate, The young men from their music.'),
  ('bd6bd788-d782-5ed5-ab53-4a3914bdb98c', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 15, 15, 'The joy of our heart is ceased; Our dance is turned into mourning.'),
  ('a6558eea-913b-537a-a973-e08aa70a08f9', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 16, 16, 'The crown is fallen from our head: Woe to us! for we have sinned.'),
  ('a463331f-0d4a-58a5-a9e5-5c52d956926a', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 17, 17, 'For this our heart is faint; For these things our eyes are dim;'),
  ('9b297b97-fdcd-54d5-a735-5acd87212158', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 18, 18, 'For the mountain of Zion, which is desolate: The foxes walk on it.'),
  ('de00611d-75c3-5450-a1f5-b5fa027e1502', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 19, 19, 'You, Yahweh, remain forever; Your throne is from generation to generation.'),
  ('9647d798-cc80-5372-af3d-23326e6dfce5', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 20, 20, 'Why do you forget us forever, [And] forsake us so long time?'),
  ('3446ba55-b383-5d0f-ad0f-ae7d780d77ca', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 21, 21, 'Turn us to yourself, Yahweh, and we shall be turned. Renew our days as of old.'),
  ('b25a7e67-6449-51b2-af2c-6291e7119afd', 'a342ce7a-8756-5968-a833-0d3a445a336c', NULL, 22, 22, 'But you have utterly rejected us; You are very angry against us.'),
  ('1e342048-2147-50f1-ab0f-8665f0ea712a', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 1, 1, 'Now it happened in the thirtieth year, in the fourth [month], in the fifth [day] of the month, as I was among the captives by the river Chebar, that the heavens were opened, and I saw visions of God.'),
  ('e50e32f1-1731-51ad-a191-d0f2102f456c', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 2, 2, 'In the fifth [day] of the month, which was the fifth year of king Jehoiachin''s captivity,'),
  ('ae8c5595-c317-5307-aee9-138696d2ba07', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 3, 3, 'the word of Yahweh came expressly to Ezekiel the priest, the son of Buzi, in the land of the Chaldeans by the river Chebar; and the hand of Yahweh was there on him.'),
  ('c234bf66-a3a9-505c-ae56-1badd3722c17', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 4, 4, 'I looked, and behold, a stormy wind came out of the north, a great cloud, with flashing lightning, and a brightness around it, and out of its midst as it were glowing metal, out of the midst of the fire.'),
  ('f0027de5-6afb-5ba8-a83f-b50e18a2da7a', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 5, 5, 'Out of its midst came the likeness of four living creatures. This was their appearance: they had the likeness of a man.'),
  ('66214d8d-097d-53ee-a351-c2089e18bebc', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 6, 6, 'Everyone had four faces, and each one of them had four wings.'),
  ('a81d9e39-8fce-52cb-a65f-b1a610d4cffe', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 7, 7, 'Their feet were straight feet; and the sole of their feet was like the sole of a calf''s foot; and they sparkled like burnished brass.'),
  ('65459079-aa84-55c8-a686-e0e89d9bf584', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 8, 8, 'They had the hands of a man under their wings on their four sides; and the four of them had their faces and their wings [thus]:'),
  ('3d48886a-0a35-5798-ac39-379b721a4df7', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 9, 9, 'their wings were joined one to another; they didn''t turn when they went; each one went straight forward.'),
  ('add53f09-69af-5c17-a140-fcc2ca1ac104', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 10, 10, 'As for the likeness of their faces, they had the face of a man; and the four of them had the face of a lion on the right side; and the four of them had the face of an ox on the left side; the four of them also had the face of an eagle.'),
  ('e22daf13-c32e-534e-a00d-ccfcadff2b92', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 11, 11, 'Such were their faces. Their wings were spread out above. Two wings of each one touched another, and two covered their bodies.'),
  ('d00a4dc4-9f15-5fd2-aa29-c6393fb31942', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 12, 12, 'Each one went straight forward: where the spirit was to go, they went; they didn''t turn when they went.'),
  ('7c1d2e8e-6b1c-5479-a3e9-d6fd1a4151cd', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 13, 13, 'As for the likeness of the living creatures, their appearance was like burning coals of fire, like the appearance of torches: [the fire] went up and down among the living creatures; and the fire was bright, and out of the fire went forth lightning.'),
  ('fa0b561d-3ddb-54cc-a45e-bbc574dee338', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 14, 14, 'The living creatures ran and returned as the appearance of a flash of lightning.'),
  ('6bf91d3d-c926-5bfc-ab97-cffc2c156021', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 15, 15, 'Now as I saw the living creatures, behold, one wheel on the earth beside the living creatures, for each of the four faces of it.'),
  ('e0852ddc-296a-5c2b-a22c-ee9d05ecee6f', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 16, 16, 'The appearance of the wheels and their work was like a beryl: and the four of them had one likeness; and their appearance and their work was as it were a wheel within a wheel.'),
  ('75045272-7948-5a1e-af36-47807a81cfec', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 17, 17, 'When they went, they went in their four directions: they didn''t turn when they went.'),
  ('7131686e-5fd4-5036-a398-d1b296c9974e', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 18, 18, 'As for their rims, they were high and dreadful; and the four of them had their rims full of eyes all around.'),
  ('e62ab252-26a1-591e-a891-e9054b791181', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 19, 19, 'When the living creatures went, the wheels went beside them; and when the living creatures were lifted up from the earth, the wheels were lifted up.'),
  ('11a3e8f7-6b1f-56c4-a160-1aec45e612d4', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 20, 20, 'Wherever the spirit was to go, they went; there was the spirit to go: and the wheels were lifted up beside them; for the spirit of the living creature was in the wheels.'),
  ('30efa342-ef70-59db-aa02-da76017a8bf5', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 21, 21, 'When those went, these went; and when those stood, these stood; and when those were lifted up from the earth, the wheels were lifted up beside them: for the spirit of the living creature was in the wheels.'),
  ('15971967-346f-5c57-aab2-3c1f8ef0811c', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 22, 22, 'Over the head of the living creature there was the likeness of an expanse, like the awesome crystal to look on, stretched forth over their heads above.'),
  ('dcdef950-ec7e-52ea-a821-7c973d1f63fc', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 23, 23, 'Under the expanse were their wings straight, the one toward the other: each one had two which covered on this side, and every one had two which covered on that side, their bodies.'),
  ('5f507485-ef39-5c0c-ad72-6051a7bba30d', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 24, 24, 'When they went, I heard the noise of their wings like the noise of great waters, like the voice of the Almighty, a noise of tumult like the noise of an army: when they stood, they let down their wings.'),
  ('7f1ee7c3-55a8-5eb6-acdc-c7f98013865e', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 25, 25, 'There was a voice above the expanse that was over their heads: when they stood, they let down their wings.'),
  ('93f68c2d-94a0-5eb3-a4ac-68f9f5b022e5', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 26, 26, 'Above the expanse that was over their heads was the likeness of a throne, as the appearance of a sapphire stone; and on the likeness of the throne was a likeness as the appearance of a man on it above.'),
  ('2dbbd263-d88a-577b-ac16-2caaaf66b76c', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 27, 27, 'I saw as it were glowing metal, as the appearance of fire within it all around, from the appearance of his waist and upward; and from the appearance of his waist and downward I saw as it were the appearance of fire, and there was brightness around him.'),
  ('56993c04-1db8-57ce-a10f-9e8581644b1f', 'a94855cb-8439-549f-a59e-601ad3128732', NULL, 28, 28, 'As the appearance of the rainbow that is in the cloud in the day of rain, so was the appearance of the brightness all around. This was the appearance of the likeness of the glory of Yahweh. When I saw it, I fell on my face, and I heard a voice of one that spoke.'),
  ('ec1c7148-3e85-5ff9-a686-d32205dec053', '97dc9284-0b50-5aff-a407-3d000fbb13ed', NULL, 1, 1, 'He said to me, Son of man, stand on your feet, and I will speak with you.'),
  ('b3baba9e-911c-51a0-a34d-0d8e668d2013', '97dc9284-0b50-5aff-a407-3d000fbb13ed', NULL, 2, 2, 'The Spirit entered into me when he spoke to me, and set me on my feet; and I heard him who spoke to me.'),
  ('db0544ff-92a1-5788-a10e-9992d8d28529', '97dc9284-0b50-5aff-a407-3d000fbb13ed', NULL, 3, 3, 'He said to me, Son of man, I send you to the children of Israel, to a nation of rebels who have rebelled against me. They and their fathers have transgressed against me even to this very day.'),
  ('d46425fb-1c05-5d9b-a8d1-311d30656437', '97dc9284-0b50-5aff-a407-3d000fbb13ed', NULL, 4, 4, 'The children are impudent and stiff-hearted: I am sending you to them; and you shall tell them, Thus says the Lord Yahweh.'),
  ('87395440-1e74-5220-a672-0014a7207686', '97dc9284-0b50-5aff-a407-3d000fbb13ed', NULL, 5, 5, 'They, whether they will hear, or whether they will forbear, (for they are a rebellious house), yet shall know that there has been a prophet among them.'),
  ('85421215-a124-5dab-a1c2-ca7f5e349a2e', '97dc9284-0b50-5aff-a407-3d000fbb13ed', NULL, 6, 6, 'You, son of man, don''t be afraid of them, neither be afraid of their words, though briers and thorns are with you, and you do dwell among scorpions: don''t be afraid of their words, nor be dismayed at their looks, though they are a rebellious house.'),
  ('de348b77-18a6-5ee0-a37f-750d2564eac1', '97dc9284-0b50-5aff-a407-3d000fbb13ed', NULL, 7, 7, 'You shall speak my words to them, whether they will hear, or whether they will forbear; for they are most rebellious.'),
  ('e375ef86-c4b7-565c-a791-cb2e79400545', '97dc9284-0b50-5aff-a407-3d000fbb13ed', NULL, 8, 8, 'But you, son of man, hear what I tell you; don''t be rebellious like that rebellious house: open your mouth, and eat that which I give you.'),
  ('1b90c1e1-059b-5a83-af00-a6b48f2bab7e', '97dc9284-0b50-5aff-a407-3d000fbb13ed', NULL, 9, 9, 'When I looked, behold, a hand was put forth to me; and, behold, a scroll of a book was therein;'),
  ('5e0b304e-34a1-58b0-af55-b3cbbf433764', '97dc9284-0b50-5aff-a407-3d000fbb13ed', NULL, 10, 10, 'He spread it before me: and it was written within and without; and there were written therein lamentations, and mourning, and woe.'),
  ('c908298f-107c-5f48-afd7-468e38dc67fc', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 1, 1, 'He said to me, Son of man, eat that which you find. Eat this scroll, and go, speak to the house of Israel.'),
  ('7d59b4a3-88df-53b5-a5c8-c249b4a8e71e', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 2, 2, 'So I opened my mouth, and he caused me to eat the scroll.'),
  ('6227c86a-53bb-5fcb-a06f-c383c10ba457', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 3, 3, 'He said to me, Son of man, cause your belly to eat, and fill your bowels with this scroll that I give you. Then I ate it; and it was as sweet as honey in my mouth.'),
  ('f9be4467-78f7-5590-a94c-b3d146cc3178', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 4, 4, 'He said to me, Son of man, go to the house of Israel, and speak my words to them.'),
  ('6fbe9e82-99e4-5126-af08-34eb4697daf0', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 5, 5, 'For you are not sent to a people of a strange speech and of a hard language, but to the house of Israel;'),
  ('10d84a34-efbb-506e-a7d1-295a312f82bb', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 6, 6, 'not to many peoples of a strange speech and of a hard language, whose words you can not understand. Surely, if I sent you to them, they would listen to you.'),
  ('dd3e7c53-4c31-57ee-a8e7-85b9581d0fd9', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 7, 7, 'But the house of Israel will not listen to you; for they will not listen to me: for all the house of Israel are obstinate and hard-hearted.'),
  ('c7b2ca7d-24ad-5ef9-a115-7c94ef0c3815', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 8, 8, 'Behold, I have made your face hard against their faces, and your forehead hard against their foreheads.'),
  ('e7af713a-fff6-5992-a173-7704aadc5389', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 9, 9, 'As an adamant harder than flint have I made your forehead: don''t be afraid of them, neither be dismayed at their looks, though they are a rebellious house.'),
  ('5cac7565-eb73-5084-ae64-9f3a4ce7c5f8', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 10, 10, 'Moreover he said to me, Son of man, all my words that I shall speak to you receive in your heart, and hear with your ears.'),
  ('5638f092-d26f-5d0a-a4b0-85575baea826', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 11, 11, 'Go to them of the captivity, to the children of your people, and speak to them, and tell them, Thus says the Lord Yahweh; whether they will hear, or whether they will forbear.'),
  ('d66ff617-1b8b-5882-a704-649d0e45f80c', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 12, 12, 'Then the Spirit lifted me up, and I heard behind me the voice of a great rushing, [saying], Blessed be the glory of Yahweh from his place.'),
  ('6eb3794b-8dd2-525b-ac77-be94f3b4b256', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 13, 13, '[I heard] the noise of the wings of the living creatures as they touched one another, and the noise of the wheels beside them, even the noise of a great rushing.'),
  ('745a069b-ecde-5c92-aeca-d7a7f6c42d85', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 14, 14, 'So the Spirit lifted me up, and took me away; and I went in bitterness, in the heat of my spirit; and the hand of Yahweh was strong on me.'),
  ('730ed39b-876b-5cd9-aa59-15a763d39794', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 15, 15, 'Then I came to them of the captivity at Tel Aviv, that lived by the river Chebar, and to where they lived; and I sat there overwhelmed among them seven days.'),
  ('7f93ad49-2c7c-560c-a8b4-21f5dbff54ce', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 16, 16, 'It happened at the end of seven days, that the word of Yahweh came to me, saying,'),
  ('da0f09c9-1713-51ce-ab51-25c4ff2be89d', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 17, 17, 'Son of man, I have made you a watchman to the house of Israel: therefore hear the word from my mouth, and give them warning from me.'),
  ('3aa71d0a-3658-5e81-a855-3ae8164e7b91', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 18, 18, 'When I tell the wicked, You shall surely die; and you give him no warning, nor speak to warn the wicked from his wicked way, to save his life; the same wicked man shall die in his iniquity; but his blood will I require at your hand.'),
  ('9fc4cd5e-b675-50c9-a6c5-716088b30f23', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 19, 19, 'Yet if you warn the wicked, and he doesn''t turn from his wickedness, nor from his wicked way, he shall die in his iniquity; but you have delivered your soul.'),
  ('0f50870a-84f3-5472-a8ab-6daec34664cc', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 20, 20, 'Again, when a righteous man does turn from his righteousness, and commit iniquity, and I lay a stumbling block before him, he shall die: because you have not given him warning, he shall die in his sin, and his righteous deeds which he has done shall not be remembered; but his blood will I require at your hand.'),
  ('3d50204c-646a-5bef-aea8-70f3c3f5bbea', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 21, 21, 'Nevertheless if you warn the righteous man, that the righteous not sin, and he does not sin, he shall surely live, because he took warning; and you have delivered your soul.'),
  ('0c750425-636c-57f1-acb8-b6255896a92d', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 22, 22, 'The hand of Yahweh was there on me; and he said to me, Arise, go forth into the plain, and I will there talk with you.'),
  ('13217311-42c0-530c-aa84-70c884eb7623', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 23, 23, 'Then I arose, and went forth into the plain: and behold, the glory of Yahweh stood there, as the glory which I saw by the river Chebar; and I fell on my face.'),
  ('5b652192-803a-55eb-af00-d27dec5dcb2b', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 24, 24, 'Then the Spirit entered into me, and set me on my feet; and he spoke with me, and said to me, Go, shut yourself inside your house.'),
  ('d3fbda42-648a-58fa-a457-b25242c448ea', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 25, 25, 'But you, son of man, behold, they shall lay bands on you, and shall bind you with them, and you shall not go out among them:'),
  ('f7c00536-9698-5ca8-ae46-910b1456fc3f', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 26, 26, 'and I will make your tongue stick to the roof of your mouth, that you shall be mute, and shall not be to them a reprover; for they are a rebellious house.'),
  ('456a5c5a-a185-5d8a-a6af-cc5ddff80226', '922a1903-cd17-5ef8-a696-4678073a71d3', NULL, 27, 27, 'But when I speak with you, I will open your mouth, and you shall tell them, Thus says the Lord Yahweh: He who hears, let him hear; and he who forbears, let him forbear: for they are a rebellious house.'),
  ('b893c376-ee48-53af-a1f1-e66a14984ea4', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 1, 1, 'You also, son of man, take a tile, and lay it before yourself, and portray on it a city, even Jerusalem:'),
  ('72015383-dc03-5a5a-a833-725927704316', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 2, 2, 'and lay siege against it, and build forts against it, and cast up a mound against it; set camps also against it, and plant battering rams against it all around.'),
  ('a6fe1463-ddcb-55fb-a74f-75d914c42565', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 3, 3, 'Take for yourself an iron pan, and set it for a wall of iron between you and the city: and set your face toward it, and it shall be besieged, and you shall lay siege against it. This shall be a sign to the house of Israel.'),
  ('0d3c3c5c-24f1-5ea0-aacc-a51d53526e32', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 4, 4, 'Moreover lie on your left side, and lay the iniquity of the house of Israel on it; [according to] the number of the days that you shall lie on it, you shall bear their iniquity.'),
  ('4a8d22f2-cce5-5120-a79c-2109c3efb40e', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 5, 5, 'For I have appointed the years of their iniquity to be to you a number of days, even three hundred ninety days: so you shall bear the iniquity of the house of Israel.'),
  ('ff50f619-a6df-54cb-a6fe-7b9fac94d601', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 6, 6, 'Again, when you have accomplished these, you shall lie on your right side, and shall bear the iniquity of the house of Judah: forty days, each day for a year, have I appointed it to you.'),
  ('91cc7d9e-ae9e-5d90-a9dd-419ee8673847', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 7, 7, 'You shall set your face toward the siege of Jerusalem, with your arm uncovered; and you shall prophesy against it.'),
  ('498c0892-f1f3-5f7f-a015-d4339953ef45', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 8, 8, 'Behold, I lay bands on you, and you shall not turn you from one side to the other, until you have accomplished the days of your siege.'),
  ('99c4ef5d-51d9-5244-a641-8018b48b8f6f', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 9, 9, 'Take for yourself also wheat, and barley, and beans, and lentils, and millet, and spelt, and put them in one vessel, and make bread of it; [according to] the number of the days that you shall lie on your side, even three hundred ninety days, you shall eat of it.'),
  ('712c2ab6-bbaa-5d7d-ae22-a166c518627f', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 10, 10, 'Your food which you shall eat shall be by weight, twenty shekels a day: from time to time you shall eat it.'),
  ('a50e4c52-ffde-5e84-ac6e-d620c4b5311f', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 11, 11, 'You shall drink water by measure, the sixth part of a hin: from time to time you shall drink.'),
  ('2907cd00-8afb-513b-a98a-8578ba8840bb', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 12, 12, 'You shall eat it as barley cakes, and you shall bake it in their sight with dung that comes out of man.'),
  ('1767ab1f-73ee-5da1-aac8-bced61d8edfa', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 13, 13, 'Yahweh said, Even thus shall the children of Israel eat their bread unclean, among the nations where I will drive them.'),
  ('fd3a1b5d-e916-5caa-a0d4-72cfc1476642', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 14, 14, 'Then I said, Ah Lord Yahweh! behold, my soul has not been polluted; for from my youth up even until now have I not eaten of that which dies of itself, or is torn of animals; neither came there abominable flesh into my mouth.'),
  ('17c62ee6-8211-55ed-a300-bc45ed05d638', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 15, 15, 'Then he said to me, Behold, I have given you cow''s dung for man''s dung, and you shall prepare your bread thereon.'),
  ('1e30df6b-cd91-59c5-aad1-d739462331e8', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 16, 16, 'Moreover he said to me, Son of man, behold, I will break the staff of bread in Jerusalem: and they shall eat bread by weight, and with fearfulness; and they shall drink water by measure, and in dismay:'),
  ('7e1da4a0-95b5-550a-a1ff-2f44be2a83ed', '64add0b6-cdc5-5bdc-a06b-1b31c58eb714', NULL, 17, 17, 'that they may want bread and water, and be dismayed one with another, and pine away in their iniquity.'),
  ('9fd20d42-f074-535f-abca-46b85556cc69', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 1, 1, 'You, son of man, take a sharp sword; You shall take it as a barber''s razor to you, and shall cause it to pass on your head and on your beard: then take balances to weigh, and divide the hair.'),
  ('05193655-682c-594a-aa4c-25a47fbbd1f0', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 2, 2, 'A third part you shall burn in the fire in the midst of the city, when the days of the siege are fulfilled; and you shall take a third part, and strike with the sword around it; and a third part you shall scatter to the wind, and I will draw out a sword after them.'),
  ('a836012b-bb2c-5ab1-ac26-5c89ffa01cf7', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 3, 3, 'You shall take of it a few in number, and bind them in your skirts.'),
  ('6f6ea02a-f032-5c7a-a6ca-fa91b89c08ba', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 4, 4, 'Of these again you shall take, and cast them into the midst of the fire, and burn them in the fire; from it shall a fire come forth into all the house of Israel.'),
  ('e13e66cb-161c-5ff4-ac92-171691ea554d', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 5, 5, 'Thus says the Lord Yahweh: This is Jerusalem; I have set her in the midst of the nations, and countries are around her.'),
  ('168ed711-2077-563c-a3a5-9e8f07eb0cd5', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 6, 6, 'She has rebelled against my ordinances in doing wickedness more than the nations, and against my statutes more than the countries that are around her; for they have rejected my ordinances, and as for my statutes, they have not walked in them.'),
  ('4ddbea51-6888-5b78-ab09-baf489634981', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 7, 7, 'Therefore thus says the Lord Yahweh: Because you are turbulent more than the nations that are around you, and have not walked in my statutes, neither have kept my ordinances, neither have done after the ordinances of the nations that are around you;'),
  ('8e97ccf3-83e4-59bb-aa47-c5bb481d1368', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 8, 8, 'therefore thus says the Lord Yahweh: Behold, I, even I, am against you; and I will execute judgments in the midst of you in the sight of the nations.'),
  ('bd650010-2d43-51bf-aa3f-5bf60c4f9f3a', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 9, 9, 'I will do in you that which I have not done, and whereunto I will not do any more the like, because of all your abominations.'),
  ('8659734f-a4f3-56fc-aa20-6dc18a77ab33', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 10, 10, 'Therefore the fathers shall eat the sons in the midst of you, and the sons shall eat their fathers; and I will execute judgments on you; and the whole remnant of you will I scatter to all the winds.'),
  ('190c8653-6b79-52e4-a007-f2bf6fc2d6c2', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 11, 11, 'Therefore, as I live, says the Lord Yahweh, surely, because you have defiled my sanctuary with all your detestable things, and with all your abominations, therefore will I also diminish [you]; neither shall my eye spare, and I also will have no pity.'),
  ('62a62973-079d-5431-a3e8-067ca7f6bc8b', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 12, 12, 'A third part of you shall die with the pestilence, and with famine shall they be consumed in the midst of you; and a third part shall fall by the sword around you; and a third part I will scatter to all the winds, and will draw out a sword after them.'),
  ('ca10a889-2273-5334-a9de-6cf00f090590', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 13, 13, 'Thus shall my anger be accomplished, and I will cause my wrath toward them to rest, and I shall be comforted; and they shall know that I, Yahweh, have spoken in my zeal, when I have accomplished my wrath on them.'),
  ('d3255b01-1f98-5a09-abc0-968efb480a7f', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 14, 14, 'Moreover I will make you a desolation and a reproach among the nations that are around you, in the sight of all that pass by.'),
  ('f58e97f2-abc3-59ce-a74c-bd05be08006f', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 15, 15, 'So it shall be a reproach and a taunt, an instruction and an astonishment, to the nations that are around you, when I shall execute judgments on you in anger and in wrath, and in wrathful rebukes; (I, Yahweh, have spoken it;)'),
  ('b8c5fb62-be31-52e8-a686-87c8f4540f29', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 16, 16, 'when I shall send on them the evil arrows of famine, that are for destruction, which I will send to destroy you: and I will increase the famine on you, and will break your staff of bread;'),
  ('119cb60b-cf94-52dd-af5b-2c657bfecf93', '3079d9c3-468d-5961-abdf-5de89d0f1041', NULL, 17, 17, 'and I will send on you famine and evil animals, and they shall bereave you; and pestilence and blood shall pass through you; and I will bring the sword on you: I, Yahweh, have spoken it.'),
  ('7ee1e258-d496-5f36-ac32-694145d27aa8', '9c477df4-62bf-5657-a3db-5b3c688922e1', NULL, 1, 1, 'The word of Yahweh came to me, saying,'),
  ('ebcecd86-d3dd-50c0-a8d3-6da50709d6ac', '9c477df4-62bf-5657-a3db-5b3c688922e1', NULL, 2, 2, 'Son of man, set your face toward the mountains of Israel, and prophesy to them,'),
  ('f7e8255f-30c4-5ca2-a918-bef742c3c98a', '9c477df4-62bf-5657-a3db-5b3c688922e1', NULL, 3, 3, 'and say, You mountains of Israel, hear the word of the Lord Yahweh: Thus says the Lord Yahweh to the mountains and to the hills, to the watercourses and to the valleys: Behold, I, even I, will bring a sword on you, and I will destroy your high places.'),
  ('a220f252-344f-50da-af3d-1a899cb07aea', '9c477df4-62bf-5657-a3db-5b3c688922e1', NULL, 4, 4, 'Your altars shall become desolate, and your incense altars shall be broken; and I will cast down your slain men before your idols.'),
  ('4afc2a48-8b45-5df1-a4e3-1c57277eade4', '9c477df4-62bf-5657-a3db-5b3c688922e1', NULL, 5, 5, 'I will lay the dead bodies of the children of Israel before their idols; and I will scatter your bones around your altars.'),
  ('96a3b11c-890d-59e2-ab3e-fcfa73dcf9e9', '9c477df4-62bf-5657-a3db-5b3c688922e1', NULL, 6, 6, 'In all your dwelling places the cities shall be laid waste, and the high places shall be desolate; that your altars may be laid waste and made desolate, and your idols may be broken and cease, and your incense altars may be cut down, and your works may be abolished.'),
  ('4baf75ec-073d-5133-a192-b20bdaae46a4', '9c477df4-62bf-5657-a3db-5b3c688922e1', NULL, 7, 7, 'The slain shall fall in the midst of you, and you shall know that I am Yahweh.'),
  ('6d86420e-55c8-58d9-a93c-92e5a2b0480c', '9c477df4-62bf-5657-a3db-5b3c688922e1', NULL, 8, 8, 'Yet will I leave a remnant, in that you shall have some that escape the sword among the nations, when you shall be scattered through the countries.'),
  ('8da1991f-1eb3-5d5d-ab43-0902c84c13bd', '9c477df4-62bf-5657-a3db-5b3c688922e1', NULL, 9, 9, 'Those of you that escape shall remember me among the nations where they shall be carried captive, how that I have been broken with their lewd heart, which has departed from me, and with their eyes, which play the prostitute after their idols: and they shall loathe themselves in their own sight for the evils which they have committed in all their abominations.'),
  ('edf67cc0-4ae0-59a2-adb6-03805fa9b2a2', '9c477df4-62bf-5657-a3db-5b3c688922e1', NULL, 10, 10, 'They shall know that I am Yahweh: I have not said in vain that I would do this evil to them.'),
  ('61450358-0087-5ad7-a449-8726246379af', '9c477df4-62bf-5657-a3db-5b3c688922e1', NULL, 11, 11, 'Thus says the Lord Yahweh: Strike with your hand, and stamp with your foot, and say, Alas! because of all the evil abominations of the house of Israel; for they shall fall by the sword, by the famine, and by the pestilence.'),
  ('78f0e429-d346-57b3-ad62-ff632de00d68', '9c477df4-62bf-5657-a3db-5b3c688922e1', NULL, 12, 12, 'He who is far off shall die of the pestilence; and he who is near shall fall by the sword; and he who remains and is besieged shall die by the famine: thus will I accomplish my wrath on them.'),
  ('52799b28-873f-5c3b-ac9e-86ee1b44b8bb', '9c477df4-62bf-5657-a3db-5b3c688922e1', NULL, 13, 13, 'You shall know that I am Yahweh, when their slain men shall be among their idols around their altars, on every high hill, on all the tops of the mountains, and under every green tree, and under every thick oak, the places where they offered pleasant aroma to all their idols.'),
  ('4149dad5-c8bc-5a45-aba4-42a9314b105b', '9c477df4-62bf-5657-a3db-5b3c688922e1', NULL, 14, 14, 'I will stretch out my hand on them, and make the land desolate and waste, from the wilderness toward Diblah, throughout all their habitations: and they shall know that I am Yahweh.'),
  ('57d4af90-fe2e-5a14-a75b-480218c048db', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 1, 1, 'Moreover the word of Yahweh came to me, saying,'),
  ('991e3c0e-7172-57fe-a4e6-5079d06f43ab', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 2, 2, 'You, son of man, thus says the Lord Yahweh to the land of Israel, An end: the end is come on the four corners of the land.'),
  ('a8b4f936-e543-5005-a585-b1c86cdd00c9', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 3, 3, 'Now is the end on you, and I will send my anger on you, and will judge you according to your ways; and I will bring on you all your abominations.'),
  ('00a7c4f2-111c-517d-adc7-b7c3d26dded6', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 4, 4, 'My eye shall not spare you, neither will I have pity; but I will bring your ways on you, and your abominations shall be in the midst of you: and you shall know that I am Yahweh.'),
  ('a7bbb897-e432-5473-ac1d-e0b539bb4c69', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 5, 5, 'Thus says the Lord Yahweh: An evil, an only evil; behold, it comes.'),
  ('87f8e871-ed7a-5624-a2a2-0db7e22c0080', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 6, 6, 'An end has come, the end has come; it awakes against you; behold, it comes.'),
  ('2fc891ee-8725-50e4-a772-e66e0d1083d9', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 7, 7, 'Your doom has come to you, inhabitant of the land: the time has come, the day is near, [a day of] tumult, and not [of] joyful shouting, on the mountains.'),
  ('9dc5e97c-1f12-589e-a351-c23ed5d49057', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 8, 8, 'Now will I shortly pour out my wrath on you, and accomplish my anger against you, and will judge you according to your ways; and I will bring on you all your abominations.'),
  ('12996e50-6460-51c5-a8cd-ebaef1ec1d2a', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 9, 9, 'My eye shall not spare, neither will I have pity: I will bring on you according to your ways; and your abominations shall be in the midst of you; and you shall know that I, Yahweh, do strike.'),
  ('0ee06f51-b272-5535-a321-1db81b78bcbf', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 10, 10, 'Behold, the day, behold, it comes: your doom is gone forth; the rod has blossomed, pride has budded.'),
  ('06da339d-bea4-5dd0-adc3-1cb99b696d9d', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 11, 11, 'Violence is risen up into a rod of wickedness; none of them [shall remain], nor of their multitude, nor of their wealth: neither shall there be eminency among them.'),
  ('cabfb30a-5a51-517b-ab14-1131255eb859', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 12, 12, 'The time is come, the day draws near: don''t let the buyer rejoice, nor the seller mourn; for wrath is on all its multitude.'),
  ('1e56b249-1edc-5610-a242-f78a3fe04cc5', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 13, 13, 'For the seller shall not return to that which is sold, although they be yet alive: for the vision is touching the whole multitude of it, none shall return; neither shall any strengthen himself in the iniquity of his life.'),
  ('5acdf25b-50ec-5a7b-a3e1-eb14240f302e', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 14, 14, 'They have blown the trumpet, and have made all ready; but none goes to the battle; for my wrath is on all its multitude.'),
  ('9b6c94d6-440c-5d96-aa51-cce0ee716ed2', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 15, 15, 'The sword is outside, and the pestilence and the famine within: he who is in the field shall die with the sword: and he who is in the city, famine and pestilence shall devour him.'),
  ('c46fe37f-476c-5ce0-aa42-aa9b06659621', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 16, 16, 'But those of those who escape shall escape, and shall be on the mountains like doves of the valleys, all of them moaning, every one in his iniquity.'),
  ('a45f1f4c-f130-5fcf-a1d7-2a30498e34aa', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 17, 17, 'All hands shall be feeble, and all knees shall be weak as water.'),
  ('884eb8dd-f1c3-51b7-ab4f-0b782d263f84', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 18, 18, 'They shall also clothe themselves with sackcloth, and horror shall cover them; and shame shall be on all faces, and baldness on all their heads.'),
  ('4ca2c065-fbb5-5930-ade9-7dfdcdeef078', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 19, 19, 'They shall cast their silver in the streets, and their gold shall be as an unclean thing; their silver and their gold shall not be able to deliver them in the day of the wrath of Yahweh: they shall not satisfy their souls, neither fill their bowels; because it has been the stumbling block of their iniquity.'),
  ('c31d35cc-18b7-5634-aef9-260ae6788e78', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 20, 20, 'As for the beauty of his ornament, he set it in majesty; but they made the images of their abominations [and] their detestable things therein: therefore have I made it to them as an unclean thing.'),
  ('0597297a-6a1b-50a4-ad2a-1867c5bb619b', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 21, 21, 'I will give it into the hands of the strangers for a prey, and to the wicked of the earth for a spoil; and they shall profane it.'),
  ('b62de3bc-f7d6-5de9-a054-b87784a813f8', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 22, 22, 'My face will I turn also from them, and they shall profane my secret [place]; and robbers shall enter into it, and profane it.'),
  ('1f363be8-261d-5837-a8f7-a84204b2fde1', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 23, 23, 'Make the chain; for the land is full of bloody crimes, and the city is full of violence.'),
  ('2caad217-2893-5efb-a5b2-2af42e03ce42', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 24, 24, 'Therefore I will bring the worst of the nations, and they shall possess their houses: I will also make the pride of the strong to cease; and their holy places shall be profaned.'),
  ('487f1b40-0b1b-52ef-abda-385f844eaa05', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 25, 25, 'Destruction comes; and they shall seek peace, and there shall be none.'),
  ('89bd722b-2a0b-5af4-a129-314371d41617', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 26, 26, 'Mischief shall come on mischief, and rumor shall be on rumor; and they shall seek a vision of the prophet; but the law shall perish from the priest, and counsel from the elders.'),
  ('df93c868-a9e2-5997-ac63-ea8f9396e9ea', '442d59a9-5c72-58d0-a4ad-4c7fac65beb4', NULL, 27, 27, 'The king shall mourn, and the prince shall be clothed with desolation, and the hands of the people of the land shall be troubled: I will do to them after their way, and according to their own judgments will I judge them; and they shall know that I am Yahweh.'),
  ('589bc5b6-29c3-5630-a95d-a50ea7a9e701', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 1, 1, 'It happened in the sixth year, in the sixth [month], in the fifth [day] of the month, as I sat in my house, and the elders of Judah sat before me, that the hand of the Lord Yahweh fell there on me.'),
  ('6d712e25-2f83-5a98-ae49-5770ffb8574a', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 2, 2, 'Then I saw, and behold, a likeness as the appearance of fire; from the appearance of his waist and downward, fire; and from his waist and upward, as the appearance of brightness, as it were glowing metal.'),
  ('edd45155-2c5e-5f6d-afad-6b6291d35fca', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 3, 3, 'He put forth the form of a hand, and took me by a lock of my head; and the Spirit lifted me up between earth and the sky, and brought me in the visions of God to Jerusalem, to the door of the gate of the inner [court] that looks toward the north; where there was the seat of the image of jealousy, which provokes to jealousy.'),
  ('d9e07ce8-33aa-5830-aecd-4e4f73fd4ad0', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 4, 4, 'Behold, the glory of the God of Israel was there, according to the appearance that I saw in the plain.'),
  ('3000005a-e798-59fb-a009-2ce706d9d48b', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 5, 5, 'Then he said to me, Son of man, lift up your eyes now the way toward the north. So I lifted up my eyes the way toward the north, and see, northward of the gate of the altar this image of jealousy in the entry.'),
  ('0689c3bb-9041-5a80-a822-750577e7c8d4', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 6, 6, 'He said to me, Son of man, do you see what they do? even the great abominations that the house of Israel do commit here, that I should go far off from my sanctuary? But you shall again see yet other great abominations.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('3ccfd343-7b0c-507f-a1a8-a844f37cebac', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 7, 7, 'He brought me to the door of the court; and when I looked, behold, a hole in the wall.'),
  ('0cd07604-7a2a-52c9-aac5-e9784548013a', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 8, 8, 'Then he said to me, Son of man, dig now in the wall: and when I had dug in the wall, behold, a door.'),
  ('75395790-a216-5242-a8b5-584fa2004cc2', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 9, 9, 'He said to me, Go in, and see the wicked abominations that they do here.'),
  ('35564688-6e1b-5f6c-a18d-fb32d9f8ad72', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 10, 10, 'So I went in and saw; and see, every form of creeping things, and abominable animals, and all the idols of the house of Israel, portrayed around on the wall.'),
  ('fd1b8327-b8d8-5293-adb0-96740a4da3e0', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 11, 11, 'There stood before them seventy men of the elders of the house of Israel; and in the midst of them stood Jaazaniah the son of Shaphan, every man with his censer in his hand; and the odor of the cloud of incense went up.'),
  ('8dc4f2ce-2700-5aff-ae84-610d424b14cd', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 12, 12, 'Then he said to me, Son of man, have you seen what the elders of the house of Israel do in the dark, every man in his rooms of imagery? for they say, Yahweh doesn''t see us; Yahweh has forsaken the land.'),
  ('a3f252a5-5c78-535b-ab03-445924e9323b', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 13, 13, 'He said also to me, You shall again see yet other great abominations which they do.'),
  ('067606f6-00bb-5f2b-a212-924a39ccc492', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 14, 14, 'Then he brought me to the door of the gate of Yahweh''s house which was toward the north; and see, there sat the women weeping for Tammuz.'),
  ('1dfe63f1-2fae-5792-a956-193a94d5ca0b', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 15, 15, 'Then he said to me, Have you seen [this], son of man? You shall again see yet greater abominations than these.'),
  ('12481bf5-8ed5-51c3-af91-4fb0916fe9f7', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 16, 16, 'He brought me into the inner court of Yahweh''s house; and see, at the door of the temple of Yahweh, between the porch and the altar, were about twenty-five men, with their backs toward the temple of Yahweh, and their faces toward the east; and they were worshipping the sun toward the east.'),
  ('4bd1a7ca-f214-5f71-a8c0-5bc478d3a87b', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 17, 17, 'Then he said to me, Have you seen [this], son of man? Is it a light thing to the house of Judah that they commit the abominations which they commit here? for they have filled the land with violence, and have turned again to provoke me to anger: and behold, they put the branch to their nose.'),
  ('69fd69e5-6ed7-557d-a204-3c4030e61f96', '9df68e4c-7e54-596a-a0d9-403e62768c70', NULL, 18, 18, 'Therefore will I also deal in wrath; my eye shall not spare, neither will I have pity; and though they cry in my ears with a loud voice, yet will I not hear them.'),
  ('08649141-321d-59b9-abc8-d4eac82ea12f', '03f64b1c-cb1e-554f-a531-ab1fe4db6f4e', NULL, 1, 1, 'Then he cried in my ears with a loud voice, saying, Cause those who are in charge of the city to draw near, every man with his destroying weapon in his hand.'),
  ('07b6f9cd-69c8-5740-a342-24c6bcd11b57', '03f64b1c-cb1e-554f-a531-ab1fe4db6f4e', NULL, 2, 2, 'Behold, six men came from the way of the upper gate, which lies toward the north, every man with his slaughter weapon in his hand; and one man in the midst of them clothed in linen, with a writer''s inkhorn by his side. They went in, and stood beside the bronze altar.'),
  ('95ed2a79-a1c5-5199-aa17-3b9a89a2fd79', '03f64b1c-cb1e-554f-a531-ab1fe4db6f4e', NULL, 3, 3, 'The glory of the God of Israel was gone up from the cherub, whereupon it was, to the threshold of the house: and he called to the man clothed in linen, who had the writer''s inkhorn by his side.'),
  ('28dbfb17-c5c6-5376-ac0b-28981c1b6a87', '03f64b1c-cb1e-554f-a531-ab1fe4db6f4e', NULL, 4, 4, 'Yahweh said to him, Go through the midst of the city, through the midst of Jerusalem, and set a mark on the foreheads of the men that sigh and that cry over all the abominations that are done in its midst.'),
  ('55329d85-b239-5dad-a3aa-7d5032b6c197', '03f64b1c-cb1e-554f-a531-ab1fe4db6f4e', NULL, 5, 5, 'To the others he said in my hearing, Go through the city after him, and strike: don''t let your eye spare, neither have pity;'),
  ('cd0acb5a-40b6-52c3-a29b-f31af9a3ba0c', '03f64b1c-cb1e-554f-a531-ab1fe4db6f4e', NULL, 6, 6, 'kill utterly the old man, the young man and the virgin, and little children and women; but don''t come near any man on whom is the mark: and begin at my sanctuary. Then they began at the old men that were before the house.'),
  ('d68fff6d-6fa0-58ed-ae13-a77c65f7d2d0', '03f64b1c-cb1e-554f-a531-ab1fe4db6f4e', NULL, 7, 7, 'He said to them, Defile the house, and fill the courts with the slain. Go forth! They went forth, and struck in the city.'),
  ('6ffa3270-11cd-5b52-aec9-a28299854685', '03f64b1c-cb1e-554f-a531-ab1fe4db6f4e', NULL, 8, 8, 'It happened, while they were smiting, and I was left, that I fell on my face, and cried, and said, Ah Lord Yahweh! will you destroy all the residue of Israel in your pouring out of your wrath on Jerusalem?'),
  ('d7846538-65c2-50a7-aad5-4786d57f5f23', '03f64b1c-cb1e-554f-a531-ab1fe4db6f4e', NULL, 9, 9, 'Then he said to me, The iniquity of the house of Israel and Judah is exceedingly great, and the land is full of blood, and the city full of perversion: for they say, Yahweh has forsaken the land, and Yahweh doesn''t see.'),
  ('20b1be88-19b1-5180-a5e0-23d049fcfa3e', '03f64b1c-cb1e-554f-a531-ab1fe4db6f4e', NULL, 10, 10, 'As for me also, my eye shall not spare, neither will I have pity, but I will bring their way on their head.'),
  ('aef198be-4a0f-5418-acb6-c13d865fb40d', '03f64b1c-cb1e-554f-a531-ab1fe4db6f4e', NULL, 11, 11, 'Behold, the man clothed in linen, who had the inkhorn by his side, reported the matter, saying, I have done as you have commanded me.'),
  ('cc5008ff-fe31-5916-a420-e21f310326e6', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 1, 1, 'Then I looked, and see, in the expanse that was over the head of the cherubim there appeared above them as it were a sapphire stone, as the appearance of the likeness of a throne.'),
  ('f5caeac2-a2cd-5d6f-a2fe-244bf5273b1b', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 2, 2, 'He spoke to the man clothed in linen, and said, Go in between the whirling [wheels], even under the cherub, and fill both your hands with coals of fire from between the cherubim, and scatter them over the city. He went in as I watched.'),
  ('57ce54f9-7b6f-5764-a582-745c8bbb2a3a', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 3, 3, 'Now the cherubim stood on the right side of the house, when the man went in; and the cloud filled the inner court.'),
  ('876c50e7-b0a5-59b9-a014-98da66e0864b', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 4, 4, 'The glory of Yahweh mounted up from the cherub, [and stood] over the threshold of the house; and the house was filled with the cloud, and the court was full of the brightness of Yahweh''s glory.'),
  ('d3d3d958-afdb-5847-af95-f9a2839e3c76', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 5, 5, 'The sound of the wings of the cherubim was heard even to the outer court, as the voice of God Almighty when he speaks.'),
  ('ace146c0-db84-5c49-a3ed-5ce744481606', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 6, 6, 'It came to pass, when he commanded the man clothed in linen, saying, Take fire from between the whirling wheels, from between the cherubim, that he went in, and stood beside a wheel.'),
  ('f17ebc42-9111-575a-af07-52247cd190be', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 7, 7, 'The cherub stretched forth his hand from between the cherubim to the fire that was between the cherubim, and took [of it], and put it into the hands of him who was clothed in linen, who took it and went out.'),
  ('e2d479e4-b9a4-5194-ae55-1fbd5aa02779', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 8, 8, 'There appeared in the cherubim the form of a man''s hand under their wings.'),
  ('07070b7f-4ef2-5384-aad1-ab536c45535d', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 9, 9, 'I looked, and behold, four wheels beside the cherubim, one wheel beside one cherub, and another wheel beside another cherub; and the appearance of the wheels was like a beryl stone.'),
  ('f7e1c467-481d-52e6-a494-89a656f3b52d', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 10, 10, 'As for their appearance, the four of them had one likeness, like a wheel within a wheel.'),
  ('033ad43c-c041-5c02-aea8-85dbc405a533', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 11, 11, 'When they went, they went in their four directions: they didn''t turn as they went, but to the place where the head looked they followed it; they didn''t turn as they went.'),
  ('be1c46d8-2f02-5526-a47d-350346e29974', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 12, 12, 'Their whole body, and their backs, and their hands, and their wings, and the wheels, were full of eyes all around, [even] the wheels that the four of them had.'),
  ('ef7438e0-710f-5f86-afd0-9add9eed9b7b', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 13, 13, 'As for the wheels, they were called in my hearing, the whirling [wheels].'),
  ('6ebf68bb-85fd-5669-a1f3-4133d92e6219', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 14, 14, 'Every one had four faces: the first face was the face of the cherub, and the second face was the face of a man, and the third face the face of a lion, and the fourth the face of an eagle.'),
  ('fbd6a40f-2466-52fa-a3b4-835f48083e8a', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 15, 15, 'The cherubim mounted up: this is the living creature that I saw by the river Chebar.'),
  ('60e197cb-14bc-58de-a35c-934dfa22c7b7', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 16, 16, 'When the cherubim went, the wheels went beside them; and when the cherubim lifted up their wings to mount up from the earth, the wheels also didn''t turn from beside them.'),
  ('2212f781-14b4-5ff3-af3f-d96b1ffe5b9e', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 17, 17, 'When they stood, these stood; and when they mounted up, these mounted up with them: for the spirit of the living creature was in them.'),
  ('5f7dd99d-dfd8-5850-a2a4-3918a432f2ef', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 18, 18, 'The glory of Yahweh went forth from over the threshold of the house, and stood over the cherubim.'),
  ('73024a58-ce7b-5b4c-ad67-2a581888280e', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 19, 19, 'The cherubim lifted up their wings, and mounted up from the earth in my sight when they went forth, and the wheels beside them: and they stood at the door of the east gate of Yahweh''s house; and the glory of the God of Israel was over them above.'),
  ('454872a2-9000-5142-abbb-b721b0085d4c', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 20, 20, 'This is the living creature that I saw under the God of Israel by the river Chebar; and I knew that they were cherubim.'),
  ('7634de78-6866-5b6d-a950-3642c9071c5e', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 21, 21, 'Every one had four faces, and every one four wings; and the likeness of the hands of a man was under their wings.'),
  ('87cc4ee9-78d3-5611-a3b9-42c18d1c363c', '8c138a81-1eef-5cd9-a6c8-d680d93508a3', NULL, 22, 22, 'As for the likeness of their faces, they were the faces which I saw by the river Chebar, their appearances and themselves; they went every one straight forward.'),
  ('104591b4-368f-557d-a6cf-4b88794fc064', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 1, 1, 'Moreover the Spirit lifted me up, and brought me to the east gate of Yahweh''s house, which looks eastward: and see, at the door of the gate twenty-five men; and I saw in the midst of them Jaazaniah the son of Azzur, and Pelatiah the son of Benaiah, princes of the people.'),
  ('89728877-6459-5bc3-a401-f5330c57e9aa', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 2, 2, 'He said to me, Son of man, these are the men who devise iniquity, and who give wicked counsel in this city;'),
  ('2a0873b5-b818-5534-a8bf-1e3580e44494', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 3, 3, 'who say, [The time] is not near to build houses: this [city] is the caldron, and we are the flesh.'),
  ('0156b786-d97d-5c52-af5c-576307a754b8', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 4, 4, 'Therefore prophesy against them, prophesy, son of man.'),
  ('21b04234-326e-5499-a43d-bdfa7ad81bee', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 5, 5, 'The Spirit of Yahweh fell on me, and he said to me, Speak, Thus says Yahweh: Thus you have said, house of Israel; for I know the things that come into your mind.'),
  ('3f8821a4-10e3-53ec-a835-bfaf3d658c4b', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 6, 6, 'You have multiplied your slain in this city, and you have filled its streets with the slain.'),
  ('b88700a3-b4d8-515b-aef1-31d87a130ad5', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 7, 7, 'Therefore thus says the Lord Yahweh: Your slain whom you have laid in its midst, they are the flesh, and this [city] is the caldron; but you shall be brought forth out of its midst.'),
  ('f2069505-19b5-5c8f-ad35-ce8f359e41f4', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 8, 8, 'You have feared the sword; and I will bring the sword on you, says the Lord Yahweh.'),
  ('acc15668-6a88-5b1f-a371-8f3e21183a9d', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 9, 9, 'I will bring you forth out of its midst, and deliver you into the hands of strangers, and will execute judgments among you.'),
  ('0e2f2ef6-0f1b-5e6d-a772-7a45b573cb1b', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 10, 10, 'You shall fall by the sword; I will judge you in the border of Israel; and you shall know that I am Yahweh.'),
  ('c835a37d-4633-5b64-acec-d2e0d93b730d', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 11, 11, 'This [city] shall not be your caldron, neither shall you be the flesh in its midst; I will judge you in the border of Israel;'),
  ('12736b97-53c0-50ea-a527-21464ffbad8b', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 12, 12, 'and you shall know that I am Yahweh: for you have not walked in my statutes, neither have you executed my ordinances, but have done after the ordinances of the nations that are around you.'),
  ('6edf8960-e056-5c28-a922-a57e51fa6455', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 13, 13, 'It happened, when I prophesied, that Pelatiah the son of Benaiah died. Then fell I down on my face, and cried with a loud voice, and said, Ah Lord Yahweh! will you make a full end of the remnant of Israel?'),
  ('53deb9e1-5d4f-5697-a84d-5e59574c24f4', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 14, 14, 'The word of Yahweh came to me, saying,'),
  ('c4a4d4bc-17be-5b50-a8b3-97246a603678', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 15, 15, 'Son of man, your brothers, even your brothers, the men of your relatives, and all the house of Israel, all of them, [are they] to whom the inhabitants of Jerusalem have said, Go far away from Yahweh. This land has been given to us for a possession.'),
  ('4d19d57b-5c6d-5268-ad9c-bfa966aa07b5', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 16, 16, 'Therefore say, Thus says the Lord Yahweh: Whereas I have removed them far off among the nations, and whereas I have scattered them among the countries, yet will I be to them a sanctuary for a little while in the countries where they are come.'),
  ('dd77cc89-d733-5384-a6e9-e805983a4577', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 17, 17, 'Therefore say, Thus says the Lord Yahweh: I will gather you from the peoples, and assemble you out of the countries where you have been scattered, and I will give you the land of Israel.'),
  ('5e8ed14e-5fc0-5fb4-afd6-7f5e97c070d7', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 18, 18, 'They shall come there, and they shall take away all the detestable things of it and all its abominations from there.'),
  ('24618ffd-a2d8-5944-a6c1-fc0982aa2804', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 19, 19, 'I will give them one heart, and I will put a new spirit within you; and I will take the stony heart out of their flesh, and will give them a heart of flesh;'),
  ('e1f54658-dbd5-51e1-a6d3-f9acc693617b', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 20, 20, 'that they may walk in my statutes, and keep my ordinances, and do them: and they shall be my people, and I will be their God.'),
  ('8b0151d5-9502-5cc4-a93b-92a1ceb37364', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 21, 21, 'But as for them whose heart walks after the heart of their detestable things and their abominations, I will bring their way on their own heads, says the Lord Yahweh.'),
  ('acc595de-3d9e-5a02-ad0c-f6a72cdf0420', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 22, 22, 'Then did the cherubim lift up their wings, and the wheels were beside them; and the glory of the God of Israel was over them above.'),
  ('cff78bb8-d6c3-5771-aa72-253139ca59c4', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 23, 23, 'The glory of Yahweh went up from the midst of the city, and stood on the mountain which is on the east side of the city.'),
  ('78c41bfc-6d4b-59a9-a5ed-8ab3a6d99039', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 24, 24, 'The Spirit lifted me up, and brought me in the vision by the Spirit of God into Chaldea, to them of the captivity. So the vision that I had seen went up from me.'),
  ('b5f38cb0-6ee1-5e20-affe-a9b100e4acba', '6f1436ac-2cdd-5011-a29b-67bc59eae725', NULL, 25, 25, 'Then I spoke to them of the captivity all the things that Yahweh had shown me.'),
  ('4c722459-6441-50c6-a197-e025cb78e914', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 1, 1, 'The word of Yahweh also came to me, saying,'),
  ('0216e5ad-a66e-5bda-aa7d-5194c89f97d4', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 2, 2, 'Son of man, you dwell in the midst of the rebellious house, who have eyes to see, and don''t see, who have ears to hear, and don''t hear; for they are a rebellious house.'),
  ('4ec3264c-c754-5d39-a7cc-65f3d12063a9', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 3, 3, 'Therefore, you son of man, prepare your stuff for moving, and move by day in their sight; and you shall move from your place to another place in their sight: it may be they will consider, though they are a rebellious house.'),
  ('be437e9d-f618-5184-a154-81c6c6350783', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 4, 4, 'You shall bring forth your stuff by day in their sight, as stuff for moving; and you shall go forth yourself at even in their sight, as when men go forth into exile.'),
  ('5f687a11-5795-581a-a382-9fd39d9efdbe', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 5, 5, 'Dig through the wall in their sight, and carry your stuff out that way.'),
  ('c7fdd24c-d925-50d4-a79a-cdc45cb8f4f6', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 6, 6, 'In their sight you shall bear it on your shoulder, and carry it forth in the dark; you shall cover your face, so that you don''t see the land: for I have set you for a sign to the house of Israel.'),
  ('cfb24799-8887-55ce-af0f-4be3a1713562', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 7, 7, 'I did so as I was commanded: I brought forth my stuff by day, as stuff for removing, and in the even I dug through the wall with my hand; I brought it forth in the dark, and bore it on my shoulder in their sight.'),
  ('7e73b2fe-1284-5b4c-ab25-13edbe2009b4', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 8, 8, 'In the morning came the word of Yahweh to me, saying,'),
  ('d9798cfc-042f-5a3d-af14-88b9564d1527', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 9, 9, 'Son of man, has not the house of Israel, the rebellious house, said to you, What are you doing?'),
  ('00786cfd-a57f-5ffc-ae20-d793ea57a148', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 10, 10, 'Say to them, Thus says the Lord Yahweh: This burden [concerns] the prince in Jerusalem, and all the house of Israel among whom they are.'),
  ('20887d27-e9c8-5e15-a40c-38010c425ed5', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 11, 11, 'Say, I am your sign: like as I have done, so shall it be done to them; they shall go into exile, into captivity.'),
  ('5a54b73f-7ceb-5305-a071-decccc4a5265', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 12, 12, 'The prince who is among them shall bear on his shoulder in the dark, and shall go forth: they shall dig through the wall to carry out thereby: he shall cover his face, because he shall not see the land with his eyes.'),
  ('56c0c070-a96c-57f1-ad58-1ab2843fdf29', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 13, 13, 'My net also will I spread on him, and he shall be taken in my snare; and I will bring him to Babylon to the land of the Chaldeans; yet shall he not see it, though he shall die there.'),
  ('885ebebf-a93b-5d73-aee0-1fac9886e646', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 14, 14, 'I will scatter toward every wind all who are around him to help him, and all his bands; and I will draw out the sword after them.'),
  ('f2a860d8-229b-5421-a4d4-38d4751b1d17', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 15, 15, 'They shall know that I am Yahweh, when I shall disperse them among the nations, and scatter them through the countries.'),
  ('fa2ef62b-bade-5335-a334-19e6bcc5dce6', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 16, 16, 'But I will leave a few men of them from the sword, from the famine, and from the pestilence; that they may declare all their abominations among the nations where they come; and they shall know that I am Yahweh.'),
  ('f40fa201-fbdf-5aba-a043-e58372af44e5', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 17, 17, 'Moreover the word of Yahweh came to me, saying,'),
  ('80d913c4-0afc-50ee-a349-326550b99782', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 18, 18, 'Son of man, eat your bread with quaking, and drink your water with trembling and with fearfulness;'),
  ('aa4c024e-f717-5e77-a3ee-1597ea0e5256', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 19, 19, 'and tell the people of the land, Thus says the Lord Yahweh concerning the inhabitants of Jerusalem, and the land of Israel: They shall eat their bread with fearfulness, and drink their water in dismay, that her land may be desolate, [and despoiled] of all that is therein, because of the violence of all those who dwell therein.'),
  ('4af4349a-b20d-5ba1-a412-63a16914c765', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 20, 20, 'The cities that are inhabited shall be laid waste, and the land shall be a desolation; and you shall know that I am Yahweh.'),
  ('c15cf5e1-4607-5732-abf0-5c3bab2da59e', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 21, 21, 'The word of Yahweh came to me, saying,'),
  ('c640452a-53b5-55f2-a5c3-45269f957490', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 22, 22, 'Son of man, what is this proverb that you have in the land of Israel, saying, The days are prolonged, and every vision fails?'),
  ('ce16caed-478b-5633-a01b-6c4dc96be16a', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 23, 23, 'Tell them therefore, Thus says the Lord Yahweh: I will make this proverb to cease, and they shall no more use it as a proverb in Israel; but tell them, The days are at hand, and the fulfillment of every vision.'),
  ('6e037543-b10e-52d3-acee-0dcec4d60578', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 24, 24, 'For there shall be no more any false vision nor flattering divination within the house of Israel.'),
  ('e6799c86-465f-58ce-a9a2-c93e68334930', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 25, 25, 'For I am Yahweh; I will speak, and the word that I shall speak shall be performed; it shall be no more deferred: for in your days, rebellious house, will I speak the word, and will perform it, says the Lord Yahweh.'),
  ('f5afc58d-e4e9-54b0-a502-f0c5c7b6905e', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 26, 26, 'Again the word of Yahweh came to me, saying,'),
  ('27ed6cc7-db4e-5cdc-ab96-ee73beeabed3', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 27, 27, 'Son of man, behold, they of the house of Israel say, The vision that he sees is for many day to come, and he prophesies of times that are far off.'),
  ('1322e15d-402c-5512-a496-7eca808a4341', '418e8da4-ae63-5fac-ad70-011d4724bb2d', NULL, 28, 28, 'Therefore tell them, Thus says the Lord Yahweh: None of my words shall be deferred any more, but the word which I shall speak shall be performed, says the Lord Yahweh.'),
  ('02388317-a14d-523e-a79f-db18f0c82874', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 1, 1, 'The word of Yahweh came to me, saying,'),
  ('c5eb6742-717c-51c1-a689-d63fcce840a7', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 2, 2, 'Son of man, prophesy against the prophets of Israel who prophesy, and say to those who prophesy out of their own heart, Hear the word of Yahweh:'),
  ('4d5ec4a5-8673-5a87-a88d-a2642246077d', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 3, 3, 'Thus says the Lord Yahweh, Woe to the foolish prophets, who follow their own spirit, and have seen nothing!'),
  ('e8844988-683a-54f2-a328-697275c98c48', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 4, 4, 'Israel, your prophets have been like foxes in the waste places.'),
  ('ddc8a9a0-4af3-59ad-a836-93ce55da2e90', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 5, 5, 'You have not gone up into the gaps, neither built up the wall for the house of Israel, to stand in the battle in the day of Yahweh.'),
  ('1f493a4c-3caa-53b5-a8f9-3d90227ba965', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 6, 6, 'They have seen falsehood and lying divination, who say, Yahweh says; but Yahweh has not sent them: and they have made men to hope that the word would be confirmed.'),
  ('ea25f420-81ae-5423-a813-fdadf19a35e3', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 7, 7, 'Haven''t you seen a false vision, and haven''t you spoken a lying divination, in that you say, Yahweh says; but I have not spoken?'),
  ('22ef7396-a531-51e5-ae50-132fe91120cf', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 8, 8, 'Therefore thus says the Lord Yahweh: Because you have spoken falsehood, and seen lies, therefore, behold, I am against you, says the Lord Yahweh.'),
  ('f1669664-5fdb-5737-ab56-3d603c478054', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 9, 9, 'My hand shall be against the prophets who see false visions, and who divine lies: they shall not be in the council of my people, neither shall they be written in the writing of the house of Israel, neither shall they enter into the land of Israel; and you shall know that I am the Lord Yahweh.'),
  ('29403d6a-dbe6-55f5-a4f6-34df74303d09', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 10, 10, 'Because, even because they have seduced my people, saying, Peace; and there is no peace; and when one builds up a wall, behold, they plaster it with whitewash:'),
  ('0ad87af3-4f99-515b-a48a-5d5206381478', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 11, 11, 'tell those who plaster it with whitewash, that it shall fall: there shall be an overflowing shower; and you, great hailstones, shall fall; and a stormy wind shall tear it.'),
  ('de7a4854-23ef-57c2-a0c4-50797b80d7b5', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 12, 12, 'Behold, when the wall has fallen, shall it not be said to you, Where is the plaster with which you have plastered it?'),
  ('14c1d5b3-e709-594b-a88d-0d115d5ce80d', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 13, 13, 'Therefore thus says the Lord Yahweh: I will even tear it with a stormy wind in my wrath; and there shall be an overflowing shower in my anger, and great hailstones in wrath to consume it.'),
  ('91720371-2a41-5993-a823-cddd6ac7c544', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 14, 14, 'So will I break down the wall that you have plastered with whitewash, and bring it down to the ground, so that its foundation shall be uncovered; and it shall fall, and you shall be consumed in its midst: and you shall know that I am Yahweh.'),
  ('9485f056-f5c0-576d-a443-5562ea79a9b8', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 15, 15, 'Thus will I accomplish my wrath on the wall, and on those who have plastered it with whitewash; and I will tell you, The wall is no more, neither those who plastered it;'),
  ('3f983167-f9a7-565b-a37f-e413740dfd12', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 16, 16, '[to wit], the prophets of Israel who prophesy concerning Jerusalem, and who see visions of peace for her, and there is no peace, says the Lord Yahweh.'),
  ('cd893dfe-0a07-5d2b-adf6-5f43dcf8582f', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 17, 17, 'You, son of man, set your face against the daughters of your people, who prophesy out of their own heart; and prophesy against them,'),
  ('a50b7ff8-d76b-59d8-a2e2-29b07eb97dab', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 18, 18, 'and say, Thus says the Lord Yahweh: Woe to the women who sew pillows on all elbows, and make kerchiefs for the head of [persons of] every stature to hunt souls! Will you hunt the souls of my people, and save souls alive for yourselves?'),
  ('38d7e4a1-a29c-5944-a171-5eda4ab1a15f', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 19, 19, 'You have profaned me among my people for handfuls of barley and for pieces of bread, to kill the souls who should not die, and to save the souls alive who should not live, by your lying to my people who listen to lies.'),
  ('539183ba-2782-59a4-a8e9-26f8710418d2', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 20, 20, 'Therefore thus says the Lord Yahweh: Behold, I am against your pillows, with which you there hunt the souls to make [them] fly, and I will tear them from your arms; and I will let the souls go, even the souls whom you hunt to make [them] fly.'),
  ('13d15d0d-6caa-5b54-afea-afaf6f72fa43', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 21, 21, 'Your kerchiefs also will I tear, and deliver my people out of your hand, and they shall be no more in your hand to be hunted; and you shall know that I am Yahweh.'),
  ('7ffb7ac5-af55-5c81-ac89-24ac495399ea', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 22, 22, 'Because with lies you have grieved the heart of the righteous, whom I have not made sad; and strengthened the hands of the wicked, that he should not return from his wicked way, and be saved alive:'),
  ('659b3d03-5999-55f4-ab4d-ac6b074bac1c', '35c8573c-2f1e-5b8c-ab6c-a9a6485c01c1', NULL, 23, 23, 'Therefore you shall no more see false visions, nor practice divination. I will deliver my people out of your hand; and you shall know that I am Yahweh.'),
  ('b8c5eb9a-d9fc-594b-a0c2-95891a1d87bb', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 1, 1, 'Then came certain of the elders of Israel to me, and sat before me.'),
  ('81ad9abe-e67e-5bfe-a170-a3ea69a5d8fc', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 2, 2, 'The word of Yahweh came to me, saying,'),
  ('ea652847-814a-53cc-a175-140caf558b0a', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 3, 3, 'Son of man, these men have taken their idols into their heart, and put the stumbling block of their iniquity before their face: should I be inquired of at all by them?'),
  ('2e544561-5980-5e19-a879-ba458b2ab81b', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 4, 4, 'Therefore speak to them, and tell them, Thus says the Lord Yahweh: Every man of the house of Israel who takes his idols into his heart, and puts the stumbling block of his iniquity before his face, and comes to the prophet; I Yahweh will answer him therein according to the multitude of his idols;'),
  ('a995d3d4-ea50-55cc-a53b-ad1bf81f3fda', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 5, 5, 'that I may take the house of Israel in their own heart, because they are all estranged from me through their idols.'),
  ('7197e5b6-79ef-5ab7-aa38-22d1e5149d5f', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 6, 6, 'Therefore tell the house of Israel, Thus says the Lord Yahweh: Return, and turn yourselves from your idols; and turn away your faces from all your abominations.'),
  ('77acaa16-c46b-5808-ab5b-caaa4566f8d3', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 7, 7, 'For everyone of the house of Israel, or of the strangers who live in Israel, who separates himself from me, and takes his idols into his heart, and puts the stumbling block of his iniquity before his face, and comes to the prophet to inquire for himself of me; I Yahweh will answer him by myself:'),
  ('ce7c4a34-164a-5db7-a386-6737750949eb', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 8, 8, 'and I will set my face against that man, and will make him an astonishment, for a sign and a proverb, and I will cut him off from the midst of my people; and you shall know that I am Yahweh.'),
  ('aab1cc10-9ece-5287-a396-947605dba04c', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 9, 9, 'If the prophet is deceived and speak a word, I, Yahweh, have deceived that prophet, and I will stretch out my hand on him, and will destroy him from the midst of my people Israel.'),
  ('adbc71b1-0353-5ecd-a6a0-d279f7bf09da', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 10, 10, 'They shall bear their iniquity: the iniquity of the prophet shall be even as the iniquity of him who seeks [to him];'),
  ('928af238-5346-54c3-ae72-3ce3916c11ef', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 11, 11, 'that the house of Israel may go no more astray from me, neither defile themselves any more with all their transgressions; but that they may be my people, and I may be their God, says the Lord Yahweh.'),
  ('87edf59e-aa95-5b3b-a886-b702fb2d6167', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 12, 12, 'The word of Yahweh came to me, saying,'),
  ('a9ee4524-3cfa-5785-a675-6ff63f748bb4', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 13, 13, 'Son of man, when a land sins against me by committing a trespass, and I stretch out my hand on it, and break the staff of its bread, and send famine on it, and cut off from it man and animal;'),
  ('3593183a-9610-5a4e-abc3-45b5672c9345', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 14, 14, 'though these three men, Noah, Daniel, and Job, were in it, they should deliver but their own souls by their righteousness, says the Lord Yahweh.'),
  ('741e380a-2c8b-5455-ac83-7c5467b30109', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 15, 15, 'If I cause evil animals to pass through the land, and they ravage it, and it be made desolate, so that no man may pass through because of the animals;'),
  ('5aec1b75-e5bb-503d-a75e-75777801f50e', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 16, 16, 'though these three men were in it, as I live, says the Lord Yahweh, they should deliver neither sons nor daughters; they only should be delivered, but the land should be desolate.'),
  ('36c8e517-4759-5695-ad29-7759b21283f7', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 17, 17, 'Or if I bring a sword on that land, and say, Sword, go through the land; so that I cut off from it man and animal;'),
  ('300653b0-b876-5f2d-a5cd-a922ed35fd16', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 18, 18, 'though these three men were in it, as I live, says the Lord Yahweh, they should deliver neither sons nor daughters, but they only should be delivered themselves.'),
  ('b0a24cdf-4246-501d-a5b7-c4a8808b0f4f', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 19, 19, 'Or if I send a pestilence into that land, and pour out my wrath on it in blood, to cut off from it man and animal;'),
  ('fcd12218-a841-5e46-acbc-0400558a6069', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 20, 20, 'though Noah, Daniel, and Job, were in it, as I live, says the Lord Yahweh, they should deliver neither son nor daughter; they should but deliver their own souls by their righteousness.'),
  ('ff843e18-71ce-53ce-add1-905b7ee66b0f', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 21, 21, 'For thus says the Lord Yahweh: How much more when I send my four severe judgments on Jerusalem, the sword, and the famine, and the evil animals, and the pestilence, to cut off from it man and animal!'),
  ('34754621-3364-5747-a6d6-a893eaa9ae24', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 22, 22, 'Yet, behold, therein shall be left a remnant that shall be carried forth, both sons and daughters: behold, they shall come forth to you, and you shall see their way and their doings; and you shall be comforted concerning the evil that I have brought on Jerusalem, even concerning all that I have brought on it.'),
  ('4d9d4d48-5b0a-5667-a481-468ec9c3d6ef', 'face8276-a3d5-504e-a15f-b35741e0573f', NULL, 23, 23, 'They shall comfort you, when you see their way and their doings; and you shall know that I have not done without cause all that I have done in it, says the Lord Yahweh.'),
  ('80fcde25-51df-51e4-aeaa-322f9e253c67', '0cb74b0b-6eab-5c36-a75e-e1362de5c159', NULL, 1, 1, 'The word of Yahweh came to me, saying,'),
  ('58e56cc3-c571-5200-a1bc-f01678c68043', '0cb74b0b-6eab-5c36-a75e-e1362de5c159', NULL, 2, 2, 'Son of man, what is the vine tree more than any tree, the vine-branch which is among the trees of the forest?'),
  ('0363a08e-73b6-500a-a394-0a7c574b2115', '0cb74b0b-6eab-5c36-a75e-e1362de5c159', NULL, 3, 3, 'Shall wood be taken of it to make any work? or will men take a pin of it to hang any vessel thereon?'),
  ('92bd978b-eb87-5587-a1f2-1fedead70371', '0cb74b0b-6eab-5c36-a75e-e1362de5c159', NULL, 4, 4, 'Behold, it is cast into the fire for fuel; the fire has devoured both its ends, and its midst is burned: is it profitable for any work?'),
  ('6091dce5-371e-5d17-ab85-cc780a31f3dc', '0cb74b0b-6eab-5c36-a75e-e1362de5c159', NULL, 5, 5, 'Behold, when it was whole, it was meet for no work: how much less, when the fire has devoured it, and it is burned, shall it yet be meet for any work!'),
  ('27faf9a3-26de-5f30-ac3a-120282e7974d', '0cb74b0b-6eab-5c36-a75e-e1362de5c159', NULL, 6, 6, 'Therefore thus says the Lord Yahweh: As the vine tree among the trees of the forest, which I have given to the fire for fuel, so will I give the inhabitants of Jerusalem.'),
  ('10c2a5db-258e-5960-af3c-bf85f7aa753f', '0cb74b0b-6eab-5c36-a75e-e1362de5c159', NULL, 7, 7, 'I will set my face against them; they shall go forth from the fire, but the fire shall devour them; and you shall know that I am Yahweh, when I set my face against them.'),
  ('74f3c781-034f-59ed-af64-93aa64da432a', '0cb74b0b-6eab-5c36-a75e-e1362de5c159', NULL, 8, 8, 'I will make the land desolate, because they have committed a trespass, says the Lord Yahweh.'),
  ('bc476c9b-9b09-5acf-a57f-04202823bf49', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 1, 1, 'Again the word of Yahweh came to me, saying,'),
  ('f10e63b7-991d-5197-aa76-e965de2fcf2d', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 2, 2, 'Son of man, cause Jerusalem to know her abominations;'),
  ('0f9fc9cb-62c1-56da-a179-b401a574e6d8', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 3, 3, 'and say, Thus says the Lord Yahweh to Jerusalem: Your birth and your birth is of the land of the Canaanite; the Amorite was your father, and your mother was a Hittite.'),
  ('f9b9dfbf-dfe1-588c-aa7c-85d6d3729cf5', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 4, 4, 'As for your birth, in the day you were born your navel was not cut, neither were you washed in water to cleanse you; you weren''t salted at all, nor swaddled at all.'),
  ('4eea3606-0518-5cbe-a40d-8e4de99c68ea', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 5, 5, 'No eye pitied you, to do any of these things to you, to have compassion on you; but you were cast out in the open field, for that your person was abhorred, in the day that you were born.'),
  ('3228ab26-3e91-505b-aa8b-c839e86a9c40', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 6, 6, 'When I passed by you, and saw you wallowing in your blood, I said to you, [Though you are] in your blood, live; yes, I said to you, [Though you are] in your blood, live.'),
  ('49fff6ae-1a27-556f-ab0a-224c65fac365', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 7, 7, 'I caused you to multiply as that which grows in the field, and you increased and grew great, and you attained to excellent ornament; your breasts were fashioned, and your hair was grown; yet you were naked and bare.'),
  ('181766ea-41de-5fed-a01a-2ae974ffc8ee', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 8, 8, 'Now when I passed by you, and looked at you, behold, your time was the time of love; and I spread my skirt over you, and covered your nakedness: yes, I swore to you, and entered into a covenant with you, says the Lord Yahweh, and you became mine.'),
  ('c393d072-f1a7-5981-a4a7-d223c6a220a6', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 9, 9, 'Then washed I you with water; yes, I thoroughly washed away your blood from you, and I anointed you with oil.'),
  ('c453d8e3-8f25-588f-ab29-7fa0c6ef8388', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 10, 10, 'I clothed you also with embroidered work, and shod you with sealskin, and I dressed you about with fine linen, and covered you with silk.'),
  ('339685a0-1298-5fa3-aeed-57085b9c3c26', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 11, 11, 'I decked you with ornaments, and I put bracelets on your hands, and a chain on your neck.'),
  ('261b8d1c-e227-57a5-aff3-3085f72bd8d8', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 12, 12, 'I put a ring on your nose, and earrings in your ears, and a beautiful crown on your head.'),
  ('21d5fdcf-b274-5146-ad2b-363b8252a2fd', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 13, 13, 'Thus you were decked with gold and silver; and your clothing was of fine linen, and silk, and embroidered work; you ate fine flour, and honey, and oil; and you were exceeding beautiful, and you prospered to royal estate.'),
  ('316453ea-60c4-597c-ad0d-aa1cece8f2d5', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 14, 14, 'Your renown went forth among the nations for your beauty; for it was perfect, through my majesty which I had put on you, says the Lord Yahweh.'),
  ('e1556af5-319a-577b-a9b5-7eb988cc82fb', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 15, 15, 'But you trusted in your beauty, and played the prostitute because of your renown, and poured out your prostitution on everyone who passed by; his it was.'),
  ('6b1b5e6b-f6bb-5128-a8f6-0477244cebcc', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 16, 16, 'You took of your garments, and made for yourselves high places decked with various colors, and played the prostitute on them: [the like things] shall not come, neither shall it be [so].'),
  ('d8af2a24-1860-561a-a4aa-c589fe1da46e', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 17, 17, 'You also took your beautiful jewels of my gold and of my silver, which I had given you, and made for yourself images of men, and played the prostitute with them;'),
  ('124d313d-101c-519a-a6d4-6c192c8ef268', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 18, 18, 'and you took your embroidered garments, and covered them, and did set my oil and my incense before them.'),
  ('c650a7ee-fa00-5b80-acd5-766cc1da0af4', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 19, 19, 'My bread also which I gave you, fine flour, and oil, and honey, with which I fed you, you even set it before them for a pleasant aroma; and [thus] it was, says the Lord Yahweh.'),
  ('012e2267-819e-5892-a3c7-72c1eb76ef60', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 20, 20, 'Moreover you have taken your sons and your daughters, whom you have borne to me, and you have sacrificed these to them to be devoured. Was your prostitution a small matter,'),
  ('1bed6f9b-b2e1-5b27-ab5d-e2461f33c714', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 21, 21, 'that you have slain my children, and delivered them up, in causing them to pass through [the fire] to them?'),
  ('46202cfb-20d6-56ea-a96d-55011a945269', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 22, 22, 'In all your abominations and your prostitution you have not remembered the days of your youth, when you were naked and bare, and were wallowing in your blood.'),
  ('0d46dc94-76fa-52c9-af36-fbc8007eaa8a', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 23, 23, 'It has happened after all your wickedness, (woe, woe to you! says the Lord Yahweh),'),
  ('a6bedfef-51bf-52ed-aef0-43a058033d6a', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 24, 24, 'that you have built for yourselves a vaulted place, and have made yourselves a lofty place in every street.'),
  ('2769d466-e134-5ab4-ab7c-6efcf6b15518', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 25, 25, 'You have built your lofty place at the head of every way, and have made your beauty an abomination, and have opened your feet to everyone who passed by, and multiplied your prostitution.'),
  ('14de9171-863b-57c7-aa04-fe7b137711a6', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 26, 26, 'You have also committed sexual immorality with the Egyptians, your neighbors, great of flesh; and have multiplied your prostitution, to provoke me to anger.'),
  ('23d37791-95ad-579f-af21-7f00a26470f0', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 27, 27, 'See therefore, I have stretched out my hand over you, and have diminished your ordinary [food], and delivered you to the will of those who hate you, the daughters of the Philistines, who are ashamed of your lewd way.'),
  ('80c1860a-5e2b-5915-afcd-54dad7b37b54', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 28, 28, 'You have played the prostitute also with the Assyrians, because you were insatiable; yes, you have played the prostitute with them, and yet you weren''t satisfied.'),
  ('b52e33b3-b077-5e13-a4eb-a84d5186780e', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 29, 29, 'You have moreover multiplied your prostitution to the land of merchants, to Chaldea; and yet you weren''t satisfied with this.'),
  ('5df8c790-941f-5451-a5e0-f03bb2cd77ad', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 30, 30, 'How weak is your heart, says the Lord Yahweh, since you do all these things, the work of an impudent prostitute;'),
  ('ebbc9ea6-5884-5e74-a483-784b3572dc5f', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 31, 31, 'in that you build your vaulted place at the head of every way, and make your lofty place in every street, and have not been as a prostitute, in that you scorn pay.'),
  ('834e27c1-0e42-59bc-af62-7ef9b70a2ff1', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 32, 32, 'A wife who commits adultery! who takes strangers instead of her husband!'),
  ('333d5b89-c5db-55ae-a127-405a2ab1210b', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 33, 33, 'They give gifts to all prostitutes; but you give your gifts to all your lovers, and bribe them, that they may come to you on every side for your prostitution.'),
  ('18cb78dc-a6e8-53a5-aa93-cc6f3b333f64', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 34, 34, 'You are different from [other] women in your prostitution, in that no one follows you to play the prostitute; and whereas you give hire, and no hire is given to you, therefore you are different.'),
  ('d432aff1-094e-5794-a4b4-d1ae6da304f4', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 35, 35, 'Therefore, prostitute, hear the word of Yahweh:'),
  ('d006c320-bb10-5464-aae0-5eae25fd1dae', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 36, 36, 'Thus says the Lord Yahweh, Because your filthiness was poured out, and your nakedness uncovered through your prostitution with your lovers; and because of all the idols of your abominations, and for the blood of your children, that you gave to them;'),
  ('a0085bbd-d463-52ff-a589-cf02dcb22bdd', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 37, 37, 'therefore see, I will gather all your lovers, with whom you have taken pleasure, and all those who you have loved, with all those who you have hated; I will even gather them against you on every side, and will uncover your nakedness to them, that they may see all your nakedness.'),
  ('f67b7dad-f19d-5fbc-ab68-dc2e34102011', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 38, 38, 'I will judge you, as women who break wedlock and shed blood are judged; and I will bring on you the blood of wrath and jealousy.'),
  ('bad23299-4711-5e48-aa5b-5d8fdd15b581', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 39, 39, 'I will also give you into their hand, and they shall throw down your vaulted place, and break down your lofty places; and they shall strip you of your clothes, and take your beautiful jewels; and they shall leave you naked and bare.'),
  ('b01612e8-43a0-5527-a5e4-2bafab53bc22', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 40, 40, 'They shall also bring up a company against you, and they shall stone you with stones, and thrust you through with their swords.'),
  ('e0d63dfc-839d-59a1-ad5b-9c0d5edecf9d', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 41, 41, 'They shall burn your houses with fire, and execute judgments on you in the sight of many women; and I will cause you to cease from playing the prostitute, and you shall also give no hire any more.'),
  ('76f13e42-b314-5b63-a6bf-de47b056ff0d', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 42, 42, 'So will I cause my wrath toward you to rest, and my jealousy shall depart from you, and I will be quiet, and will be no more angry.'),
  ('59478f15-35d0-5520-a4f4-bf43d5662df4', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 43, 43, 'Because you have not remembered the days of your youth, but have raged against me in all these things; therefore, behold, I also will bring your way on your head, says the Lord Yahweh: and you shall not commit this lewdness with all your abominations.'),
  ('6bbc1b02-b9c8-587f-a21d-b4c604032b1e', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 44, 44, 'Behold, everyone who uses proverbs shall use [this] proverb against you, saying, As is the mother, so is her daughter.'),
  ('ad4db850-a0f7-5692-ad03-8413cffeb64f', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 45, 45, 'You are the daughter of your mother, who loathes her husband and her children; and you are the sister of your sisters, who loathed their husbands and their children: your mother was a Hittite, and your father an Amorite.'),
  ('2aa4d980-3ec2-52d8-aa17-15252a91e370', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 46, 46, 'Your elder sister is Samaria, who dwells at your left hand, she and her daughters; and your younger sister, who dwells at your right hand, is Sodom and her daughters.'),
  ('150e668f-fa74-5e19-a957-32c6aa5114ad', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 47, 47, 'Yet have you not walked in their ways, nor done after their abominations; but, as [if that were] a very little [thing], you were more corrupt than they in all your ways.'),
  ('e80b2288-00da-5ceb-af3a-fd57f3cf0c62', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 48, 48, 'As I live, says the Lord Yahweh, Sodom your sister has not done, she nor her daughters, as you have done, you and your daughters.'),
  ('4f2c3746-959c-598c-ae05-b66862cdda79', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 49, 49, 'Behold, this was the iniquity of your sister Sodom: pride, fullness of bread, and prosperous ease was in her and in her daughters; neither did she strengthen the hand of the poor and needy.'),
  ('4f032280-f861-5438-af9d-a02ab090b1a3', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 50, 50, 'They were haughty, and committed abomination before me: therefore I took them away as I saw [good].'),
  ('bf256a74-2a61-5922-a236-fa0d7610d120', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 51, 51, 'Neither has Samaria committed half of your sins; but you have multiplied your abominations more than they, and have justified your sisters by all your abominations which you have done.'),
  ('fd1175af-b78c-554d-ad68-18436df075b5', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 52, 52, 'You also, bear you your own shame, in that you have given judgment for your sisters; through your sins that you have committed more abominable than they, they are more righteous that you: yes, be also confounded, and bear your shame, in that you have justified your sisters.'),
  ('0df15220-570d-5394-add5-8a34ed218d3a', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 53, 53, 'I will turn again their captivity, the captivity of Sodom and her daughters, and the captivity of Samaria and her daughters, and the captivity of your captives in the midst of them;'),
  ('1da7f729-206c-5f65-afa6-5615a8f9a0d1', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 54, 54, 'that you may bear your own shame, and may be ashamed because of all that you have done, in that you are a comfort to them.'),
  ('9eade7bd-45a4-56f3-ae2d-5198571a5f39', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 55, 55, 'Your sisters, Sodom and her daughters, shall return to their former estate; and Samaria and her daughters shall return to their former estate; and you and your daughters shall return to your former estate.'),
  ('043a8632-235c-59e5-ad7c-55f3aa2709ed', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 56, 56, 'For your sister Sodom was not mentioned by your mouth in the day of your pride,'),
  ('d06e3ce2-f054-5092-ac15-402a68666bc6', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 57, 57, 'before your wickedness was uncovered, as at the time of the reproach of the daughters of Syria, and of all who are around her, the daughters of the Philistines, who do despite to you all around.'),
  ('526949d5-8ebb-5d3a-a641-2d8fa7df1b2d', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 58, 58, 'You have borne your lewdness and your abominations, says Yahweh.'),
  ('2c0e01c6-5a9f-5540-ae71-ff8342ae21e2', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 59, 59, 'For thus says the Lord Yahweh: I will also deal with you as you have done, who have despised the oath in breaking the covenant.'),
  ('c7bab4d3-1ea8-56af-ad47-70cf69d78eda', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 60, 60, 'Nevertheless I will remember my covenant with you in the days of your youth, and I will establish to you an everlasting covenant.'),
  ('e5e50558-2c37-5713-a74f-7c6ada8b1edd', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 61, 61, 'Then you shall remember your ways, and be ashamed, when you shall receive your sisters, your elder [sisters] and your younger; and I will give them to you for daughters, but not by your covenant.'),
  ('2dd65611-b4bc-5c94-a990-72086d8038e1', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 62, 62, 'I will establish my covenant with you; and you shall know that I am Yahweh;'),
  ('c31d05aa-830e-5d35-aecf-bbb4dd6cbfb4', '31e13e11-a5f8-5fc4-a7fd-78173375d34e', NULL, 63, 63, 'that you may remember, and be confounded, and never open your mouth any more, because of your shame, when I have forgiven you all that you have done, says the Lord Yahweh.'),
  ('27160408-d34f-5dee-a9cf-4aaff6ebd487', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 1, 1, 'The word of Yahweh came to me, saying,'),
  ('d4b5a69a-28b8-502e-a3de-0f6c5d5b4721', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 2, 2, 'Son of man, put forth a riddle, and speak a parable to the house of Israel;'),
  ('b63281e0-a56e-5fe6-accf-8bda0d75d543', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 3, 3, 'and say, Thus says the Lord Yahweh: A great eagle with great wings and long feathers, full of feathers, which had various colors, came to Lebanon, and took the top of the cedar:'),
  ('4e25cb69-fcd8-5976-a1f4-df3b096c842e', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 4, 4, 'he cropped off the topmost of the young twigs of it, and carried it to a land of traffic; he set it in a city of merchants.'),
  ('af0a14dc-afcf-5751-a04d-bce349934865', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 5, 5, 'He took also of the seed of the land, and planted it in a fruitful soil; he placed it beside many waters; he set it as a willow tree.'),
  ('926ff3a3-d602-51ab-a004-7c929dd401a4', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 6, 6, 'It grew, and became a spreading vine of low stature, whose branches turned toward him, and its roots were under him: so it became a vine, and brought forth branches, and shot forth sprigs.'),
  ('b1115c20-0360-5dee-aeba-7329ec6a71fb', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 7, 7, 'There was also another great eagle with great wings and many feathers: and behold, this vine did bend its roots toward him, and shot forth its branches toward him, from the beds of its plantation, that he might water it.'),
  ('9f7914bd-9587-515f-af31-8de53e34d734', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 8, 8, 'It was planted in a good soil by many waters, that it might bring forth branches, and that it might bear fruit, that it might be a goodly vine.'),
  ('18c1c02e-4837-5e32-ab5c-dd9390fd929e', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 9, 9, 'Say, Thus says the Lord Yahweh: Shall it prosper? shall he not pull up its roots, and cut off its fruit, that it may wither; that all its fresh springing leaves may wither? and not by a strong arm or many people can it be raised from its roots.'),
  ('bd6b45ab-1b19-5ff2-afc1-eb469ed208de', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 10, 10, 'Yes, behold, being planted, shall it prosper? shall it not utterly wither, when the east wind touches it? it shall wither in the beds where it grew.'),
  ('0c7951ad-02ab-57c1-a4d3-372edbbb3cf6', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 11, 11, 'Moreover the word of Yahweh came to me, saying,'),
  ('e5e961bc-6929-521c-a0b7-cd452722db51', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 12, 12, 'Say now to the rebellious house, Don''t you know what these things mean? tell them, Behold, the king of Babylon came to Jerusalem, and took its king, and its princes, and brought them to him to Babylon:'),
  ('59efcef8-b936-5135-a215-d8f5a4b6d522', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 13, 13, 'and he took of the seed royal, and made a covenant with him; he also brought him under an oath, and took away the mighty of the land;'),
  ('6d280faf-729a-599c-a7a9-4321e3b1452c', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 14, 14, 'that the kingdom might be base, that it might not lift itself up, but that by keeping his covenant it might stand.'),
  ('f9db78d4-ed5b-5956-ab3d-a52112812ef9', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 15, 15, 'But he rebelled against him in sending his ambassadors into Egypt, that they might give him horses and many people. Shall he prosper? shall he escape who does such things? shall he break the covenant, and yet escape?'),
  ('21e73d5f-7991-5469-a7a6-2351ddc52f2d', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 16, 16, 'As I live, says the Lord Yahweh, surely in the place where the king dwells who made him king, whose oath he despised, and whose covenant he broke, even with him in the midst of Babylon he shall die.'),
  ('b937ed14-9a9d-53bb-a8b4-4ddff1760204', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 17, 17, 'Neither shall Pharaoh with his mighty army and great company help him in the war, when they cast up mounds and build forts, to cut off many persons.'),
  ('22265420-baac-5216-ad7f-c3786f7756f4', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 18, 18, 'For he has despised the oath by breaking the covenant; and behold, he had given his hand, and yet has done all these things; he shall not escape.'),
  ('9de40c7a-3b06-578d-a958-a2eb002129cd', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 19, 19, 'Therefore thus says the Lord Yahweh: As I live, surely my oath that he has despised, and my covenant that he has broken, I will even bring it on his own head.'),
  ('bdcf5c1c-3a48-50d0-a1d5-385201d78757', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 20, 20, 'I will spread my net on him, and he shall be taken in my snare, and I will bring him to Babylon, and will enter into judgment with him there for his trespass that he has trespassed against me.'),
  ('657bc178-ca79-5135-ae44-fc28aca98cc9', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 21, 21, 'All his fugitives in all his bands shall fall by the sword, and those who remain shall be scattered toward every wind: and you shall know that I, Yahweh, have spoken it.'),
  ('76802cac-2157-52fa-aff3-7a2720404fe7', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 22, 22, 'Thus says the Lord Yahweh: I will also take of the lofty top of the cedar, and will set it; I will crop off from the topmost of its young twigs a tender one, and I will plant it on a high and lofty mountain:'),
  ('948598e1-238d-51ac-a28f-83a1df24eb3d', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 23, 23, 'in the mountain of the height of Israel will I plant it; and it shall bring forth boughs, and bear fruit, and be a goodly cedar: and under it shall dwell all birds of every wing; in the shade of its branches shall they dwell.'),
  ('19dd499f-1001-53e8-a416-bbb61f2744a0', '9e3fd75c-c47f-5e9e-ae2c-faf4c15f1b15', NULL, 24, 24, 'All the trees of the field shall know that I, Yahweh, have brought down the high tree, have exalted the low tree, have dried up the green tree, and have made the dry tree to flourish; I, Yahweh, have spoken and have done it.'),
  ('12a3ff61-77a9-5a8a-a27a-3ce2c0bb8470', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 1, 1, 'The word of Yahweh came to me again, saying,'),
  ('47933e1e-5287-5fab-aa05-3734679a7c13', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 2, 2, 'What do you mean, that you use this proverb concerning the land of Israel, saying, The fathers have eaten sour grapes, and the children''s teeth are set on edge?'),
  ('b8302485-b156-5863-a94c-022abfb33ab9', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 3, 3, 'As I live, says the Lord Yahweh, you shall not have [occasion] any more to use this proverb in Israel.'),
  ('5701dcae-5f23-5e3d-a9be-e8b34e2ed749', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 4, 4, 'Behold, all souls are mine; as the soul of the father, so also the soul of the son is mine: the soul who sins, he shall die.'),
  ('470a1a77-ed94-5522-a255-2fb77b642523', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 5, 5, 'But if a man is just, and does that which is lawful and right,'),
  ('d53bb040-2289-515f-a5e0-ce6243debb55', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 6, 6, 'and has not eaten on the mountains, neither has lifted up his eyes to the idols of the house of Israel, neither has defiled his neighbor''s wife, neither has come near to a woman in her impurity,'),
  ('8dbc2d72-9cda-5ef5-a61b-de72d0f83810', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 7, 7, 'and has not wronged any, but has restored to the debtor his pledge, has taken nothing by robbery, has given his bread to the hungry, and has covered the naked with a garment;'),
  ('c545511c-369c-5b61-a736-bf372be35ed3', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 8, 8, 'he who has not given forth on interest, neither has taken any increase, who has withdrawn his hand from iniquity, has executed true justice between man and man,'),
  ('0efef692-49bb-56aa-a462-96448023e90c', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 9, 9, 'has walked in my statutes, and has kept my ordinances, to deal truly; he is just, he shall surely live, says the Lord Yahweh.'),
  ('4664bbcd-225e-5707-ae25-ffe2fa7ca5f3', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 10, 10, 'If he fathers a son who is a robber, a shedder of blood, and who does any one of these things,'),
  ('4d10ca3b-3e8f-53ff-a2a1-d87f8f2eeb99', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 11, 11, 'and who does not any of those [duties], but even has eaten on the mountains, and defiled his neighbor''s wife,')
